import { Handler } from "@netlify/functions";
import { generateObject } from "ai";
import { createClient, type SupabaseClient } from "@supabase/supabase-js";
import { resolvePromptWithFallback } from "../../src/shared/config/prompts/prompt-resolver.service";
import { GLOBAL_VIDEO_DURATION_PROMPTS } from "../../src/shared/config/prompts/global-video-duration.prompts";
import {
  INSTRUCTIONAL_PLAN_CONTEXT_PROMPT_CODE,
  INSTRUCTIONAL_PLAN_SYSTEM_PROMPT_CODE,
  instructionalPlanContextPromptDefault,
  renderPromptTemplate,
} from "../../src/shared/config/prompts/pipeline.prompts";
import {
  createServiceRoleClient,
  getSupabaseServiceKey,
  getSupabaseUrl,
  resolveAiModel,
  resolveModelSetting,
} from "./shared/bootstrap";
import { getErrorMessage } from "./shared/errors";
import { backgroundGuardFailureResponse, methodNotAllowedResponse, parseVerifiedBackgroundBody } from "./shared/http";
import {
  resolveArtifactVideoDurationPolicy,
  type VideoDurationPolicy,
} from "../../src/domains/video-duration/video-duration-policy";
import { applyVideoDurationPolicyToPlan } from "../../src/domains/video-duration/video-duration-plan";
import {
  canIteratePlan,
  getPlanIterationCount,
  getNextPlanIteration,
  getPreviousPlanIteration,
  PLAN_MAX_ITERATIONS,
} from "../../src/domains/plan/lib/plan-iteration";
import {
  GeneratedInstructionalPlanSchema,
  type GeneratedInstructionalPlanBlocker,
  type GeneratedInstructionalPlanLesson,
} from "../../src/domains/plan/lib/instructional-plan-generation.schema";
import { buildInstructionalPlanContextPrompt } from "../../src/domains/plan/lib/instructional-plan-prompt";
import { getInstructionalPlanCompletenessIssues } from "../../src/domains/plan/lib/plan-completeness";
import { alignPlanLessonsById } from "../../src/domains/plan/lib/plan-lesson-identity";
import { readSyllabusWithOrigin } from "../../src/domains/syllabus/services/syllabus-workflow-read";
import { recordAiFailure, recordAiSdkUsage } from "../../src/shared/ai/usage-telemetry";

type BackgroundSupabaseClient = SupabaseClient;
type GeneratedLessonPlan = GeneratedInstructionalPlanLesson;
type GeneratedBlocker = GeneratedInstructionalPlanBlocker;

interface RequestBody {
  artifactId?: string;
  customPrompt?: string;
  iterationInstructions?: string;
  iterationNumber?: number;
  organizationId?: string | null;
  useCustomPrompt?: boolean;
}

interface ArtifactRecord {
  generation_metadata?: unknown;
  idea_central: string;
  nombres?: string[] | null;
  organization_id?: string | null;
}

interface SyllabusLessonRecord {
  topics?: string[];
  estimated_minutes?: number | null;
  id: string;
  objective_specific?: string | null;
  title: string;
}

interface SyllabusModuleRecord {
  id?: string | null;
  lessons?: SyllabusLessonRecord[] | null;
  title: string;
}

interface SyllabusRecord {
  modules?: unknown;
  state?: string;
  input_mode?: string;
  content_version?: number;
}

function createBackgroundSupabaseClient() {
  return createClient(getSupabaseUrl(), getSupabaseServiceKey());
}

function normalizeSyllabusModules(rawModules: unknown): SyllabusModuleRecord[] {
  if (!Array.isArray(rawModules)) {
    throw new Error("Syllabus modules is empty or not an array.");
  }

  const modules = rawModules as SyllabusModuleRecord[];
  if (modules.length === 0) {
    throw new Error("Syllabus modules is empty or not an array.");
  }

  return modules;
}

function renderLessonsText(lessons: SyllabusLessonRecord[]) {
  return lessons
    .map(
      (lesson, index) =>
        `${index + 1}. ID: ${lesson.id}\n   Leccion: ${lesson.title}\n   Temas obligatorios: ${(lesson.topics || []).join("; ")}\n   OA Original: ${lesson.objective_specific || "N/A"}\n   Tiempo total estimado de aprendizaje: ${lesson.estimated_minutes || "N/A"} minutos`,
    )
    .join("\n\n");
}

async function prepareInstructionalPlanRecord(
  supabase: BackgroundSupabaseClient,
  artifactId: string,
  reservedIteration?: number,
) {
  const { data: existingPlan, error: lookupError } = await supabase
    .from("instructional_plans")
    .select("id, iteration_count, lesson_plans")
    .eq("artifact_id", artifactId)
    .maybeSingle();

  if (lookupError) {
    throw lookupError;
  }

  const currentIteration = getPlanIterationCount(
    existingPlan?.iteration_count,
    Array.isArray(existingPlan?.lesson_plans) &&
      existingPlan.lesson_plans.length > 0,
  );
  const nextIteration =
    reservedIteration === undefined
      ? getNextPlanIteration(currentIteration)
      : reservedIteration;

  if (
    !Number.isInteger(nextIteration) ||
    nextIteration < 1 ||
    nextIteration > PLAN_MAX_ITERATIONS
  ) {
    throw new Error("Numero de iteracion del plan invalido.");
  }

  if (reservedIteration === undefined && !canIteratePlan(currentIteration)) {
    throw new Error(
      `El plan instruccional alcanzo el limite de ${PLAN_MAX_ITERATIONS} iteraciones.`,
    );
  }

  if (existingPlan) {
    let reservationQuery = supabase
      .from("instructional_plans")
      .update({
        validation: null,
        last_error: null,
        state: "STEP_PROCESSING",
        iteration_count: nextIteration,
        updated_at: new Date().toISOString(),
      })
      .eq("id", existingPlan.id);

    if (reservedIteration === undefined) {
      reservationQuery = reservationQuery.eq(
        "iteration_count",
        existingPlan.iteration_count || 0,
      );
    } else {
      reservationQuery = reservationQuery.eq(
        "iteration_count",
        reservedIteration,
      );
    }

    const { data: preparedPlan, error: reservationError } =
      await reservationQuery.select("id").maybeSingle();

    if (reservationError) {
      throw reservationError;
    }
    if (!preparedPlan) {
      throw new Error("Otra iteracion del plan fue iniciada al mismo tiempo.");
    }
    return nextIteration;
  }

  const { error: insertError } = await supabase
    .from("instructional_plans")
    .insert({
      artifact_id: artifactId,
      lesson_plans: [],
      blockers: [],
      validation: null,
      last_error: null,
      state: "STEP_PROCESSING",
      iteration_count: nextIteration,
    });

  if (insertError) {
    throw insertError;
  }

  return nextIteration;
}

async function generateModulePlans(params: {
  artifact: ArtifactRecord;
  contextPromptTemplate: string;
  module: SyllabusModuleRecord;
  moduleIndex: number;
  modelName: string;
  systemPromptTemplate: string;
  temperature: number;
  videoDurationPolicy: VideoDurationPolicy;
  artifactId: string;
  attempt: number;
  organizationId?: string | null;
  supabase: SupabaseClient;
}) {
  const {
    artifact,
    contextPromptTemplate,
    module,
    moduleIndex,
    modelName,
    systemPromptTemplate,
    temperature,
    videoDurationPolicy,
    artifactId,
    attempt,
    organizationId,
    supabase,
  } = params;
  const lessons = module.lessons || [];
  const lessonsText = renderLessonsText(lessons);
  const promptVariables = {
    courseName: artifact.nombres?.[0] || artifact.idea_central,
    currentModule: module.title,
    ideaCentral: artifact.idea_central,
    lessonCount: lessons.length,
    lessonsText,
  };
  const finalSystemPrompt = renderPromptTemplate(
    systemPromptTemplate,
    promptVariables,
  );
  const finalContextPrompt = renderPromptTemplate(
    contextPromptTemplate,
    promptVariables,
  );

  const startedAt = Date.now();
  let result;
  try {
    result = await generateObject({
      model: resolveAiModel(modelName),
      schema: GeneratedInstructionalPlanSchema,
      prompt: `${finalSystemPrompt}\n\nMODULO ACTUAL: ${module.title}\n${finalContextPrompt}`,
      temperature,
    });
  } catch (error) {
    await recordAiFailure({
      context: {
        artifactId,
        attempt,
        operation: "generate_instructional_plan_module",
        organizationId,
        pipelineStep: "PLAN",
      },
      error,
      model: modelName,
      provider: modelName.startsWith("gemini-") ? "gemini" : "openai",
      startedAt,
      supabase,
    });
    throw error;
  }
  await recordAiSdkUsage({
    context: {
      artifactId,
      attempt,
      operation: "generate_instructional_plan_module",
      organizationId,
      pipelineStep: "PLAN",
    },
    model: modelName,
    startedAt,
    supabase,
    usage: result.usage,
  });

  const identifiedLessons = lessons.map((lesson, lessonIndex) => ({ ...lesson, id: lesson.id || `lesson-${moduleIndex + 1}-${lessonIndex + 1}` }));
  const orderedPlans = alignPlanLessonsById(identifiedLessons, result.object.lesson_plans);
  const moduleLessonPlans = orderedPlans.map((lessonPlan, lessonIndex) => {
    const syllabusLesson = lessons[lessonIndex];
    return {
      ...lessonPlan,
      // IDs are pipeline keys, not generative content. Preserve the syllabus
      // identity even if the model emits the literal string "undefined".
      lesson_id:
        syllabusLesson?.id ||
        `lesson-${moduleIndex + 1}-${lessonIndex + 1}`,
      lesson_title: syllabusLesson?.title || lessonPlan.lesson_title,
      module_id: module.id || `mod-${moduleIndex}`,
      module_title: module.title,
      module_index: moduleIndex,
    };
  }) as GeneratedLessonPlan[];
  const lessonPlans = applyVideoDurationPolicyToPlan(
    moduleLessonPlans,
    videoDurationPolicy,
  ) as GeneratedLessonPlan[];

  return {
    blockers: result.object.blockers as GeneratedBlocker[],
    lessonPlans,
  };
}

export const handler: Handler = async (event) => {
  if (event.httpMethod !== "POST") {
    return methodNotAllowedResponse();
  }

  let artifactId: string | undefined;
  let activeIteration: number | undefined;
  let supabase: BackgroundSupabaseClient | undefined;
  let body: RequestBody;
  try {
    body = await parseVerifiedBackgroundBody(event);
  } catch (error) {
    return backgroundGuardFailureResponse(error);
  }

  try {
    artifactId = body.artifactId;
    activeIteration = body.iterationNumber;

    if (!artifactId) {
      return { statusCode: 400, body: "Missing required fields" };
    }

    console.log(
      `[Background Job] Starting Instructional Plan generation for artifacts/${artifactId}`,
    );

    supabase = createBackgroundSupabaseClient();

    const [
      { data: rawArtifact, error: artifactError },
      { data: rawSyllabus, error: syllabusError },
    ] = await Promise.all([
      supabase.from("artifacts").select("*").eq("id", artifactId).single(),
      readSyllabusWithOrigin(supabase, artifactId, "modules,state"),
    ]);

    if (artifactError || !rawArtifact) {
      throw new Error(`Artifact not found: ${artifactError?.message}`);
    }

    if (rawArtifact.organization_id !== (body.organizationId ?? null)) {
      return { statusCode: 404, body: "Artifact not found" };
    }

    if (syllabusError) {
      throw new Error(`Syllabus not found: ${syllabusError.message}`);
    }

    const syllabusRecord = (rawSyllabus || null) as SyllabusRecord | null;
    if (!syllabusRecord?.modules) {
      throw new Error("Syllabus record has no modules.");
    }
    if (syllabusRecord.input_mode === "PROVIDED_SYLLABUS" && syllabusRecord.state !== "STEP_APPROVED") {
      throw new Error("Aprueba el temario importado antes de generar el plan.");
    }

    const artifact = rawArtifact as ArtifactRecord;
    const videoDurationPolicy = resolveArtifactVideoDurationPolicy(
      artifact.generation_metadata,
    );
    const syllabusModules = normalizeSyllabusModules(syllabusRecord.modules);

    const promptOrganizationId = artifact.organization_id || null;
    const [systemPromptTemplate, contextPromptTemplateFromDb] =
      await Promise.all([
        resolvePromptWithFallback(
          supabase,
          INSTRUCTIONAL_PLAN_SYSTEM_PROMPT_CODE,
          GLOBAL_VIDEO_DURATION_PROMPTS.INSTRUCTIONAL_PLAN_SYSTEM,
          promptOrganizationId,
        ),
        resolvePromptWithFallback(
          supabase,
          INSTRUCTIONAL_PLAN_CONTEXT_PROMPT_CODE,
          instructionalPlanContextPromptDefault,
          promptOrganizationId,
        ),
      ]);

    const contextPromptTemplate = buildInstructionalPlanContextPrompt({
      configuredPrompt: contextPromptTemplateFromDb || instructionalPlanContextPromptDefault,
      customPrompt: body.customPrompt,
      iterationInstructions: body.iterationInstructions,
      useCustomPrompt: body.useCustomPrompt,
    });

    const iterationNumber = await prepareInstructionalPlanRecord(
      supabase,
      artifactId,
      body.iterationNumber,
    );
    activeIteration = iterationNumber;
    if (syllabusRecord.input_mode === "PROVIDED_SYLLABUS") {
      const { error: versionError } = await supabase.from("instructional_plans")
        .update({ syllabus_content_version: syllabusRecord.content_version }).eq("artifact_id", artifactId).eq("iteration_count", iterationNumber);
      if (versionError) throw versionError;
    }

    const modelConfig = await resolveModelSetting(
      createServiceRoleClient(),
      "INSTRUCTIONAL_PLAN",
      {
        model: "gemini-3.5-flash",
        fallbackModel: "gemini-2.5-flash",
        temperature: 0.7,
        thinkingLevel: "medium",
      },
      promptOrganizationId,
    );
    const modelName = modelConfig.model;
    console.log(
      `[Background Job] Starting incremental generation with ${modelName}`,
    );

    let allGeneratedPlans: GeneratedLessonPlan[] = [];
    let allBlockers: GeneratedBlocker[] = [];

    for (
      let moduleIndex = 0;
      moduleIndex < syllabusModules.length;
      moduleIndex++
    ) {
      const module = syllabusModules[moduleIndex];
      const lessons = module.lessons || [];
      if (lessons.length === 0) {
        continue;
      }

      console.log(
        `[Background Job] Processing Module ${moduleIndex + 1}/${syllabusModules.length}: ${module.title} (${lessons.length} lessons)`,
      );

      try {
        const moduleResult = await generateModulePlans({
          artifactId,
          attempt: iterationNumber,
          artifact,
          contextPromptTemplate,
          module,
          moduleIndex,
          modelName,
          systemPromptTemplate,
          temperature: modelConfig.temperature,
          videoDurationPolicy,
          organizationId: promptOrganizationId,
          supabase,
        });

        allGeneratedPlans = [...allGeneratedPlans, ...moduleResult.lessonPlans];
        allBlockers = [...allBlockers, ...moduleResult.blockers];

        const { data: heartbeat, error: heartbeatError } = await supabase
          .from("instructional_plans")
          .update({ updated_at: new Date().toISOString() })
          .eq("artifact_id", artifactId)
          .eq("state", "STEP_PROCESSING")
          .eq("iteration_count", iterationNumber)
          .select("id")
          .maybeSingle();
        if (heartbeatError) throw heartbeatError;
        if (!heartbeat) {
          throw new Error(
            "La iteracion fue cancelada o reemplazada por una solicitud mas reciente.",
          );
        }

        console.log(
          `[Background Job] Module ${moduleIndex + 1} generated. Total lessons so far: ${allGeneratedPlans.length}`,
        );
      } catch (error: unknown) {
        console.error(
          `[Background Job] Error in module ${moduleIndex + 1}:`,
          error,
        );
        throw new Error(
          `Module ${moduleIndex + 1} generation failed: ${getErrorMessage(error)}`,
        );
      }
    }

    if (allGeneratedPlans.length === 0) {
      throw new Error("La generacion no produjo ninguna leccion para el plan.");
    }
    const completenessIssues = getInstructionalPlanCompletenessIssues(
      syllabusModules,
      allGeneratedPlans,
    );
    if (completenessIssues.length > 0) {
      throw new Error(
        `La generación produjo un plan incompleto: ${completenessIssues.join(" ")}`,
      );
    }

    const { data: completedPlan, error: completionError } = await supabase
      .from("instructional_plans")
      .update({
        lesson_plans: allGeneratedPlans,
        blockers: allBlockers,
        state:
          allBlockers.length > 0
            ? "STEP_WITH_BLOCKERS"
            : "STEP_READY_FOR_REVIEW",
        iteration_count: iterationNumber,
        last_error: null,
        updated_at: new Date().toISOString(),
      })
      .eq("artifact_id", artifactId)
      .eq("state", "STEP_PROCESSING")
      .eq("iteration_count", iterationNumber)
      .select("id")
      .maybeSingle();

    if (completionError) {
      throw completionError;
    }
    if (!completedPlan) {
      throw new Error(
        "La iteracion fue reemplazada por una solicitud mas reciente.",
      );
    }

    console.log(
      `[Background Job] Generation finished successfully for ${allGeneratedPlans.length} lessons.`,
    );
    return {
      statusCode: 200,
      body: JSON.stringify({ success: true, count: allGeneratedPlans.length }),
    };
  } catch (error: unknown) {
    console.error("[Background Job] Fatal Error:", error);

    if (supabase && artifactId) {
      const errorMessage = getErrorMessage(error).slice(0, 500);
      const failureUpdate = {
        state: "STEP_FAILED",
        last_error: {
          code: "INSTRUCTIONAL_PLAN_GENERATION_FAILED",
          message: errorMessage,
          occurred_at: new Date().toISOString(),
        },
        updated_at: new Date().toISOString(),
        ...(activeIteration === undefined
          ? {}
          : { iteration_count: getPreviousPlanIteration(activeIteration) }),
      };
      let failureQuery = supabase
        .from("instructional_plans")
        .update(failureUpdate)
        .eq("artifact_id", artifactId);

      if (activeIteration !== undefined) {
        failureQuery = failureQuery
          .eq("state", "STEP_PROCESSING")
          .eq("iteration_count", activeIteration);
      }

      await failureQuery;
    }

    return {
      statusCode: 500,
      body: JSON.stringify({
        success: false,
        error: getErrorMessage(error),
      }),
    };
  }
};

import { createGoogleGenerativeAI } from "@ai-sdk/google";
import { createOpenAI } from "@ai-sdk/openai";
import { GoogleGenAI } from "@google/genai";
import OpenAI from "openai";
import { createClient } from "@supabase/supabase-js";

import { resolveBackgroundFunctionOrigin } from "../../../src/lib/server/background-function-origin";

function getRequiredEnv(name: string) {
  const value = process.env[name];
  if (!value) {
    throw new Error(`Missing environment variable: ${name}`);
  }

  return value;
}

function getOptionalEnv(name: string) {
  return process.env[name] || null;
}

export function getSupabaseUrl() {
  return getRequiredEnv("NEXT_PUBLIC_SUPABASE_URL");
}

export function getSupabaseAnonKey() {
  return getRequiredEnv("NEXT_PUBLIC_SUPABASE_ANON_KEY");
}

export function hasSupabaseServiceRoleKey() {
  return Boolean(getOptionalEnv("SUPABASE_SERVICE_ROLE_KEY"));
}

export function getSupabaseServiceKey() {
  return getRequiredEnv("SUPABASE_SERVICE_ROLE_KEY");
}

export function getGeminiApiKey() {
  return getOptionalGeminiApiKey() ||
    (() => {
      throw new Error(
        "Missing environment variable: GOOGLE_GENERATIVE_AI_API_KEY or GOOGLE_API_KEY",
      );
    })();
}

export function getOptionalGeminiApiKey() {
  return (
    getOptionalEnv("GOOGLE_GENERATIVE_AI_API_KEY") ||
    getOptionalEnv("GOOGLE_API_KEY")
  );
}

export function getGeminiApiKeySource() {
  if (getOptionalEnv("GOOGLE_GENERATIVE_AI_API_KEY")) {
    return "GOOGLE_GENERATIVE_AI_API_KEY";
  }

  if (getOptionalEnv("GOOGLE_API_KEY")) {
    return "GOOGLE_API_KEY";
  }

  return "missing";
}

export function getSofliaInboxEnv() {
  return {
    key: getRequiredEnv("SOFLIA_INBOX_SUPABASE_KEY"),
    url: getRequiredEnv("SOFLIA_INBOX_SUPABASE_URL"),
  };
}

export function getOpenAiApiKey() {
  return getRequiredEnv("OPENAI_API_KEY");
}

export function getOptionalOpenAiApiKey() {
  return getOptionalEnv("OPENAI_API_KEY");
}

export function getOptionalOpenAiAdminConfig() {
  return {
    adminKey: getOptionalEnv("OPENAI_ADMIN_KEY"),
    organizationId: getOptionalEnv("OPENAI_ORG_ID"),
    projectId: getOptionalEnv("OPENAI_PROJECT_ID"),
  };
}

export function getSofliaAuthSupabaseAnonKey() {
  return getRequiredEnv("SOFLIA_AUTH_SUPABASE_ANON_KEY");
}

export function getCourseforgeJwtSecret() {
  return getRequiredEnv("COURSEFORGE_JWT_SECRET");
}

export function createServiceRoleClient() {
  return createClient(getSupabaseUrl(), getSupabaseServiceKey());
}

export function createGeminiClient() {
  return new GoogleGenAI({ apiKey: getGeminiApiKey() });
}

export function createOpenAiClient() {
  return new OpenAI({ apiKey: getOpenAiApiKey() });
}

export function createGoogleAIProvider() {
  return createGoogleGenerativeAI({
    apiKey: getGeminiApiKey(),
  });
}

export function createOpenAiAIProvider() {
  return createOpenAI({
    apiKey: getOpenAiApiKey(),
  });
}

export function resolveAiModel(modelName: string) {
  const name = modelName.toLowerCase();
  if (name.startsWith("gpt-") || name.startsWith("o1") || name.startsWith("o3")) {
    const openaiProvider = createOpenAiAIProvider();
    return openaiProvider(modelName);
  }

  const googleProvider = createGoogleAIProvider();
  return googleProvider(modelName);
}

export function getFunctionsBaseUrl() {
  return resolveBackgroundFunctionOrigin(process.env);
}

export interface ModelSettingResult {
  model: string;
  fallbackModel: string;
  temperature: number;
  thinkingLevel: string;
}

/**
 * Resuelve la configuración de modelo para un paso del pipeline desde model_settings.
 * Si no hay fila activa para el setting_type, usa los defaults provistos.
 * Patrón centralizado para todos los background jobs.
 */
export async function resolveModelSetting(
  supabase: ReturnType<typeof createServiceRoleClient>,
  settingType: string,
  defaults: ModelSettingResult,
  organizationId?: string | null,
): Promise<ModelSettingResult> {
  const selectActiveSetting = (orgId?: string | null) => {
    let query = supabase
      .from("model_settings")
      .select("model_name, fallback_model, temperature, thinking_level")
      .eq("setting_type", settingType)
      .eq("is_active", true)
      .order("id", { ascending: false })
      .limit(1);

    return orgId ? query.eq("organization_id", orgId) : query.is("organization_id", null);
  };

  const { data: orgData } = organizationId
    ? await selectActiveSetting(organizationId).maybeSingle()
    : { data: null };

  const { data: globalData } = await selectActiveSetting(null).maybeSingle();
  const data = orgData || globalData;

  return {
    model: data?.model_name || defaults.model,
    fallbackModel: data?.fallback_model || defaults.fallbackModel,
    temperature: data?.temperature ?? defaults.temperature,
    thinkingLevel: data?.thinking_level || defaults.thinkingLevel,
  };
}

/**
 * Resolves a required database-backed model configuration.
 * Unlike resolveModelSetting, this function never substitutes code defaults.
 */
export async function resolveConfiguredModelSetting(
  supabase: ReturnType<typeof createServiceRoleClient>,
  settingType: string,
  organizationId?: string | null,
): Promise<ModelSettingResult> {
  const selectActiveSetting = async (orgId?: string | null) => {
    let query = supabase
      .from("model_settings")
      .select("model_name, fallback_model, temperature, thinking_level")
      .eq("setting_type", settingType)
      .eq("is_active", true)
      .order("id", { ascending: false })
      .limit(1);

    query = orgId
      ? query.eq("organization_id", orgId)
      : query.is("organization_id", null);

    const { data, error } = await query.maybeSingle();
    if (error) {
      throw new Error(
        `No se pudo consultar la configuracion de modelo ${settingType}: ${error.message}`,
      );
    }
    return data;
  };

  const organizationSetting = organizationId
    ? await selectActiveSetting(organizationId)
    : null;
  const configuredSetting = organizationSetting || await selectActiveSetting(null);

  if (!configuredSetting?.model_name?.trim()) {
    throw new Error(
      `MODEL_SETTING_NOT_CONFIGURED: Configura un modelo principal activo para ${settingType} en Configuracion antes de ejecutar esta fase.`,
    );
  }

  return {
    model: configuredSetting.model_name.trim(),
    fallbackModel: configuredSetting.fallback_model?.trim() || "",
    temperature: configuredSetting.temperature ?? 0.7,
    thinkingLevel: configuredSetting.thinking_level || "medium",
  };
}

import OpenAI from "openai";
import { readSyllabusWithOrigin } from "../../../../src/domains/syllabus/services/syllabus-workflow-read";
import { PIPELINE_GENERATION_LIMITS, isPermanentProviderFailure } from "../../../../src/lib/pipeline-generation-policy";
import type { SupabaseClient } from "@supabase/supabase-js";
import type { CurationRowInsert } from "../../../../src/shared/types/curation.types";
import {
  buildCourseContextSummary,
  buildLessonsToProcess,
} from "../unified-curation-helpers";
import { calculateLessonCoverage } from "./coverage";
import { searchLessonCandidates } from "./search";
import { normalizeSourceUrl, SOURCE_VALIDATION_TIMEOUT_MS, validateUrlSource } from "./validation";
import type {
  CurationCandidate,
  CurationLesson,
  UrlValidationResult,
} from "./types";

const LESSONS_PER_BATCH = 2;
const DEFAULT_SOURCES_PER_LESSON = 2;
const SEARCH_ATTEMPTS = 3;
const MAX_AUTONOMOUS_ROUNDS = 6;
const MAX_STALLED_ROUNDS = 2;

function wait(milliseconds: number) {
  return new Promise((resolve) => setTimeout(resolve, milliseconds));
}

export async function validateAutomaticCandidates(params: {
  candidates: CurationCandidate[];
  existingNormalizedUrls: Set<string>;
  validate?: (
    url: string,
    options: { existingNormalizedUrls: Iterable<string> },
  ) => Promise<UrlValidationResult>;
  limit?: number;
  shouldContinue?: () => Promise<boolean>;
}) {
  const {
    candidates,
    existingNormalizedUrls,
    validate = validateUrlSource,
    limit = DEFAULT_SOURCES_PER_LESSON,
  } = params;
  const selected: Array<{
    candidate: CurationCandidate;
    validation: UrlValidationResult;
  }> = [];

  for (const candidate of candidates) {
    if (selected.length >= limit) break;
    if (params.shouldContinue && !await params.shouldContinue()) break;
    let candidateUrl: string;
    try {
      candidateUrl = normalizeSourceUrl(candidate.url);
    } catch {
      continue;
    }
    if (existingNormalizedUrls.has(candidateUrl)) continue;
    const validation = await validate(candidate.url, {
      existingNormalizedUrls,
    });
    // Exclude every attempted URL in later autonomous rounds, including
    // candidates rejected by the technical validator.
    const resolvedUrl = validation.normalizedUrl || candidateUrl;
    const duplicateDestination = existingNormalizedUrls.has(resolvedUrl);
    existingNormalizedUrls.add(candidateUrl);
    existingNormalizedUrls.add(resolvedUrl);
    if (!validation.isValid || duplicateDestination) continue;
    selected.push({ candidate, validation });
  }
  return selected;
}

export async function runCurationWorkflowV2(params: {
  artifactId: string;
  curationId: string;
  customPrompt?: string;
  systemPrompt?: string;
  openAiApiKey: string;
  model: string;
  reasoningEffort?: string;
  supabase: SupabaseClient;
  resume?: boolean;
  attemptNumber: number;
  search?: typeof searchLessonCandidates;
  validate?: typeof validateUrlSource;
}) {
  const {
    artifactId,
    curationId,
    customPrompt,
    systemPrompt,
    openAiApiKey,
    model,
    reasoningEffort = "low",
    supabase,
  } = params;
  const deadline = Date.now() + PIPELINE_GENERATION_LIMITS.curationRunMs;
  const checkpoint = async (rows: CurationRowInsert[] = [], completion: Record<string, unknown> | null = null) => {
    const { data, error } = await supabase.rpc("commit_curation_progress", {
      p_curation_id: curationId, p_attempt: params.attemptNumber, p_rows: rows, p_completion: completion,
    });
    if (error) throw error;
    return data === true;
  };
  if (!await checkpoint()) return 0;
  const [planResult, artifactResult, syllabusResult] = await Promise.all([
    supabase
      .from("instructional_plans")
      .select("lesson_plans")
      .eq("artifact_id", artifactId)
      .maybeSingle(),
    supabase
      .from("artifacts")
      .select(
        "idea_central, nombres, objetivos, descripcion, generation_metadata, organization_id",
      )
      .eq("id", artifactId)
      .single(),
    readSyllabusWithOrigin(supabase, artifactId, "modules,state"),
  ]);
  if (planResult.error) throw new Error(planResult.error.message);
  if (artifactResult.error) throw new Error(artifactResult.error.message);
  if (syllabusResult.error) throw new Error(syllabusResult.error.message);
  const effectivePlan = await mergeDeliveryCurationPlan(supabase, artifactId, planResult.data?.lesson_plans);
  if (syllabusResult.data?.input_mode === "PROVIDED_SYLLABUS" && planResult.data) {
    const { data: version, error } = await supabase.from("instructional_plans").select("syllabus_content_version").eq("artifact_id", artifactId).single();
    if (error) throw error;
    if (syllabusResult.data.state !== "STEP_APPROVED" || version?.syllabus_content_version !== syllabusResult.data.content_version) {
      throw new Error("El plan no corresponde al temario importado aprobado. Regenera el plan antes de buscar fuentes.");
    }
  }
  const sourceLessons = new Map<string, { topics?: string[] }>();
  for (const module of syllabusResult.data?.modules || []) {
    for (const lesson of module.lessons || []) if (lesson.id) sourceLessons.set(lesson.id, lesson);
  }

  const context = buildCourseContextSummary(
    artifactResult.data,
    syllabusResult.data,
  );
  const lessons = buildLessonsToProcess(effectivePlan).map(
    (lesson): CurationLesson => ({
      lesson_id: lesson.lesson_id,
      topics: sourceLessons.get(lesson.lesson_id)?.topics || [],
      lesson_title: lesson.lesson_title,
      lesson_objective: lesson.lesson_objective,
      module_title: lesson.module_title,
      required_sources: lesson.required_sources,
      video_target_seconds: lesson.video_target_seconds,
    }),
  );
  const { data: existingRows, error: existingError } = await supabase
    .from("curation_rows")
    .select(
      "id, lesson_id, source_ref, source_kind, origin, apta, validation_report, content_sha256, storage_path",
    )
    .eq("curation_id", curationId);
  if (existingError) throw new Error(existingError.message);

  const automaticRows: Array<{
    id?: string;
    lesson_id: string;
    source_ref?: string | null;
    source_kind?: string | null;
    origin?: string | null;
    apta: boolean | null;
    validation_report?: { status?: string } | null;
    content_sha256?: string | null;
    storage_path?: string | null;
  }> = (existingRows || []).filter(
    (row) =>
      (!row.origin || row.origin === "automatic") && row.source_kind !== "pdf",
  );
  const normalizedUrlsByLesson = new Map<string, Set<string>>();
  for (const row of automaticRows) {
    if (!row.source_ref) continue;
    try {
      const lessonUrls =
        normalizedUrlsByLesson.get(row.lesson_id) || new Set<string>();
      lessonUrls.add(normalizeSourceUrl(row.source_ref));
      normalizedUrlsByLesson.set(row.lesson_id, lessonUrls);
    } catch {
      // Invalid legacy rows are revalidated elsewhere.
    }
  }
  const hadMissingCoverage = calculateLessonCoverage(
    lessons,
    automaticRows,
  ).some((item) => !item.isCovered);

  const client = new OpenAI({ apiKey: openAiApiKey, maxRetries: 0, timeout: PIPELINE_GENERATION_LIMITS.requestTimeoutMs });
  let inserted = 0;
  let successfulSearchCalls = 0;
  let stalledRounds = 0;

  rounds: for (let round = 1; round <= MAX_AUTONOMOUS_ROUNDS; round += 1) {
    const coverage = calculateLessonCoverage(lessons, automaticRows);
    const missingIds = new Set(
      coverage.filter((item) => !item.isCovered).map((item) => item.lessonId),
    );
    const lessonsToSearch = lessons.filter((lesson) =>
      missingIds.has(lesson.lesson_id),
    );
    if (lessonsToSearch.length === 0) break;

    console.log(
      `[Curation V2] Autonomous round ${round}/${MAX_AUTONOMOUS_ROUNDS}; ${lessonsToSearch.length} lesson(s) pending.`,
    );
    let insertedThisRound = 0;

    for (
      let offset = 0;
      offset < lessonsToSearch.length;
      offset += LESSONS_PER_BATCH
    ) {
      const batch = lessonsToSearch.slice(offset, offset + LESSONS_PER_BATCH);
      if (!await checkpoint()) return inserted;
      if (Date.now() >= deadline) break rounds;

      let candidates: CurationCandidate[] = [];
      let lastSearchError: unknown;
      for (let attempt = 0; attempt < SEARCH_ATTEMPTS; attempt += 1) {
        if (Date.now() >= deadline) break rounds;
        if (!await checkpoint()) return inserted;
        try {
          candidates = await (params.search || searchLessonCandidates)({
            client,
            model,
            courseContext: context.fullCourseContext,
            lessons: batch.map((lesson) => {
              const currentCoverage = coverage.find((item) => item.lessonId === lesson.lesson_id)!;
              return {
                ...lesson,
                remaining_sources: Math.max(0, currentCoverage.targetCount - currentCoverage.validCount),
                excluded_urls: [...(normalizedUrlsByLesson.get(lesson.lesson_id) || [])],
              };
            }),
            customPrompt,
            systemPrompt,
            reasoningEffort,
            round,
            artifactId,
            organizationId: artifactResult.data.organization_id,
            supabase,
            deadlineMs: deadline,
          });
          successfulSearchCalls += 1;
          lastSearchError = undefined;
          break;
        } catch (error) {
          if (isPermanentProviderFailure(error)) throw error;
          lastSearchError = error;
          console.error(
            `[Curation V2] Search attempt ${attempt + 1}/${SEARCH_ATTEMPTS} failed:`,
            error,
          );
          if (attempt < SEARCH_ATTEMPTS - 1) {
            const delay = 2_000 * (attempt + 1);
            if (Date.now() + delay >= deadline) break rounds;
            await wait(delay);
          }
        }
      }
      if (lastSearchError) {
        console.error(
          `[Curation V2] Batch pending after retries: ${batch.map((lesson) => lesson.lesson_id).join(", ")}`,
        );
        continue;
      }

      for (const lesson of batch) {
        const lessonNormalizedUrls =
          normalizedUrlsByLesson.get(lesson.lesson_id) || new Set<string>();
        normalizedUrlsByLesson.set(lesson.lesson_id, lessonNormalizedUrls);
        const coverageItem = calculateLessonCoverage(
          lessons,
          automaticRows,
        ).find((item) => item.lessonId === lesson.lesson_id);
        const remainingSources = Math.max(
          0,
          (lesson.required_sources || DEFAULT_SOURCES_PER_LESSON) -
            (coverageItem?.validCount || 0),
        );
        const selected = await validateAutomaticCandidates({
          candidates: candidates.filter(
            (item) => item.lesson_id === lesson.lesson_id,
          ),
          existingNormalizedUrls: lessonNormalizedUrls,
          limit: remainingSources,
          validate: (url, options) => (params.validate || validateUrlSource)(url, {
            ...options,
            timeoutMilliseconds: Math.max(1, Math.min(SOURCE_VALIDATION_TIMEOUT_MS, deadline - Date.now())),
          }),
          shouldContinue: async () => Date.now() < deadline && await checkpoint(),
        });
        const rows: CurationRowInsert[] = selected.map(
          ({ candidate, validation }) => ({
            curation_id: curationId,
            lesson_id: lesson.lesson_id,
            lesson_title: lesson.lesson_title,
            component: "LESSON_SOURCE",
            is_critical: true,
            source_ref: validation.normalizedUrl,
            source_title: candidate.title || validation.report.detected_title,
            source_rationale: candidate.rationale,
            url_status: "OK",
            apta: true,
            cobertura_completa: true,
            auto_evaluated: true,
            auto_reason: validation.report.reason,
            origin: "automatic",
            source_kind: "url",
            validation_report: validation.report,
          }),
        );
        if (rows.length > 0) {
          if (!await checkpoint(rows)) return inserted;
          automaticRows.push(
            ...rows.map((row) => ({
              lesson_id: row.lesson_id,
              source_ref: row.source_ref,
              source_kind: row.source_kind,
              origin: row.origin,
              apta: row.apta,
              validation_report: row.validation_report as {
                status?: string;
              },
            })),
          );
          inserted += rows.length;
          insertedThisRound += rows.length;
        }
      }
    }

    stalledRounds = insertedThisRound === 0 ? stalledRounds + 1 : 0;
    if (stalledRounds >= MAX_STALLED_ROUNDS) {
      console.warn(
        "[Curation V2] Stopping after two rounds without new valid sources.",
      );
      break;
    }
  }

  if (hadMissingCoverage && successfulSearchCalls === 0 && inserted === 0 && Date.now() < deadline) {
    throw new Error("OpenAI search failed for every lesson batch.");
  }

  const { data: finalRows, error: finalRowsError } = await supabase
    .from("curation_rows")
    .select(
      "id, lesson_id, apta, validation_report, source_ref, source_kind, origin, content_sha256, storage_path",
    )
    .eq("curation_id", curationId);
  if (finalRowsError) throw new Error(finalRowsError.message);
  const finalAutomaticRows = (finalRows || []).filter(
    (row) =>
      (!row.origin || row.origin === "automatic") && row.source_kind !== "pdf",
  );
  const coverage = calculateLessonCoverage(lessons, finalAutomaticRows);
  const missing = coverage.filter((item) => !item.isCovered);
  const isComplete = missing.length === 0 && lessons.length > 0;
  const stopReason = Date.now() >= deadline
    ? "La búsqueda alcanzó el tiempo disponible para esta ejecución."
    : stalledRounds >= MAX_STALLED_ROUNDS
      ? "Las últimas búsquedas no encontraron nuevas fuentes que superaran la validación."
      : "La búsqueda alcanzó el máximo de rondas de esta ejecución.";
  await checkpoint([], {
      state: isComplete ? "PHASE2_APPROVED" : "PHASE2_BLOCKED",
      qa_decision: {
        decision: isComplete ? "APPROVED" : "BLOCKED",
        notes: isComplete
          ? `Curaduria autonoma completada: ${coverage.reduce((total, item) => total + item.validCount, 0)} fuentes web validas para ${lessons.length} lecciones.`
          : `${stopReason} Se conservaron las fuentes válidas. Lecciones pendientes: ${missing.map((item) => `${item.lessonTitle} (${item.validCount}/${item.targetCount})`).join(", ")}`,
        reviewed_by: "gpt:auto",
        reviewed_at: new Date().toISOString(),
      },
      updated_at: new Date().toISOString(),
    });
  return inserted;
}
