"use client";

import { useCallback, useEffect, useState } from "react";
import { useCourseDelivery } from "@/domains/course-delivery/hooks/useCourseDelivery";
import {
  getArtifactGenerationSnapshotAction,
  regenerateArtifactAction,
  updateArtifactContentAction,
  updateArtifactStatusAction,
} from "@/domains/artifacts/actions/artifact.actions";
import {
  buildWorkflowSnapshot,
  isCurationApprovedFromSnapshot,
  isInstructionalPlanApproved,
  isMaterialsApprovedFromSnapshot,
  isSyllabusApproved,
} from "@/lib/artifact-workflow";
import type { ArtifactWorkflowStep } from "@/lib/client/artifact-workspace-preferences";
import { useArtifactWorkspacePreferences } from "@/hooks/useArtifactWorkspacePreferences";
import { getArtifactDisplayState } from "../artifacts-list.utils";
import type {
  PublicationProfile,
  PublicationRequestRecord,
  PublicationVideoLesson,
} from "@/domains/publication/types/publication.types";
import { PRODUCTION_THEME } from "@/domains/materials/components/production-asset-ui";
import { ArtifactStageContent } from "./ArtifactStageContent";
import { ArtifactToast } from "./ArtifactToast";
import { ArtifactWorkflowHeader } from "./ArtifactWorkflowHeader";
import { ArtifactWorkflowStepper } from "./ArtifactWorkflowStepper";
import {
  ARTIFACT_REFRESH_POLL_INTERVAL_MS,
  ARTIFACT_TOAST_HIDE_DELAY_MS,
} from "@/shared/constants/timing";
import type {
  ArtifactContentUpdates,
  ArtifactEditedContent,
  ArtifactValidationReport,
  ArtifactViewRecord,
} from "./artifact-view.types";

const STATUS_STYLES: Record<string, string> = {
  READY_FOR_QA: "text-cyan-700 bg-cyan-50 border-cyan-200 dark:text-cyan-300 dark:bg-cyan-500/10 dark:border-cyan-500/20",
  ESCALATED: "text-orange-700 bg-orange-50 border-orange-200 dark:text-orange-300 dark:bg-orange-500/10 dark:border-orange-500/20",
  GENERATING: "text-blue-700 bg-blue-50 border-blue-200 animate-pulse dark:text-blue-300 dark:bg-blue-500/10 dark:border-blue-500/20",
  APPROVED: "text-green-700 bg-green-50 border-green-200 dark:text-green-300 dark:bg-green-500/10 dark:border-green-500/20",
};

function buildEditedContent(artifact: ArtifactViewRecord): ArtifactEditedContent {
  return {
    nombres: artifact.nombres || [],
    objetivos: artifact.objetivos || [],
    descripcion: {
      texto: artifact.descripcion?.texto || artifact.descripcion?.resumen || "",
      publico_objetivo: artifact.descripcion?.publico_objetivo || "",
      beneficios: artifact.descripcion?.beneficios || "",
    },
  };
}

export default function ArtifactClientView({
  artifact: initialArtifact,
  publicationRequest,
  publicationLessons,
  profile,
  basePath = "/admin",
}: {
  artifact: ArtifactViewRecord;
  publicationRequest?: PublicationRequestRecord | null;
  publicationLessons?: PublicationVideoLesson[];
  profile?: PublicationProfile;
  basePath?: string;
}) {
  const [artifact, setArtifact] = useState(initialArtifact);
  const [activeTab, setActiveTab] = useState<"content" | "validation">(
    "content",
  );
  const [feedback, setFeedback] = useState("");
  const [isRegenerating, setIsRegenerating] = useState(false);
  const [reviewState, setReviewState] = useState<
    "pending" | "approved" | "rejected"
  >(
    artifact.state === "APPROVED" || artifact.qa_status === "APPROVED"
      ? "approved"
      : "pending",
  );
  const [localProductionComplete, setLocalProductionComplete] = useState(
    Boolean(artifact.production_complete),
  );
  const [editingSection, setEditingSection] = useState<
    "nombres" | "objetivos" | "descripcion" | null
  >(null);
  const [editedContent, setEditedContent] = useState(
    buildEditedContent(artifact),
  );
  const [toast, setToast] = useState<{
    show: boolean;
    message: string;
    type: "success" | "error" | "info";
  }>({ show: false, message: "", type: "info" });

  const snapshot = buildWorkflowSnapshot(artifact, publicationRequest);
  const delivery = useCourseDelivery(artifact.id);
  const hasSessions = Boolean(delivery.snapshot && delivery.snapshot.workspace.document.config.mode !== "NEXUS");
  const coursePlanApproved = hasSessions ? Boolean(delivery.snapshot?.readiness.planReady) : isInstructionalPlanApproved(snapshot);
  const courseMaterialsApproved = hasSessions ? Boolean(delivery.snapshot?.readiness.materialsReady) : isMaterialsApprovedFromSnapshot(snapshot);
  const syllabusApproved = isSyllabusApproved(snapshot);
  const planApproved = coursePlanApproved;
  const curationApproved = isCurationApprovedFromSnapshot(snapshot);
  const materialsApproved = courseMaterialsApproved;
  const baseDone = reviewState === "approved" || syllabusApproved;

  const canAccessStep = useCallback((step: ArtifactWorkflowStep) => {
    if (step === 1) return true;
    if (step === 2) return baseDone;
    if (step === 3) return syllabusApproved;
    if (step === 4) return planApproved;
    if (step === 5) return curationApproved;
    return materialsApproved;
  }, [baseDone, curationApproved, materialsApproved, planApproved, syllabusApproved]);
  const { currentStep, setCurrentStep } = useArtifactWorkspacePreferences({
    artifactId: artifact.id,
    canAccessStep,
    ready: Boolean(delivery.snapshot) || Boolean(delivery.error),
  });

  useEffect(() => {
    setArtifact(initialArtifact);
  }, [initialArtifact]);

  useEffect(() => {
    setLocalProductionComplete(Boolean(artifact.production_complete));
  }, [artifact.production_complete]);

  useEffect(() => {
    setEditedContent(buildEditedContent(artifact));
  }, [artifact]);

  useEffect(() => {
    if (artifact.state === "GENERATING" || isRegenerating) {
      let cancelled = false;
      const syncGenerationSnapshot = async () => {
        try {
          const result = await getArtifactGenerationSnapshotAction(artifact.id);
          if (!result.success || cancelled) return;
          setArtifact((current) => ({ ...current, ...result.artifact }));
        } catch (error) {
          // A transient server-action transport failure must not interrupt the
          // user's current workspace. The next polling interval can retry.
          if (!cancelled) {
            console.warn("[ArtifactDetail] Generation snapshot sync failed", error);
          }
        }
      };

      void syncGenerationSnapshot();
      const interval = setInterval(() => void syncGenerationSnapshot(), ARTIFACT_REFRESH_POLL_INTERVAL_MS);

      return () => {
        cancelled = true;
        clearInterval(interval);
      };
    }
  }, [artifact.id, artifact.state, isRegenerating]);

  useEffect(() => {
    const enabled = currentStep === 7;
    document.documentElement.classList.toggle("courseforge-assembly-focus", enabled);
    const page = document.getElementById("artifact-detail-page");
    const breadcrumbs = document.getElementById("artifact-detail-breadcrumbs");
    if (enabled && page) {
      page.style.cssText = "display:flex; flex-direction:column; height:100%; max-width:none; margin:0; padding:0; transition:all 420ms cubic-bezier(.22,1,.36,1);";
    }
    if (enabled && breadcrumbs) breadcrumbs.style.display = "none";
    window.dispatchEvent(
      new CustomEvent("courseforge:admin-focus-mode", {
        detail: { enabled },
      }),
    );

    return () => {
      document.documentElement.classList.remove("courseforge-assembly-focus");
      if (page) page.style.cssText = "";
      if (breadcrumbs) breadcrumbs.style.display = "";
      window.dispatchEvent(
        new CustomEvent("courseforge:admin-focus-mode", {
          detail: { enabled: false },
        }),
      );
    };
  }, [currentStep]);

  const showToast = (
    message: string,
    type: "success" | "error" | "info" = "info",
  ) => {
    setToast({ show: true, message, type });
    setTimeout(() => {
      setToast((previous) => ({ ...previous, show: false }));
    }, ARTIFACT_TOAST_HIDE_DELAY_MS);
  };

  const handleSaveContent = async () => {
    if (!editingSection) return;

    try {
      const updates: ArtifactContentUpdates = {};

      if (editingSection === "nombres") {
        updates.nombres = editedContent.nombres;
      }

      if (editingSection === "objetivos") {
        updates.objetivos = editedContent.objetivos;
      }

      if (editingSection === "descripcion") {
        updates.descripcion = {
          ...artifact.descripcion,
          ...editedContent.descripcion,
        };
      }

      const result = await updateArtifactContentAction(artifact.id, updates);
      if (!result.success) {
        showToast("Error al guardar.", "error");
        return;
      }

      setEditingSection(null);
      setArtifact((current) => ({ ...current, ...updates }));
      showToast("Cambios guardados.", "success");
    } catch (error) {
      console.error(error);
      showToast("Error de conexiҳn", "error");
    }
  };

  const handleCancelEdit = () => {
    setEditingSection(null);
    setEditedContent(buildEditedContent(artifact));
  };

  const handleRegenerate = async () => {
    setIsRegenerating(true);

    try {
      const result = await regenerateArtifactAction(artifact.id, feedback);
      if (!result.success) {
        showToast(result.error || "No se pudo iniciar la regeneración.", "error");
        return;
      }
      showToast("Regeneraciҳn iniciada.", "info");
      setReviewState("pending");
      setFeedback("");
      setArtifact((current) => ({
        ...current,
        descripcion: {},
        nombres: [],
        objetivos: [],
        state: "GENERATING",
      }));
    } catch (error) {
      console.error(error);
      showToast("Error al regenerar.", "error");
    } finally {
      setIsRegenerating(false);
    }
  };

  const handleApproveBase = async () => {
    try {
      const result = await updateArtifactStatusAction(artifact.id, "APPROVED");
      if (!result.success) {
        showToast("Error al actualizar.", "error");
        return;
      }

      setReviewState("approved");
      setArtifact((current) => ({ ...current, state: "APPROVED" }));
      showToast("Fase 1 Aprobada.", "success");
    } catch (error) {
      console.error(error);
      showToast("Error de conexiҳn.", "error");
    }
  };

  const handleRejectBase = async () => {
    try {
      const result = await updateArtifactStatusAction(artifact.id, "REJECTED");
      if (!result.success) {
        showToast("Error al actualizar.", "error");
        return;
      }

      setReviewState("rejected");
      setArtifact((current) => ({ ...current, state: "REJECTED" }));
      showToast("Fase 1 Rechazada.", "info");
    } catch (error) {
      console.error(error);
      showToast("Error de conexiҳn.", "error");
    }
  };

  const validation = artifact.validation_report || {
    results: [],
    all_passed: false,
  } satisfies ArtifactValidationReport;
  const displayState =
    basePath === "/admin" || basePath.endsWith("/admin")
      ? getArtifactDisplayState({
          id: artifact.id,
          idea_central: artifact.idea_central || "",
          descripcion: artifact.descripcion,
          state: artifact.state,
          created_at: artifact.created_at,
          created_by: "",
          syllabus_state:
            typeof artifact.syllabus_state === "string"
              ? artifact.syllabus_state
              : undefined,
          plan_state:
            typeof artifact.plan_state === "string" ? artifact.plan_state : undefined,
          production_complete: Boolean(artifact.production_complete),
        }, true)
      : artifact.state;
  const currentStatusStyle =
    STATUS_STYLES[displayState] || STATUS_STYLES.GENERATING;

  // Construir snapshot — extrae solo campos primitivos del artifact.
  // Elimina contaminación cruzada entre fases.
  const productionComplete =
    localProductionComplete || snapshot.productionComplete;
  const assetsComplete = snapshot.assetsComplete;

  // Cada paso se marca como "done" solo por su propia fase
  const syllabusDone = syllabusApproved;
  const planDone = planApproved;
  const curationDone = curationApproved;
  const materialsDone = materialsApproved;
  const productionDone = assetsComplete || productionComplete;
  const postproductionDone = productionComplete;

  // Progresión lineal estricta: cada paso requiere que su predecesor esté done
  const canAccessSourcesStep = planDone;
  const canAccessMaterialsStep = curationDone;
  // Production, assembly and publication are parallel workspaces once
  // materials are approved. Completion in one must not gate access to another.
  const canAccessProductionStep = materialsDone;
  const canAccessPostproductionStep = materialsDone;
  const canAccessPublicationStep = materialsDone;
  const isAssemblyStudio = currentStep === 7;

  return (
    <div className={`relative ${isAssemblyStudio ? "flex h-full min-h-0 flex-col gap-2 overflow-hidden" : "space-y-8"}`}>
      <ArtifactToast
        toast={toast}
        onClose={() => setToast((previous) => ({ ...previous, show: false }))}
      />

      <div id={isAssemblyStudio ? "assembly-workspace-toolbar" : undefined} className={isAssemblyStudio ? `${PRODUCTION_THEME.workspaceHeader} gap-3` : "space-y-8"}>
        <ArtifactWorkflowHeader
          artifact={artifact}
          compact={isAssemblyStudio}
          currentStatusStyle={currentStatusStyle}
          displayState={displayState}
        />

        <ArtifactWorkflowStepper
          assemblyRequired={delivery.snapshot?.readiness.assembly ?? true}
          deliveryOnly={delivery.snapshot?.workspace.document.config.mode === "SYNCHRONOUS"}
          canAccessMaterialsStep={canAccessMaterialsStep}
          canAccessProductionStep={canAccessProductionStep}
          canAccessPostproductionStep={canAccessPostproductionStep}
          canAccessPublicationStep={canAccessPublicationStep}
          canAccessSourcesStep={canAccessSourcesStep}
          currentStep={currentStep}
          compact={isAssemblyStudio}
          onStepChange={setCurrentStep}
          stepStatus={{
            baseDone,
            syllabusDone,
            planDone,
            curationDone,
            materialsDone,
            productionDone,
            postproductionDone,
            publicationDone:
              publicationRequest?.status === "SENT" ||
              publicationRequest?.status === "APPROVED",
          }}
        />
      </div>

      <div className={isAssemblyStudio ? "min-h-0 flex-1 overflow-hidden" : ""}>
        <ArtifactStageContent
          delivery={delivery}
          activeTab={activeTab}
          artifact={artifact}
          basePath={basePath}
          currentStep={currentStep}
          editedContent={editedContent}
          editingSection={editingSection}
          feedback={feedback}
          isRegenerating={isRegenerating}
          onApproveBase={handleApproveBase}
          onCancelEdit={handleCancelEdit}
          onLocalProductionStatusChange={setLocalProductionComplete}
          onRejectBase={handleRejectBase}
          onRegenerate={handleRegenerate}
          onSaveContent={handleSaveContent}
          profile={profile}
          assetsComplete={assetsComplete}
          publicationLessons={publicationLessons}
          publicationRequest={publicationRequest}
          reviewState={reviewState}
          setActiveTab={setActiveTab}
          setCurrentStep={setCurrentStep}
          setEditedContent={setEditedContent}
          setEditingSection={setEditingSection}
          setFeedback={setFeedback}
          validation={validation}
        />
      </div>
    </div>
  );
}

"use client";

import { AlertCircle, CheckCircle2 } from "lucide-react";

interface ArtifactWorkflowHeaderProps {
  artifact: {
    courseId?: string | null;
    created_at: string;
    id: string;
    idea_central?: string | null;
    state: string;
  };
  currentStatusStyle: string;
  displayState?: string;
  compact?: boolean;
}

function getArtifactTitle(title?: string | null) {
  return (title || "Artefacto sin nombre")
    .replace(/(TEMA:|IDEA PRINCIPAL:|PÒšBLICO:|RESULTADOS:)/g, "")
    .split(".")[0]
    .trim();
}

export function ArtifactWorkflowHeader({
  artifact,
  currentStatusStyle,
  displayState = artifact.state,
  compact = false,
}: ArtifactWorkflowHeaderProps) {
  return (
    <div className={`relative flex min-w-0 items-center justify-between gap-4 overflow-hidden ${compact ? "min-w-[12rem] p-0" : "engine-page-hero min-h-[8.5rem] p-6 md:p-8"}`}>
      {!compact && <div className="absolute top-0 right-0 w-[300px] h-[300px] bg-[var(--engine-info)]/5 rounded-full blur-[80px] pointer-events-none translate-x-1/2 -translate-y-1/2" />}
      <div className="relative z-10 min-w-0 flex-1">
        <div className={`flex min-w-0 items-center gap-3 ${compact ? "" : "mb-2"}`}>
          <h1
            className={`${compact ? "font-display !text-[1.45rem] !font-normal !leading-none text-[var(--engine-text)]" : "font-display text-3xl font-normal text-white md:text-4xl"} truncate`}
            title={artifact.idea_central || undefined}
          >
            {getArtifactTitle(artifact.idea_central)}
          </h1>
          <div
            className={`${compact ? "hidden 2xl:flex" : "flex"} items-center gap-1 rounded-full border px-2 py-0.5 text-[9px] font-bold uppercase tracking-wider ${currentStatusStyle}`}
          >
            {displayState === "READY_FOR_QA" ? (
              <CheckCircle2 size={10} />
            ) : (
              <AlertCircle size={10} />
            )}
            {displayState.replaceAll("_", " ")}
          </div>
        </div>
        {!compact && <p className="font-sans text-xs text-white/65">
          {artifact.courseId || artifact.id} " Creado hace{" "}
          {new Date(artifact.created_at).toLocaleDateString()}
        </p>}
      </div>
    </div>
  );
}

'use client';

import { useState } from 'react';
import { toast } from 'sonner';
import { getErrorMessage } from '@/lib/errors';
import {
    buildInitialSelectedLessons,
    buildInitialVideoMappings,
    buildMappingsFromProductionLessons,
    generateSlugFromTitle,
    getDirectVideoDuration,
    getInitialCourseData,
} from '@/domains/publication/lib/publication-client';
import type {
    LessonVideoData,
    PublicationCourseData,
    PublicationProfile,
    PublicationRequestRecord,
    PublicationVideoLesson,
} from '@/domains/publication/types/publication.types';
import { dismissUpstreamDirtyAction } from '@/lib/server/pipeline-dirty-actions';
import { buildVideoUrl, fetchVideoMetadataClient } from '@/lib/video-platform';
import { ConfirmationModal } from '@/shared/components/ConfirmationModal';
import { UpstreamChangeAlert } from '@/shared/components/UpstreamChangeAlert';
import { refreshProductionVideos } from './actions';
import { CourseDataForm } from './components/CourseDataForm';
import { PublicationAlerts } from './components/PublicationAlerts';
import { PublicationHeader } from './components/PublicationHeader';
import { PublishSuccessModal } from './components/PublishSuccessModal';
import { VideoMappingList } from './components/VideoMappingList';
import styles from './PublicationWorkspace.module.css';

interface PublicationClientViewProps {
    artifactId: string;
    artifactTitle: string;
    lessons: PublicationVideoLesson[];
    existingRequest?: PublicationRequestRecord | null;
    profile?: PublicationProfile;
    basePath?: string;
}

async function savePublicationDraftRequest(
    artifactId: string,
    data: PublicationCourseData,
    lessonVideos: Record<string, LessonVideoData>,
    selectedLessons: Set<string>,
    status: 'DRAFT' | 'READY',
) {
    const response = await fetch('/api/save-draft', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
            artifactId,
            data: {
                ...data,
                lesson_videos: lessonVideos,
                selected_lessons: Array.from(selectedLessons),
                status,
            },
        }),
    });

    const result = (await response.json()) as { success?: boolean; error?: string };
    if (!result.success) {
        throw new Error(result.error || 'Error al guardar borrador');
    }

    return result;
}

export default function PublicationClientView({
    artifactId,
    artifactTitle,
    lessons,
    existingRequest,
    profile,
    basePath: _basePath = '/admin',
}: PublicationClientViewProps) {
    const initialMappings = buildInitialVideoMappings(lessons, existingRequest);
    const lockedEmail = profile?.email || null;
    const [courseData, setCourseData] = useState<PublicationCourseData>(() => {
        const initial = getInitialCourseData(existingRequest);
        if (!initial.instructor_email && lockedEmail) {
            initial.instructor_email = lockedEmail;
        }
        // Auto-suggest a stable slug from the artifact title when none is saved yet.
        // This slug must NOT include a timestamp — it is the idempotency key on SofLIA.
        if (!initial.slug && artifactTitle) {
            initial.slug = generateSlugFromTitle(artifactTitle);
        }
        return initial;
    });
    const [videoMappings, setVideoMappings] = useState<Record<string, LessonVideoData>>(
        initialMappings,
    );
    const [selectedLessons, setSelectedLessons] = useState<Set<string>>(() =>
        buildInitialSelectedLessons(lessons, initialMappings, existingRequest),
    );
    const [isSaving, setIsSaving] = useState(false);
    const [isPublishing, setIsPublishing] = useState(false);
    const [isResetting, setIsResetting] = useState(false);
    const [isResetModalOpen, setIsResetModalOpen] = useState(false);
    const [isPublishConfirmModalOpen, setIsPublishConfirmModalOpen] =
        useState(false);
    const [isPublishSuccessModalOpen, setIsPublishSuccessModalOpen] =
        useState(false);
    const [isUpstreamDirty, setIsUpstreamDirty] = useState(
        Boolean(existingRequest?.upstream_dirty),
    );

    const missingVideos = lessons.filter(
        (lesson) => !videoMappings[lesson.id]?.video_id,
    ).length;
    const selectableLessonsCount = lessons.filter(
        (lesson) => !!videoMappings[lesson.id]?.video_id,
    ).length;
    const missingEmail = !courseData.instructor_email;
    const missingSlug = !courseData.slug;
    const missingThumbnail = !courseData.thumbnail_url;
    const isMetadataComplete = !missingEmail && !missingSlug && !missingThumbnail;
    const isReady = isMetadataComplete;
    const metadataCompleteCount =
        3 - [missingEmail, missingSlug, missingThumbnail].filter(Boolean).length;

    const handleConfirmReset = async () => {
        setIsResetting(true);

        try {
            const result = await refreshProductionVideos(artifactId);
            if (!result.success) {
                toast.error(
                    `Error al obtener datos de produccion: ${result.error}`,
                );
                return;
            }

            const newMappings = buildMappingsFromProductionLessons(result.lessons);
            const lessonsWithVideo = result.lessons.filter(
                (lesson) => !!newMappings[lesson.id]?.video_id,
            );
            let syncedCount = 0;

            for (const lesson of lessonsWithVideo) {
                const mapping = newMappings[lesson.id];
                if (!mapping) {
                    continue;
                }

                try {
                    if (
                        mapping.video_provider === 'youtube' ||
                        mapping.video_provider === 'vimeo'
                    ) {
                        const metadata = await fetchVideoMetadataClient(
                            buildVideoUrl(
                                mapping.video_provider,
                                mapping.video_id,
                            ),
                        );

                        if (metadata.duration > 0) {
                            newMappings[lesson.id].duration = metadata.duration;
                            syncedCount += 1;
                        }
                        continue;
                    }

                    if (
                        mapping.video_provider === 'direct' &&
                        mapping.video_id &&
                        mapping.duration <= 0
                    ) {
                        const duration = await getDirectVideoDuration(
                            mapping.video_id,
                        );
                        if (duration > 0) {
                            newMappings[lesson.id].duration = duration;
                            syncedCount += 1;
                        }
                        continue;
                    }

                    if (mapping.duration > 0) {
                        syncedCount += 1;
                    }
                } catch (error) {
                    console.error(
                        `Error syncing duration for ${lesson.id}:`,
                        error,
                    );
                }
            }

            const syncedSelectedLessons = new Set(
                Object.keys(newMappings).filter(
                    (lessonId) => !!newMappings[lessonId]?.video_id,
                ),
            );

            setVideoMappings({ ...newMappings });
            setSelectedLessons(syncedSelectedLessons);

            await savePublicationDraftRequest(
                artifactId,
                courseData,
                newMappings,
                syncedSelectedLessons,
                'DRAFT',
            );

            toast.success(
                `Videos sincronizados y guardados (${lessonsWithVideo.length} videos, ${syncedCount} con duracion)`,
            );
        } catch (error) {
            console.error(error);
            toast.error('Error al restablecer mappings');
        } finally {
            setIsResetting(false);
        }
    };

    const handleSaveDraft = async () => {
        setIsSaving(true);

        try {
            await savePublicationDraftRequest(
                artifactId,
                courseData,
                videoMappings,
                selectedLessons,
                'DRAFT',
            );
            toast.success('Borrador guardado correctamente');
        } catch (error: unknown) {
            toast.error(
                `Error inesperado: ${getErrorMessage(error, 'Error desconocido')}`,
            );
        } finally {
            setIsSaving(false);
        }
    };

    const handlePublish = async () => {
        setIsPublishing(true);
        setIsPublishConfirmModalOpen(false);

        try {
            await savePublicationDraftRequest(
                artifactId,
                courseData,
                videoMappings,
                selectedLessons,
                'READY',
            );

            const response = await fetch('/api/trigger-publish', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ artifactId }),
            });
            const result = (await response.json()) as {
                success?: boolean;
                error?: string;
            };

            if (response.ok && result.success) {
                setIsPublishSuccessModalOpen(true);
            } else {
                toast.error(
                    `Error al publicar en Soflia: ${result.error || 'Fallo desconocido'}`,
                );
            }
        } catch (error: unknown) {
            toast.error(
                `Error critico: ${getErrorMessage(error, 'Error desconocido')}`,
            );
        } finally {
            setIsPublishing(false);
        }
    };

    return (
        <div className={styles.workspace}>
            {isUpstreamDirty && (
                <div className={styles.upstreamAlert}>
                    <UpstreamChangeAlert
                        source={
                            existingRequest?.upstream_dirty_source ||
                            'un paso anterior'
                        }
                        onIterate={async () => {
                            await dismissUpstreamDirtyAction(
                                'publication_requests',
                                artifactId,
                            );
                            setIsUpstreamDirty(false);
                        }}
                        onDismiss={async () => {
                            await dismissUpstreamDirtyAction(
                                'publication_requests',
                                artifactId,
                            );
                            setIsUpstreamDirty(false);
                        }}
                    />
                </div>
            )}

            <PublicationHeader
                artifactTitle={artifactTitle}
                lessonsCount={lessons.length}
                status={existingRequest?.status}
                profile={profile}
                isReady={isReady}
                metadataCompleteCount={metadataCompleteCount}
                selectedLessonsCount={selectedLessons.size}
                selectableLessonsCount={selectableLessonsCount}
                isSaving={isSaving}
                isPublishing={isPublishing}
                isResetting={isResetting}
                onReset={() => setIsResetModalOpen(true)}
                onSaveDraft={() => {
                    void handleSaveDraft();
                }}
                onPublish={() => setIsPublishConfirmModalOpen(true)}
            />

            <div className={styles.workspaceGrid}>
                <main className={styles.primaryColumn}>
                    <VideoMappingList
                        lessons={lessons}
                        mappings={videoMappings}
                        onMappingChange={setVideoMappings}
                        selectedLessons={selectedLessons}
                        onSelectionChange={setSelectedLessons}
                    />
                </main>

                <aside className={styles.sideRail} aria-label="Configuración de publicación">
                    <PublicationAlerts
                        missingEmail={missingEmail}
                        missingSlug={missingSlug}
                        missingThumbnail={missingThumbnail}
                        missingVideos={missingVideos}
                        selectedLessonsCount={selectedLessons.size}
                        selectableLessonsCount={selectableLessonsCount}
                    />

                    <CourseDataForm
                        artifactId={artifactId}
                        initialData={courseData}
                        onDataChange={setCourseData}
                        lockedEmail={lockedEmail ?? undefined}
                    />
                </aside>
            </div>

            <ConfirmationModal
                isOpen={isPublishConfirmModalOpen}
                onClose={() => setIsPublishConfirmModalOpen(false)}
                onConfirm={async () => {
                    await handlePublish();
                }}
                title="Confirmas el envio a Soflia?"
                message={
                    <div className="space-y-3">
                        <p>
                            Esta accion creara los registros y empaquetara el
                            curso para la plataforma de destino.
                        </p>
                        <p className="text-sm text-gray-500">
                            Asegurate de haber guardado cualquier cambio antes
                            de continuar.
                        </p>
                    </div>
                }
                confirmText="Si, Enviar a Soflia"
                cancelText="Cancelar"
                variant="info"
                isLoading={isPublishing}
            />

            <PublishSuccessModal
                isOpen={isPublishSuccessModalOpen}
                onClose={() => setIsPublishSuccessModalOpen(false)}
            />

            <ConfirmationModal
                isOpen={isResetModalOpen}
                onClose={() => setIsResetModalOpen(false)}
                onConfirm={async () => {
                    setIsResetModalOpen(false);
                    await handleConfirmReset();
                }}
                title="Sincronizar desde Produccion?"
                message={
                    <div className="space-y-3">
                        <p>
                            Esto descartara las asignaciones manuales actuales
                            y recargara los videos mas recientes desde el paso
                            de produccion.
                        </p>
                        <p className="font-semibold text-yellow-500">
                            Se sincronizaran las duraciones reales de los videos
                            detectados.
                        </p>
                    </div>
                }
                confirmText="Si, Sincronizar"
                cancelText="Cancelar"
                variant="warning"
                isLoading={isResetting}
            />
        </div>
    );
}

'use client';

import { useState, useRef } from 'react';
import { BookOpen, Image as ImageIcon, Loader2, Upload } from 'lucide-react';
import { getErrorMessage } from '@/lib/errors';
import { uploadWithSignedUrl } from '@/lib/storage-upload';
import { THUMBNAIL_UPLOAD_MAX_BYTES } from '@/domains/publication/thumbnail-upload-policy';
import { toast } from 'sonner';
import {
    formatThumbnailUrl,
} from '@/domains/publication/lib/publication-client';
import type { PublicationCourseData } from '@/domains/publication/types/publication.types';
import { EngineSelect } from '@/components/ui/EngineSelect';
import styles from '../PublicationWorkspace.module.css';

interface CourseDataFormProps {
    artifactId: string;
    initialData?: PublicationCourseData;
    onDataChange: (data: PublicationCourseData) => void;
    lockedEmail?: string;
}

export function CourseDataForm({ artifactId, initialData, onDataChange, lockedEmail }: CourseDataFormProps) {
    const [formData, setFormData] = useState<PublicationCourseData>({
        category: initialData?.category || 'ia',
        level: initialData?.level || 'beginner',
        instructor_email: initialData?.instructor_email || '',
        slug: initialData?.slug || '',
        price: initialData?.price || 0,
        thumbnail_url: formatThumbnailUrl(initialData?.thumbnail_url) || '',
    });

    const [isUploading, setIsUploading] = useState(false);
    const fileInputRef = useRef<HTMLInputElement>(null);

    const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (!file) return;

        if (file.size > THUMBNAIL_UPLOAD_MAX_BYTES) {
            toast.error("La imagen no debe superar los 5MB");
            return;
        }

        setIsUploading(true);

        try {
            const { publicUrl } = await uploadWithSignedUrl('thumbnails', '', file, {
                artifactId,
                purpose: 'thumbnail',
                upsert: false,
            });

            handleChange('thumbnail_url', publicUrl);
            toast.success("Imagen subida correctamente");
        } catch (error: unknown) {
            console.error('Upload error:', error);
            toast.error(
                `Error al subir imagen: ${getErrorMessage(error, 'Error desconocido')}`,
            );
        } finally {
            setIsUploading(false);
        }
    };

    const handleChange = (
        field: keyof PublicationCourseData,
        value: string | number,
    ) => {
        let finalValue: string | number | undefined = value;
        
        // Fix for Google Drive view links to display as image correctly
        if (field === 'thumbnail_url' && typeof finalValue === 'string') {
            finalValue = formatThumbnailUrl(finalValue);
        }

        const newData: PublicationCourseData = { ...formData, [field]: finalValue };
        setFormData(newData);
        onDataChange(newData);
    };

    return (
        <section className={styles.settingsPanel}>
            <div className={styles.panelHeading}>
                <span className={styles.panelIcon} aria-hidden="true">
                    <BookOpen size={17} />
                </span>
                <div>
                    <span className={styles.eyebrow}>Configuración</span>
                    <h3>Datos del curso</h3>
                </div>
            </div>

            <div className={styles.formGrid}>
                {/* Category */}
                <div className={styles.fieldGroup}>
                    <label>
                        Categoría
                    </label>
                    <EngineSelect
                        value={formData.category}
                        onValueChange={(value) => handleChange('category', value)}
                        options={[
                            { value: 'ia', label: 'Inteligencia Artificial' },
                            { value: 'programming', label: 'Programación' },
                            { value: 'data', label: 'Data Science' },
                            { value: 'design', label: 'Diseño' },
                            { value: 'business', label: 'Negocios' },
                            { value: 'marketing', label: 'Marketing' },
                        ]}
                    />
                </div>

                {/* Level */}
                <div className={styles.fieldGroup}>
                    <label>
                        Nivel
                    </label>
                    <EngineSelect
                        value={formData.level}
                        onValueChange={(value) => handleChange('level', value)}
                        options={[
                            { value: 'beginner', label: 'Principiante' },
                            { value: 'intermediate', label: 'Intermedio' },
                            { value: 'advanced', label: 'Avanzado' },
                        ]}
                    />
                </div>

                {/* Instructor Email */}
                <div className={styles.fieldGroup}>
                    <label>
                        Email del Instructor (Soflia)
                    </label>
                    <input
                        type="email"
                        placeholder="instructor@soflia.com"
                        readOnly={Boolean(lockedEmail)}
                        className={`${styles.textInput} ${lockedEmail ? styles.lockedInput : ''}`}
                        value={formData.instructor_email}
                        onChange={(e) => {
                            if (!lockedEmail) handleChange('instructor_email', e.target.value);
                        }}
                    />
                    <p className={styles.fieldHint}>
                        {lockedEmail
                            ? "Asociado a tu cuenta de Soflia."
                            : "Debe coincidir con un usuario registrado en Soflia."}
                    </p>
                </div>

                {/* Slug */}
                <div className={styles.fieldGroup}>
                    <label>
                        Slug URL
                    </label>
                    <input
                        type="text"
                        placeholder="intro-machine-learning"
                        className={styles.textInput}
                        value={formData.slug}
                        onChange={(e) => handleChange('slug', e.target.value)}
                    />
                </div>

                {/* Price */}
                <div className={styles.fieldGroup}>
                    <label>
                        Precio (USD)
                    </label>
                    <input
                        type="number"
                        min="0"
                        step="0.01"
                        className={styles.textInput}
                        value={formData.price}
                        onChange={(e) => handleChange('price', parseFloat(e.target.value))}
                    />
                </div>

                {/* Thumbnail URL */}
                <div className={`${styles.fieldGroup} ${styles.coverField}`}>
                    <label>
                        Portada del curso
                    </label>

                    <div className={styles.coverControls}>
                        {/* Drag & Drop / Upload Area */}
                        <input
                            type="file"
                            ref={fileInputRef}
                            onChange={handleImageUpload}
                            className={styles.hiddenInput}
                            accept="image/png, image/jpeg, image/webp"
                        />
                        <button
                            type="button"
                            onClick={() => fileInputRef.current?.click()}
                            className={styles.coverUpload}
                        >
                            {formData.thumbnail_url ? (
                                <>
                                    <div className={styles.coverPreview}>
                                        <img src={formData.thumbnail_url} alt="Vista previa de la portada" />
                                        <div className={styles.coverOverlay} />
                                    </div>
                                    <div className={styles.coverAction}>
                                        {isUploading ? (
                                            <Loader2 className="animate-spin" size={24} />
                                        ) : (
                                            <ImageIcon size={24} className="group-hover:scale-110 transition-transform" />
                                        )}
                                        <p>Cambiar portada</p>
                                    </div>
                                </>
                            ) : (
                                <>
                                    <div className={styles.uploadIcon}>
                                        {isUploading ? <Loader2 className="animate-spin" size={24} /> : <Upload size={24} />}
                                    </div>
                                    <div className={styles.uploadCopy}>
                                        <p>
                                            {isUploading ? 'Subiendo...' : 'Subir portada'}
                                        </p>
                                        <small>PNG, JPG o WEBP · máximo 5 MB</small>
                                    </div>
                                </>
                            )}
                        </button>

                        {/* Fallback URL Input */}
                        <div className={styles.urlInputWrap}>
                            <input
                                type="url"
                                placeholder="O pega una URL externa..."
                                className={`${styles.textInput} ${styles.urlInput}`}
                                value={formData.thumbnail_url}
                                onChange={(e) => handleChange('thumbnail_url', e.target.value)}
                            />
                            <div className={styles.inputIcon}>
                                <ImageIcon size={14} />
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        </section>
    );
}

"use client";

import { useRouter } from "next/navigation";
import type { CloudStorageProvider } from "@/domains/production/cloud-storage/types";

interface CloudStorageConnectButtonProps {
  className?: string;
  children: React.ReactNode;
  provider: CloudStorageProvider;
}

const CONNECT_URLS: Record<CloudStorageProvider, string> = {
  google_drive: "/api/auth/google/login",
  onedrive: "/api/auth/microsoft/login",
};

export function CloudStorageConnectButton({
  children,
  className,
  provider,
}: CloudStorageConnectButtonProps) {
  const router = useRouter();
  const handleConnect = () => {
    const popup = window.open(
      CONNECT_URLS[provider],
      `courseforge-${provider}-oauth`,
      "width=720,height=760,menubar=no,toolbar=no,location=yes,status=no",
    );

    if (!popup) {
      window.location.href = CONNECT_URLS[provider];
      return;
    }

    let hasSynchronized = false;
    let intervalId: number | undefined;
    const synchronizeConnection = () => {
      if (hasSynchronized) return;
      hasSynchronized = true;
      if (intervalId !== undefined) window.clearInterval(intervalId);
      router.refresh();
    };

    const handleMessage = (event: MessageEvent) => {
      if (event.origin !== window.location.origin) return;
      if (event.data?.type !== "courseforge:cloud-storage-oauth") return;

      window.removeEventListener("message", handleMessage);
      if (event.data?.status === "success") {
        synchronizeConnection();
      }
    };

    window.addEventListener("message", handleMessage);

    intervalId = window.setInterval(() => {
      if (!popup.closed) return;
      window.clearInterval(intervalId);
      window.removeEventListener("message", handleMessage);
      synchronizeConnection();
    }, 700);
  };

  return (
    <button type="button" onClick={handleConnect} className={className}>
      {children}
    </button>
  );
}

