"use client";

import { useEffect, useMemo, useState } from "react";
import { HardDrive } from "lucide-react";
import {
  disconnectCloudStorageAction,
  getCloudStorageConnectionsAction,
} from "@/domains/production/actions/cloud-storage.actions";
import { CloudStorageConnectButton } from "./CloudStorageConnectButton";
import { toast } from "sonner";
import type {
  CloudStorageConnection,
  CloudStorageProvider,
} from "@/domains/production/cloud-storage/types";

interface CloudStorageProviderSelectorProps {
  onProviderChange: (provider: CloudStorageProvider | null) => void;
}

const PROVIDER_LABELS: Record<CloudStorageProvider, string> = {
  google_drive: "Google Drive",
  onedrive: "OneDrive",
};

export function CloudStorageProviderSelector({
  onProviderChange,
}: CloudStorageProviderSelectorProps) {
  const [connections, setConnections] = useState<CloudStorageConnection[]>([]);
  const [selectedProvider, setSelectedProvider] = useState<CloudStorageProvider | null>(null);
  const [disconnectingProvider, setDisconnectingProvider] = useState<CloudStorageProvider | null>(null);

  const loadConnections = async () => {
    const response = await getCloudStorageConnectionsAction();
    const nextConnections = response.connections;
    setConnections(nextConnections);

    const firstConnected = nextConnections.find((connection) => connection.connected)?.provider || null;
    setSelectedProvider((currentProvider) => {
      if (
        currentProvider &&
        nextConnections.some((connection) => connection.provider === currentProvider && connection.connected)
      ) {
        return currentProvider;
      }

      return firstConnected;
    });
  };

  useEffect(() => {
    loadConnections();
  }, []);

  useEffect(() => {
    onProviderChange(selectedProvider);
  }, [onProviderChange, selectedProvider]);

  const connectedProviders = useMemo(
    () => connections.filter((connection) => connection.connected),
    [connections],
  );

  const handleProviderChange = (provider: CloudStorageProvider | null) => {
    setSelectedProvider(provider);
  };

  const handleDisconnect = async (provider: CloudStorageProvider) => {
    setDisconnectingProvider(provider);
    try {
      const result = await disconnectCloudStorageAction(provider);
      if (!result.success) {
        toast.error(result.error || `No se pudo desvincular ${PROVIDER_LABELS[provider]}`);
        return;
      }

      toast.success(`${PROVIDER_LABELS[provider]} desvinculado`);
      if (selectedProvider === provider) {
        handleProviderChange(null);
      }
      await loadConnections();
    } finally {
      setDisconnectingProvider(null);
    }
  };

  if (connectedProviders.length === 0) {
    return (
      <div className="flex flex-col gap-2 pt-3 border-t border-gray-100 dark:border-white/5">
        <span className="text-xs text-gray-500 dark:text-slate-400 flex items-center gap-1.5 select-none">
          <HardDrive size={14} className="text-gray-400" />
          No hay almacenamiento cloud conectado
        </span>
        <div className="flex flex-wrap gap-3">
          <CloudStorageConnectButton provider="google_drive" className="text-xs text-[var(--engine-accent)] hover:underline font-semibold">
            Conectar Google Drive
          </CloudStorageConnectButton>
          <CloudStorageConnectButton provider="onedrive" className="text-xs text-[var(--engine-accent)] hover:underline font-semibold">
            Conectar OneDrive
          </CloudStorageConnectButton>
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-3 pt-3 border-t border-gray-100 dark:border-white/5">
      <label className="text-xs uppercase tracking-wider text-gray-500 dark:text-[var(--engine-muted)] font-bold">
        Sincronizar carpetas de assets
      </label>
      <div className="space-y-2">
        <label className="flex items-center gap-3 text-sm text-gray-700 dark:text-slate-300 font-medium cursor-pointer">
          <input
            type="radio"
            name="cloudStorageProvider"
            checked={selectedProvider === null}
            onChange={() => handleProviderChange(null)}
            className="h-4 w-4 border-gray-300 text-[var(--engine-accent)] focus:ring-[var(--engine-accent)]"
          />
          <span>No sincronizar</span>
        </label>

        {connectedProviders.map((connection) => (
          <div
            key={connection.provider}
            className="flex items-center justify-between gap-3 rounded-lg border border-gray-100 px-3 py-2 dark:border-white/5"
          >
            <label className="flex min-w-0 flex-1 items-center gap-3 text-sm text-gray-700 dark:text-slate-300 font-medium cursor-pointer">
              <input
                type="radio"
                name="cloudStorageProvider"
                checked={selectedProvider === connection.provider}
                onChange={() => handleProviderChange(connection.provider)}
                className="h-4 w-4 border-gray-300 text-[var(--engine-accent)] focus:ring-[var(--engine-accent)]"
              />
              <span className="flex min-w-0 items-center gap-1.5">
                <HardDrive size={14} className="shrink-0 text-[var(--engine-accent)]" />
                <span className="shrink-0">{PROVIDER_LABELS[connection.provider]}</span>
                {connection.email && (
                  <span className="truncate text-xs text-gray-500 dark:text-slate-400">
                    ({connection.email})
                  </span>
                )}
              </span>
            </label>
            <button
              type="button"
              onClick={() => handleDisconnect(connection.provider)}
              disabled={disconnectingProvider === connection.provider}
              className="shrink-0 text-xs font-semibold text-red-500 hover:underline disabled:cursor-not-allowed disabled:opacity-60"
            >
              {disconnectingProvider === connection.provider ? "Desvinculando..." : "Desvincular"}
            </button>
          </div>
        ))}
      </div>
    </div>
  );
}

'use client';

import { useCallback, useRef, useState } from 'react';
import { useRouter } from 'next/navigation';
import { motion } from 'framer-motion';
import { Sparkles, Upload, ArrowRight, BookOpen, Users, Target, Settings, ChevronDown, CheckCircle2, HardDrive } from 'lucide-react';

import { generateArtifactAction } from '@/domains/artifacts/actions/artifact.actions';
import { ScormImportFlow } from './components/ScormImportFlow';
import { CloudStorageProviderSelector } from './components/CloudStorageProviderSelector';
import { toast } from 'sonner';
import type { CloudStorageProvider } from '@/domains/production/cloud-storage/types';
import {
    createDefaultVideoDurationPolicy,
    VideoDurationPolicyFields,
} from '@/domains/artifacts/components/VideoDurationPolicyFields';
import {
    videoDurationPolicySchema,
    type VideoDurationPolicy,
} from '@/domains/video-duration/video-duration-policy';

interface ArtifactIdeaFormData {
    courseId: string;
    description: string;
    expectedResults: string;
    targetAudience: string;
    title: string;
}

interface SelectionCardProps {
    active: boolean;
    description: string;
    icon: React.ReactNode;
    onClick: () => void;
    title: string;
}

interface TemplateCardProps {
    description: string;
    onClick: () => void;
    title: string;
}

export default function NewArtifactPage({
    basePath = '/admin',
}: {
    basePath?: string;
}) {
    const [mode, setMode] = useState<'ai' | 'import'>('ai');
    const [isAdvancedOpen, setIsAdvancedOpen] = useState(false);
    const [isLoading, setIsLoading] = useState(false);
    const submission = useRef({ pending: false, requestId: '' });
    const [cloudStorageProvider, setCloudStorageProvider] = useState<CloudStorageProvider | null>(null);
    const [videoDurationPolicy, setVideoDurationPolicy] = useState<VideoDurationPolicy>(
        createDefaultVideoDurationPolicy,
    );
    const useGoogleDrive = false;
    const setUseGoogleDrive = (_checked: boolean) => {};

    // Form State
    const [formData, setFormData] = useState<ArtifactIdeaFormData>({
        title: '',
        description: '',
        targetAudience: '',
        expectedResults: '',
        courseId: ''
    });

    const router = useRouter();
    const videoDurationValidation = videoDurationPolicySchema.safeParse(videoDurationPolicy);
    const isGenerateDisabled = isLoading || !formData.description || !videoDurationValidation.success;

    const handleCloudStorageProviderChange = useCallback((provider: CloudStorageProvider | null) => {
        setCloudStorageProvider(provider);
    }, []);

    const handleGenerate = async () => {
        if (submission.current.pending) return;
        const validation = videoDurationPolicySchema.safeParse(videoDurationPolicy);
        if (!validation.success) {
            setIsAdvancedOpen(true);
            toast.error(validation.error.issues[0]?.message || 'Configuración de duración inválida.');
            return;
        }

        submission.current.pending = true;
        submission.current.requestId ||= crypto.randomUUID();
        setIsLoading(true);
        try {
            const result = await generateArtifactAction({
                requestId: submission.current.requestId,
                title: formData.title,
                description: formData.description,
                targetAudience: formData.targetAudience,
                expectedResults: formData.expectedResults,
                courseId: formData.courseId,
                cloudStorageProvider,
                videoDurationPolicy,
            });

            if (result.success) {
                router.push(`${basePath}/artifacts/${result.artifactId}`);
            } else {
                submission.current.pending = false;
                console.error(result.error);
                toast.error(`Error generando el artefacto: ${result.error}`);
            }
        } catch (error) {
            submission.current.pending = false;
            console.error(error);
            toast.error('Ocurrió un error inesperado.');
        } finally {
            if (!submission.current.pending) setIsLoading(false);
        }
    };

    return (
        <div className="max-w-7xl mx-auto space-y-8">
            {/* Header Section */}
            <div className="engine-page-hero">
                <div className="relative z-10">
                    <div className="engine-eyebrow flex items-center gap-2">
                        <Sparkles size={16} />
                        <span>Generador de Contenido con IA</span>
                    </div>
                    <h1 className="mb-2 text-3xl md:text-4xl">Generar nuevo artefacto</h1>
                    <p className="max-w-2xl text-base">
                        Crea un nuevo curso utilizando Inteligencia Artificial o importa contenido existente para comenzar.
                        Nuestra IA estructurará tus ideas en un formato pedagógico completo.
                    </p>
                </div>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
                {/* Left Column: Main Form */}
                <div className="lg:col-span-2 space-y-8">

                    {/* Mode Selection */}
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                        <ModeCard
                            active={mode === 'ai'}
                            onClick={() => setMode('ai')}
                            icon={<Sparkles className="text-[var(--engine-accent)]" size={24} />}
                            title="Crear con IA"
                            description="Estructurado y Preciso. Genera desde cero."
                        />
                        <ModeCard
                            active={mode === 'import'}
                            onClick={() => setMode('import')}
                            icon={<Upload className="text-[var(--engine-info)]" size={24} />}
                            title="Importar Existente"
                            description="Pega contenido completo o sube archivos."
                        />
                    </div>

                    {/* Form Container */}
                    <div className="bg-white dark:bg-[var(--engine-surface-solid)] border border-gray-200 dark:border-[var(--engine-muted)]/10 rounded-2xl p-6 md:p-8 shadow-xl">
                        {mode === 'ai' ? (
                            <div className="space-y-6">

                                {/* Title Input */}
                                <div className="space-y-2">
                                    <label className="text-sm font-medium text-gray-900 dark:text-white flex items-center gap-2">
                                        <BookOpen size={16} className="text-[var(--engine-accent)]" />
                                        Tema o Título del Curso
                                    </label>
                                    <input
                                        type="text"
                                        placeholder="Ej. Curso Completo de Python para Data Science"
                                        className="w-full bg-gray-50 dark:bg-[var(--engine-canvas)] border border-gray-200 dark:border-[var(--engine-muted)]/20 rounded-xl px-4 py-3.5 text-gray-900 dark:text-white placeholder-gray-400 dark:placeholder-[var(--engine-muted)] focus:outline-none focus:border-[var(--engine-accent)]/50 focus:ring-1 focus:ring-[var(--engine-accent)]/20 transition-all font-medium"
                                        value={formData.title}
                                        onChange={e => {
                                            const val = e.target.value;
                                            setFormData(prev => ({ ...prev, title: val }));
                                        }}
                                    />
                                </div>

                                {/* Description Textarea */}
                                <div className="space-y-2">
                                    <label className="text-sm font-medium text-gray-900 dark:text-white flex justify-between items-center">
                                        <span>Idea Principal y Descripción</span>
                                        <span className="text-xs text-gray-500 dark:text-[var(--engine-muted)]">{formData.description.length}/1000</span>
                                    </label>
                                    <textarea
                                        placeholder="Describe de qué trata el curso en detalle... Por ejemplo: 'Un curso introductorio para enseñar Python a analistas financieros, enfocándose en librerías como Pandas y visualización de datos...'"
                                        className="w-full bg-gray-50 dark:bg-[var(--engine-canvas)] border border-gray-200 dark:border-[var(--engine-muted)]/20 rounded-xl px-4 py-3.5 text-gray-900 dark:text-white placeholder-gray-400 dark:placeholder-[var(--engine-muted)] focus:outline-none focus:border-[var(--engine-accent)]/50 focus:ring-1 focus:ring-[var(--engine-accent)]/20 transition-all min-h-[160px] resize-none leading-relaxed"
                                        value={formData.description}
                                        onChange={e => {
                                            const val = e.target.value;
                                            setFormData(prev => ({ ...prev, description: val }));
                                        }}
                                        maxLength={1000}
                                    />
                                </div>

                                {/* Two Columns Grid */}
                                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                                    <div className="space-y-2">
                                        <label className="text-sm font-medium text-gray-900 dark:text-white flex items-center gap-2">
                                            <Users size={16} className="text-[#F59E0B]" />
                                            Público Objetivo
                                        </label>
                                        <input
                                            type="text"
                                            placeholder="Ej. Principiantes, Gerentes..."
                                            className="w-full bg-gray-50 dark:bg-[var(--engine-canvas)] border border-gray-200 dark:border-[var(--engine-muted)]/20 rounded-xl px-4 py-3 text-gray-900 dark:text-white placeholder-gray-400 dark:placeholder-[var(--engine-muted)] focus:outline-none focus:border-[var(--engine-accent)]/50 transition-all"
                                            value={formData.targetAudience}
                                            onChange={e => {
                                                const val = e.target.value;
                                                setFormData(prev => ({ ...prev, targetAudience: val }));
                                            }}
                                        />
                                    </div>
                                    <div className="space-y-2">
                                        <label className="text-sm font-medium text-gray-900 dark:text-white flex items-center gap-2">
                                            <Target size={16} className="text-[#10B981]" />
                                            Resultados Esperados
                                        </label>
                                        <input
                                            type="text"
                                            placeholder="Ej. Crear primera app web..."
                                            className="w-full bg-gray-50 dark:bg-[var(--engine-canvas)] border border-gray-200 dark:border-[var(--engine-muted)]/20 rounded-xl px-4 py-3 text-gray-900 dark:text-white placeholder-gray-400 dark:placeholder-[var(--engine-muted)] focus:outline-none focus:border-[var(--engine-accent)]/50 transition-all"
                                            value={formData.expectedResults}
                                            onChange={e => {
                                                const val = e.target.value;
                                                setFormData(prev => ({ ...prev, expectedResults: val }));
                                            }}
                                        />
                                    </div>
                                </div>

                                {/* Advanced Config Toggle */}
                                <div className="pt-4 border-t border-gray-200 dark:border-[var(--engine-muted)]/10">
                                    <button
                                        onClick={() => setIsAdvancedOpen(!isAdvancedOpen)}
                                        className="flex items-center gap-2 text-sm text-gray-500 dark:text-[var(--engine-text-muted)] hover:text-gray-900 dark:hover:text-white transition-colors"
                                    >
                                        <Settings size={16} />
                                        Configuración Avanzada
                                        <ChevronDown size={14} className={`transform transition-transform ${isAdvancedOpen ? 'rotate-180' : ''}`} />
                                    </button>

                                    {isAdvancedOpen && (
                                        <motion.div
                                            initial={{ height: 0, opacity: 0 }}
                                            animate={{ height: 'auto', opacity: 1 }}
                                            className="pt-4 space-y-4"
                                        >
                                            <div className="space-y-2">
                                                <label className="text-xs uppercase tracking-wider text-gray-500 dark:text-[var(--engine-muted)] font-bold">ID del Curso (Opcional)</label>
                                                <input
                                                    type="text"
                                                    placeholder="#1. MARKETING-101"
                                                    className="w-full bg-gray-50 dark:bg-[var(--engine-canvas)] border border-gray-200 dark:border-[var(--engine-muted)]/20 rounded-lg px-4 py-2 text-sm text-gray-900 dark:text-white focus:outline-none focus:border-[var(--engine-accent)]/30"
                                                    value={formData.courseId}
                                                    onChange={e => {
                                                        const val = e.target.value;
                                                        setFormData(prev => ({ ...prev, courseId: val }));
                                                    }}
                                                />
                                            </div>

                                            <CloudStorageProviderSelector onProviderChange={handleCloudStorageProviderChange} />
                                            <VideoDurationPolicyFields
                                                onChange={setVideoDurationPolicy}
