  surface: "#FFFFFF",
  text: "#0A2540",
};

const DEFAULT_MODIFIERS: TemplateModifiers = {
  cornerRadius: 8,
  density: "comfortable",
  fontPairing: "system_sans",
  showBrandMark: true,
