        const newClip = {
          id: `drive-${Date.now()}`,
          storage_path: result.storagePath,
          public_url: result.publicUrl,
          file_name: result.fileName,
          order: currentClips.length + 1,
        };
        assetsPatch.b_roll_clips = [...currentClips, newClip];
        break;
      }
      case "avatar":
        assetsPatch.avatar_video = {
          storage_path: result.storagePath,
          public_url: result.publicUrl,
          file_name: result.fileName,
          provider: "upload",
        };
