function getModelOptions(settingType: string) {
  if (settingType === "SLIDES_IMAGE_GENERATION") {
    return IMAGE_MODEL_OPTIONS;
  }

  return ALL_MODEL_OPTIONS;
}

function getReasoningOptions(settingType: string) {
  return settingType === "CURATION"
    ? OPENAI_REASONING_LEVEL_OPTIONS
    : REASONING_LEVEL_OPTIONS;
}

function getMetadata(settingType: string) {
  return (
    SETTING_METADATA[settingType] || {
      title: `Configuracion de ${settingType}`,
      icon: <Settings2 size={16} />,
      accent: "teal" as const,
    }
  );
}

function resolveSettingScope(setting: CurationConfig) {
  if (setting.scope?.trim()) {
    return setting.scope.trim();
  }

  if (
    setting.setting_type.startsWith("SLIDES_") ||
    setting.setting_type.startsWith("SLIDE_TEMPLATE_")
  ) {
    return "Modulos: Slides";
  }
  if (setting.setting_type.includes("BUNDLE")) {
    return "Modulos: Bundle";
  }
  if (SETTING_METADATA[setting.setting_type]) {
    return "Cursos";
  }
  return "General";
}

function groupSettingsByScope(settings: CurationConfig[]) {
  const grouped = new Map<string, CurationConfig[]>();

  for (const setting of settings) {
    const scope = resolveSettingScope(setting);
    grouped.set(scope, [...(grouped.get(scope) || []), setting]);
  }

  return Array.from(grouped.entries())
    .map(([scope, scopeSettings]) => ({
      scope,
      settings: scopeSettings.sort((left, right) => {
        const leftIndex = SETTING_ORDER.indexOf(left.setting_type);
        const rightIndex = SETTING_ORDER.indexOf(right.setting_type);
        return (
          (leftIndex === -1 ? 999 : leftIndex) -
          (rightIndex === -1 ? 999 : rightIndex) ||
          left.setting_type.localeCompare(right.setting_type)
        );
      }),
    }))
    .sort((left, right) => {
      const leftIndex = SETTING_SCOPE_ORDER.indexOf(left.scope);
      const rightIndex = SETTING_SCOPE_ORDER.indexOf(right.scope);
      return (
        (leftIndex === -1 ? 999 : leftIndex) -
        (rightIndex === -1 ? 999 : rightIndex) ||
        left.scope.localeCompare(right.scope)
      );
    });
}

function getPromptsForSetting(settingType: string, prompts: SystemPrompt[]) {
  const matcher = PROMPT_CODE_MATCHERS[settingType];

  if (!matcher) {
    return [];
  }

  return prompts
    .filter((prompt) => {
      if (prompt.code.startsWith("SYNCHRONOUS_")) return false;
      const code = prompt.code.toUpperCase();
      return !LEGACY_PROMPT_CODES.has(code) && matcher(code);
    })
    .sort((left, right) => left.code.localeCompare(right.code));
}

function getPromptHelpText(prompt: SystemPrompt) {
  return (
    PROMPT_HELP_TEXT[prompt.code.toUpperCase()] ||
    "Funcion: prompt configurable de esta fase del pipeline. Estructura: conserva las variables entre {{ }} o ${ } porque el sistema las reemplaza al ejecutar el flujo."
  );
}

function PromptHelpTooltip({ text }: { text: string }) {
  return <HelpTooltip ariaLabel="Ver ayuda del prompt" stopPropagation>{text}</HelpTooltip>;
}

function PhasePromptEditor({
  prompt,
  history,
  historyLoading,
  saving,
  resetting,
  restoringId,
  onLoadHistory,
  onRestoreVersion,
  onSave,
  onReset,
}: {
  prompt: SystemPrompt;
  history?: SystemPrompt[];
  historyLoading: boolean;
  saving: boolean;
  resetting: boolean;
  restoringId: string | null;
  onLoadHistory: (prompt: SystemPrompt) => void;
  onRestoreVersion: (prompt: SystemPrompt) => void;
  onSave: (prompt: SystemPrompt, content: string) => void;
  onReset: (prompt: SystemPrompt) => void;
}) {
  const [draft, setDraft] = useState(prompt.content);
  const [isOpen, setIsOpen] = useState(false);
  const [showHistory, setShowHistory] = useState(false);

  useEffect(() => {
    setDraft(prompt.content);
  }, [prompt.id, prompt.content]);

  const hasChanges = draft !== prompt.content;
  const handleToggleHistory = () => {
    const nextShowHistory = !showHistory;
    setShowHistory(nextShowHistory);
    setIsOpen(true);
    if (nextShowHistory && !history) {
      onLoadHistory(prompt);
    }
  };

  return (
    <div className="border border-gray-200 dark:border-[var(--engine-muted)]/10 rounded-xl overflow-hidden bg-gray-50 dark:bg-[var(--engine-canvas)]/50">
      <div className="px-4 py-3 border-b border-gray-200 dark:border-[var(--engine-muted)]/10 flex flex-col gap-3 md:flex-row md:items-center md:justify-between">
        <div
          role="button"
          tabIndex={0}
          onClick={() => setIsOpen((current) => !current)}
          onKeyDown={(event) => {
            if (event.key === "Enter" || event.key === " ") {
              event.preventDefault();
              setIsOpen((current) => !current);
            }
          }}
          className="min-w-0 flex flex-1 items-start gap-2 text-left"
        >
          {isOpen ? (
            <ChevronDown size={16} className="mt-0.5 text-gray-400" />
          ) : (
            <ChevronRight size={16} className="mt-0.5 text-gray-400" />
          )}
          <div className="min-w-0">
          <div className="flex items-center gap-2">
            <MessageSquareCode size={15} className="text-[var(--engine-accent)]" />
            <h5 className="text-sm font-semibold text-gray-900 dark:text-white truncate">
              {prompt.code} v{prompt.version}
            </h5>
            <PromptHelpTooltip text={getPromptHelpText(prompt)} />
            {prompt.is_org_override && (
              <span className="text-[10px] font-semibold px-2 py-0.5 rounded-full bg-amber-500/10 text-amber-500 border border-amber-500/20">
                {prompt.is_restored_default ? "Default restaurado" : "Personalizado"}
              </span>
            )}
            {prompt.scope && (
              <span className="text-[10px] font-semibold px-2 py-0.5 rounded-full bg-blue-500/10 text-blue-600 border border-blue-500/20">
                {prompt.scope}
              </span>
            )}
            {prompt.is_active && (
              <span className="text-[10px] font-semibold px-2 py-0.5 rounded-full bg-green-500/10 text-green-600 border border-green-500/20">
                Activo
              </span>
            )}
          </div>
          <p className="text-xs text-gray-500 dark:text-[var(--engine-text-muted)] mt-1 truncate">
            {prompt.description || "Sin descripcion"}
          </p>
          </div>
        </div>

        <div className="flex items-center gap-2">
          <button
            type="button"
            onClick={handleToggleHistory}
            disabled={historyLoading || saving || resetting}
            className="px-3 py-2 rounded-lg text-xs font-semibold text-gray-600 dark:text-gray-300 border border-gray-200 dark:border-[var(--engine-muted)]/20 hover:bg-white dark:hover:bg-white/5 transition-colors disabled:opacity-50 flex items-center gap-2"
          >
            {historyLoading ? <Loader2 size={13} className="animate-spin" /> : <History size={13} />}
            Historial
          </button>
          {prompt.is_org_override && (
            <button
              type="button"
              onClick={() => onReset(prompt)}
              disabled={resetting || saving}
              className="px-3 py-2 rounded-lg text-xs font-semibold text-amber-600 dark:text-amber-400 border border-amber-500/30 hover:bg-amber-500/10 transition-colors disabled:opacity-50 flex items-center gap-2"
            >
              {resetting ? (
                <Loader2 size={13} className="animate-spin" />
              ) : (
                <RotateCcw size={13} />
              )}
              Restaurar
            </button>
          )}
          <button
            type="button"
            onClick={() => onSave(prompt, draft)}
            disabled={saving || resetting || !hasChanges}
            className="px-3 py-2 rounded-lg text-xs font-semibold bg-[var(--engine-accent)] text-white dark:text-black hover:bg-[var(--engine-accent)]/90 transition-colors disabled:opacity-50 flex items-center gap-2"
          >
            {saving ? <Loader2 size={13} className="animate-spin" /> : <Save size={13} />}
            Guardar
          </button>
        </div>
      </div>

      {isOpen && (
        <>
          <textarea
            value={draft}
            onChange={(event) => setDraft(event.target.value)}
            className="w-full min-h-72 bg-white dark:bg-[var(--engine-canvas)] text-gray-900 dark:text-gray-300 font-mono text-sm p-4 resize-y focus:outline-none focus:ring-1 focus:ring-[var(--engine-accent)]/30 leading-relaxed"
            spellCheck={false}
            placeholder="Contenido del prompt"
          />

          {showHistory && (
            <div className="border-t border-gray-200 dark:border-[var(--engine-muted)]/10 bg-white dark:bg-[#0B1118] p-4">
              <div className="mb-3 flex items-center gap-2 text-xs font-bold uppercase tracking-wider text-gray-500 dark:text-[var(--engine-text-muted)]">
                <History size={14} />
                Historial de versiones
              </div>
              {historyLoading ? (
                <div className="flex items-center gap-2 text-xs text-gray-500">
                  <Loader2 size={13} className="animate-spin" />
                  Cargando historial...
                </div>
              ) : history && history.length > 0 ? (
                <div className="space-y-2">
                  {history.map((item) => (
                    <div
                      key={item.id}
                      className="rounded-lg border border-gray-200 dark:border-[var(--engine-muted)]/10 bg-gray-50 dark:bg-[var(--engine-canvas)]/60 p-3"
                    >
                      <div className="flex flex-col gap-2 md:flex-row md:items-center md:justify-between">
                        <div className="min-w-0">
                          <div className="flex flex-wrap items-center gap-2">
                            <span className="text-xs font-semibold text-gray-900 dark:text-white">
                              v{item.version}
                            </span>
                            <span className="text-[10px] uppercase tracking-wider text-gray-500 dark:text-[var(--engine-text-muted)]">
                              {item.organization_id ? "Organizacion" : "Global"}
                            </span>
                            {item.is_active && (
                              <span className="text-[10px] font-semibold px-2 py-0.5 rounded-full bg-green-500/10 text-green-600 border border-green-500/20">
                                Activa
                              </span>
                            )}
                            {item.source && (
                              <span className="text-[10px] font-semibold px-2 py-0.5 rounded-full bg-gray-200/70 text-gray-600 dark:bg-white/5 dark:text-gray-300">
                                {item.source}
                              </span>
                            )}
                          </div>
                          <p className="mt-1 text-[11px] text-gray-500 dark:text-[var(--engine-text-muted)]">
                            {new Date(item.created_at).toLocaleString()}
                            {item.change_summary ? ` - ${item.change_summary}` : ""}
                          </p>
                        </div>
                        <button
                          type="button"
                          onClick={() => onRestoreVersion(item)}
                          disabled={item.id === prompt.id || Boolean(restoringId) || saving || resetting}
                          className="px-3 py-2 rounded-lg text-xs font-semibold text-[var(--engine-accent)] border border-[var(--engine-accent)]/30 hover:bg-[var(--engine-accent)]/10 transition-colors disabled:opacity-50 flex items-center gap-2"
                        >
                          {restoringId === item.id ? <Loader2 size={13} className="animate-spin" /> : <RotateCcw size={13} />}
                          Restaurar esta version
                        </button>
                      </div>
                      <details className="mt-2">
                        <summary className="cursor-pointer text-[11px] font-semibold text-gray-500 hover:text-gray-900 dark:text-[var(--engine-text-muted)] dark:hover:text-white">
                          Ver contenido
                        </summary>
                        <pre className="mt-2 max-h-48 overflow-auto whitespace-pre-wrap rounded-md bg-white p-3 text-[11px] text-gray-700 dark:bg-[#070A0F] dark:text-gray-300">
                          {item.content}
                        </pre>
                      </details>
                    </div>
                  ))}
                </div>
              ) : (
                <p className="text-xs text-gray-500 dark:text-[var(--engine-text-muted)]">
                  No hay historial para este prompt.
                </p>
              )}
            </div>
          )}

          <div className="px-4 py-2 border-t border-gray-200 dark:border-[var(--engine-muted)]/10 text-xs text-gray-500 dark:text-[var(--engine-text-muted)] flex flex-col gap-1 md:flex-row md:justify-between">
            <span>
              {prompt.is_org_override
                ? "Version activa para esta organizacion"
                : "Version global default activa"}
            </span>
            <span>Ultima actualizacion: {new Date(prompt.updated_at).toLocaleDateString()}</span>
          </div>
        </>
      )}
    </div>
  );
}

export function CurationSettingsManager() {
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [settingsList, setSettingsList] = useState<CurationConfig[]>([]);
  const [prompts, setPrompts] = useState<SystemPrompt[]>([]);
  const [promptSavingId, setPromptSavingId] = useState<string | null>(null);
  const [promptResettingCode, setPromptResettingCode] = useState<string | null>(null);
  const [promptHistories, setPromptHistories] = useState<Record<string, SystemPrompt[]>>({});
  const [promptHistoryLoadingCode, setPromptHistoryLoadingCode] = useState<string | null>(null);
  const [promptRestoringId, setPromptRestoringId] = useState<string | null>(null);

  useEffect(() => {
    async function loadSettings() {
      const [settingsRes, promptsRes] = await Promise.all([
        getModelSettingsAction(),
        getSystemPromptsAction(),
      ]);

      if (settingsRes.success && settingsRes.settings) {
        const filtered = settingsRes.settings.filter(
          (setting) => !OBSOLETE_SETTING_TYPES.has(setting.setting_type),
        );
        filtered.sort((a, b) => {
          const leftIndex = SETTING_ORDER.indexOf(a.setting_type);
          const rightIndex = SETTING_ORDER.indexOf(b.setting_type);
          return (
            (leftIndex === -1 ? 999 : leftIndex) -
            (rightIndex === -1 ? 999 : rightIndex)
          );
        });
        setSettingsList(filtered);
      } else {
        console.error("Error loading settings:", settingsRes.error);
        toast.error("Error al cargar la configuracion de modelos");
      }

      if (promptsRes.success && promptsRes.prompts) {
        setPrompts(promptsRes.prompts);
      } else {
        console.error("Error loading prompts:", promptsRes.error);
        toast.error("Error al cargar los prompts");
      }

      setLoading(false);
    }

    loadSettings();
  }, []);

  const handleUpdate = <Key extends keyof CurationConfig>(
    id: number,
    key: Key,
    value: CurationConfig[Key],
  ) => {
    setSettingsList((previous) =>
      previous.map((item) =>
        item.id === id ? { ...item, [key]: value } : item,
      ),
    );
  };

  const saveSettings = async () => {
    setSaving(true);
    const res = await updateModelSettingsAction(settingsList);

    if (!res.success) {
      toast.error(res.error || "Error guardando algunas configuraciones");
    } else {
      toast.success("Configuraciones de modelos guardadas correctamente");
    }

    setSaving(false);
  };

  const refreshPrompts = async () => {
    const promptsRes = await getSystemPromptsAction();
    if (promptsRes.success && promptsRes.prompts) {
      setPrompts(promptsRes.prompts);
    }
  };

  const loadPromptHistory = async (prompt: SystemPrompt) => {
    setPromptHistoryLoadingCode(prompt.code);
    const res = await getSystemPromptHistoryAction(prompt.code);

    if (res.success && res.prompts) {
      setPromptHistories((previous) => ({
        ...previous,
        [prompt.code]: res.prompts!,
      }));
    } else {
      toast.error(res.error || "Error al cargar historial del prompt");
    }

    setPromptHistoryLoadingCode(null);
  };

  const savePrompt = async (prompt: SystemPrompt, content: string) => {
    setPromptSavingId(prompt.id);

    const res = await updateSystemPromptAction({
      id: prompt.id,
      content,
    });

    if (res.success && res.prompt) {
      await refreshPrompts();
      if (promptHistories[prompt.code]) {
        await loadPromptHistory(prompt);
      }
      toast.success(`Prompt guardado como v${res.prompt.version}`);
    } else {
      toast.error(res.error || "Error al guardar el prompt");
    }

    setPromptSavingId(null);
  };

  const resetPrompt = async (prompt: SystemPrompt) => {
    setPromptResettingCode(prompt.code);

    const res = await resetPromptToDefaultAction(prompt.code);

    if (res.success) {
      await refreshPrompts();
      if (promptHistories[prompt.code]) {
        await loadPromptHistory(prompt);
      }
      toast.success("Prompt restaurado al default global");
    } else {
      toast.error(res.error || "Error al restaurar el prompt");
    }

    setPromptResettingCode(null);
  };

  const restorePromptVersion = async (prompt: SystemPrompt) => {
    setPromptRestoringId(prompt.id);
    const res = await restorePromptVersionAction(prompt.id);

    if (res.success && res.prompt) {
      await refreshPrompts();
      await loadPromptHistory(prompt);
      toast.success(`Version restaurada como v${res.prompt.version}`);
    } else {
      toast.error(res.error || "Error al restaurar version");
    }

    setPromptRestoringId(null);
  };

  const renderModelScopeSection = (scope: string, scopeSettings: CurationConfig[]) => {
    const metadata = PROMPT_SCOPE_METADATA[scope] || {
      description: "Modelos configurables de este ambito.",
      icon: <Settings2 size={16} />,
      title: scope,
    };

    return (
      <section
        key={scope}
        className="engine-settings-scope"
      >
        <div className="engine-settings-scope__header">
          <div className="flex items-start gap-3">
            <div className="rounded-lg bg-[var(--engine-primary)]/10 p-2 text-[var(--engine-primary)] dark:bg-[var(--engine-accent)]/10 dark:text-[var(--engine-accent)]">
              {metadata.icon}
            </div>
            <div>
              <h4 className="text-sm font-bold uppercase tracking-wider text-gray-600 dark:text-gray-300">
                Modelos: {metadata.title}
              </h4>
              <p className="mt-1 text-sm text-gray-500 dark:text-[var(--engine-text-muted)]">
                {metadata.description}
              </p>
            </div>
          </div>
          <span className="rounded-full border border-gray-200 px-3 py-1 text-xs font-semibold text-gray-500 dark:border-[var(--engine-muted)]/20 dark:text-[var(--engine-text-muted)]">
            {scopeSettings.length} configuraciones
          </span>
        </div>

        <div className="engine-settings-phases">
          {scopeSettings.map((setting) => renderConfigSection(setting))}
        </div>
      </section>
    );
  };

  const renderConfigSection = (setting: CurationConfig) => {
    const metadata = getMetadata(setting.setting_type);
    const phasePrompts = getPromptsForSetting(setting.setting_type, prompts);
    const isGreen = metadata.accent === "green";
    const modelOptions = getModelOptions(setting.setting_type);
    const reasoningOptions = getReasoningOptions(setting.setting_type);
    const usesConfiguredModel = !DETERMINISTIC_SLIDE_SETTING_TYPES.has(setting.setting_type);
    const accentText = isGreen ? "text-[#10B981]" : "text-[var(--engine-accent)]";
    const accentBg = isGreen
      ? "bg-[#10B981]/10 text-[#10B981]"
      : "bg-[var(--engine-accent)]/10 text-[var(--engine-accent)]";

    return (
      <div
        key={setting.id}
        className="engine-settings-phase animate-in fade-in slide-in-from-bottom-4 duration-500"
      >
        <div className="engine-settings-phase__identity">
          <div className={`p-2 rounded-lg ${accentBg}`}>{metadata.icon}</div>
          <h4 className="text-sm font-bold text-gray-500 dark:text-gray-300 uppercase tracking-wider">
            {metadata.title}
          </h4>
          <span className="engine-settings-phase__number">
            {String(settingsList.indexOf(setting) + 1).padStart(2, "0")}
          </span>
        </div>

        <div className="engine-settings-phase__content">

        {usesConfiguredModel ? <><div className="grid grid-cols-1 md:grid-cols-2 gap-6 relative z-10">
          <PremiumSelect
            label="Modelo Principal"
            icon={<Zap size={12} className={accentText} />}
            value={setting.model_name ?? ""}
            onChange={(value) => handleUpdate(setting.id, "model_name", value)}
            options={modelOptions}
          />

          <PremiumSelect
            label="Modelo Fallback"
            icon={
              <span className="w-3 h-3 rounded-full border border-gray-400 dark:border-[var(--engine-muted)] flex items-center justify-center text-[8px] text-gray-400 dark:text-[var(--engine-muted)]">
                ?
              </span>
            }
            value={setting.fallback_model ?? ""}
            onChange={(value) =>
              handleUpdate(setting.id, "fallback_model", value)
            }
            options={modelOptions}
          />
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-6 relative z-0">
          <PremiumSelect
            label="Nivel de Pensamiento"
            icon={<BrainCircuit size={12} className="text-[var(--engine-info)]" />}
            value={setting.thinking_level ?? "medium"}
            onChange={(value) =>
              handleUpdate(setting.id, "thinking_level", value)
            }
            options={reasoningOptions}
          />

          <div className="space-y-4">
            <div className="flex justify-between items-center">
              <label className="text-[10px] font-bold text-gray-500 dark:text-[var(--engine-text-muted)] uppercase tracking-wider">
                Temperatura (Creatividad)
              </label>
              <span
                className={`text-xs font-mono font-bold px-2 py-0.5 rounded border ${
                  isGreen
                    ? "text-[#10B981] bg-[#10B981]/10 border-[#10B981]/20"
                    : "text-[var(--engine-accent)] bg-[var(--engine-accent)]/10 border-[var(--engine-accent)]/20"
                }`}
              >
                {setting.temperature}
              </span>
            </div>
            <div className="relative pt-2">
              <input
                type="range"
                min="0.1"
                max="1.0"
                step="0.1"
                value={setting.temperature ?? 0.7}
                onChange={(event) =>
                  handleUpdate(
                    setting.id,
                    "temperature",
                    Number.parseFloat(event.target.value),
                  )
                }
                className={`w-full h-2 bg-gray-200 dark:bg-[#0A0D12] rounded-lg appearance-none cursor-pointer hover:opacity-100 relative z-20 ${
                  isGreen ? "accent-[#10B981]" : "accent-[var(--engine-accent)]"
                }`}
              />
              <div className="absolute top-1/2 left-0 right-0 h-px bg-gray-300 dark:bg-[var(--engine-surface-hover)] -translate-y-1/2 z-0" />
            </div>
            <div className="flex justify-between text-[10px] text-gray-400 dark:text-[var(--engine-muted)]">
              <span>Preciso (0.1)</span>
              <span>Creativo (1.0)</span>
            </div>
          </div>
        </div></> : (
          <div className="rounded-xl border border-cyan-200 bg-cyan-50 p-4 text-sm text-cyan-900 dark:border-cyan-400/20 dark:bg-cyan-400/10 dark:text-cyan-100">
            Esta etapa usa reglas deterministas y validación tipada. Cambiar modelo, temperatura o prompt no modifica su resultado.
          </div>
        )}

        {usesConfiguredModel && <div className="space-y-3">
          <div className="flex items-center gap-2">
            <MessageSquareCode size={15} className={accentText} />
            <h5 className="text-xs font-bold text-gray-500 dark:text-[var(--engine-text-muted)] uppercase tracking-wider">
              Prompts de la fase
            </h5>
          </div>

          {phasePrompts.length > 0 ? (
            <div className="space-y-4">
              {phasePrompts.map((prompt) => (
                <PhasePromptEditor
                  key={`${prompt.code}-${prompt.version}-${prompt.id}`}
                  prompt={prompt}
                  history={promptHistories[prompt.code]}
                  historyLoading={promptHistoryLoadingCode === prompt.code}
                  saving={promptSavingId === prompt.id}
                  resetting={promptResettingCode === prompt.code}
                  restoringId={promptRestoringId}
                  onLoadHistory={loadPromptHistory}
                  onRestoreVersion={restorePromptVersion}
                  onSave={savePrompt}
                  onReset={resetPrompt}
                />
              ))}
            </div>
          ) : (
            <div className="border border-dashed border-gray-200 dark:border-[var(--engine-muted)]/20 rounded-xl p-4 text-sm text-gray-500 dark:text-[var(--engine-text-muted)] bg-gray-50 dark:bg-[var(--engine-canvas)]/40">
              No hay prompts configurables asociados directamente a este paso.
            </div>
          )}
        </div>}

        </div>

        {settingsList.indexOf(setting) < settingsList.length - 1 && (
          <div className="engine-settings-phase__divider" />
        )}
      </div>
    );
  };

  if (loading) {
    return (
      <div className="p-8 flex justify-center text-[var(--engine-accent)]">
        <Loader2 className="animate-spin" />
      </div>
    );
  }

  if (settingsList.length === 0) {
    return (
      <div className="p-12 text-center text-gray-500 dark:text-gray-400">
        <Settings2 className="mx-auto mb-4 opacity-50" size={48} />
        <p>No se encontraron configuraciones de modelos activas.</p>
      </div>
    );
  }

  return (
    <div className="space-y-12">
      <section className="space-y-5">
        <div>
          <h3 className="text-lg font-bold text-gray-900 dark:text-white">
            Modelos por ambito
          </h3>
          <p className="mt-1 text-sm text-gray-500 dark:text-[var(--engine-text-muted)]">
            Define modelo, fallback, temperatura y razonamiento para cada flujo y agente configurable.
          </p>
        </div>

        <div className="space-y-5">
          {groupSettingsByScope(settingsList).map((group) =>
            renderModelScopeSection(group.scope, group.settings),
          )}
        </div>
      </section>

      <div className="pt-4 flex justify-end border-t border-gray-100 dark:border-[var(--engine-muted)]/10 mt-6">
        <button
          onClick={saveSettings}
          disabled={saving}
          className="px-6 py-2.5 bg-[var(--engine-primary)] text-white hover:bg-[var(--engine-primary)]/90 dark:bg-[var(--engine-accent)] dark:text-[#0A0D12] text-sm font-bold rounded-xl dark:hover:bg-[var(--engine-accent-hover)] disabled:opacity-50 transition-all flex items-center gap-2 shadow-lg shadow-[var(--engine-primary)]/20 dark:shadow-[var(--engine-accent)]/20"
        >
          {saving ? (
            <Loader2 size={16} className="animate-spin" />
          ) : (
            <Save size={16} />
          )}
          Guardar Configuracion
        </button>
      </div>

    </div>
  );
}

import { useState, useEffect, useCallback, useRef } from "react";
import { Curation, CurationRow } from "../types/curation.types";
import {
  getCurationSnapshotAction,
  startCurationAction,
  clearSystemGeneratedCurationRowsAction,
  clearInvalidCurationRowsAction,
} from "../actions/curation.actions";
import { toast } from "sonner";
import {
  CURATION_RUNNING_STATES,
  CURATION_STATES,
} from "@/lib/pipeline-constants";
import { usePolling } from "@/shared/hooks/usePolling";
import { isSystemGeneratedCurationRow } from "../lib/curation-row-rules";

export interface CurationLessonRequirement {
  lessonId: string;
  lessonTitle: string;
  requiredSources: number;
  videoTargetSeconds: number;
}

function isUnauthorizedError(error: unknown) {
  if (typeof error === "string") return error === "Unauthorized";
  if (error instanceof Error) return error.message === "Unauthorized";
  return false;
}

export function useCuration(artifactId: string) {
  const [curation, setCuration] = useState<Curation | null>(null);
  const [rows, setRows] = useState<CurationRow[]>([]);
  const [lessonRequirements, setLessonRequirements] = useState<
    CurationLessonRequirement[]
  >([]);
  const [configuredPrompt, setConfiguredPrompt] = useState("");
  const [loading, setLoading] = useState(true);
  const [isGenerating, setIsGenerating] = useState(false);
  const [snapshotAuthUnavailable, setSnapshotAuthUnavailable] = useState(false);
  const hasShownAuthToast = useRef(false);
  const startInFlight = useRef(false);
  const isValidating = curation?.state === CURATION_STATES.VALIDATING;

  const fetchCurationData = useCallback(async () => {
    try {
      const result = await getCurationSnapshotAction(artifactId);
      if (!result.success) {
        if (isUnauthorizedError(result.error)) {
          setSnapshotAuthUnavailable(true);
          setIsGenerating(false);
          if (!hasShownAuthToast.current) {
            toast.warning(
              "La sesion no esta disponible para actualizar fuentes. Recarga la pagina cuando termine el proceso.",
            );
            hasShownAuthToast.current = true;
          }
          return;
        }
        throw new Error(result.error || "Error loading curation");
      }

      setSnapshotAuthUnavailable(false);
      hasShownAuthToast.current = false;
      const curData = result.curation || null;
      setCuration(curData);
      setLessonRequirements(result.lessonRequirements || []);
      setConfiguredPrompt(result.prompt?.content || "");

      if (curData) {
        setRows(result.rows || []);

        const isGen = CURATION_RUNNING_STATES.has(curData.state);
        setIsGenerating(isGen);
      } else {
        setRows([]);
        setIsGenerating(false);
      }
    } catch (error) {
      if (isUnauthorizedError(error)) {
        setSnapshotAuthUnavailable(true);
        setIsGenerating(false);
        if (!hasShownAuthToast.current) {
          toast.warning(
            "La sesion no esta disponible para actualizar fuentes. Recarga la pagina cuando termine el proceso.",
          );
          hasShownAuthToast.current = true;
        }
        return;
      }
      console.error("Error in useCuration fetch:", error);
      toast.error("Error cargando datos de curaduria");
    } finally {
      setLoading(false);
    }
  }, [artifactId]);

  usePolling(
    fetchCurationData,
    Boolean(
      curation?.id &&
      (isGenerating || isValidating) &&
      !snapshotAuthUnavailable,
    ),
    {
      intervalMs: 3000,
    },
  );

  usePolling(
    fetchCurationData,
    !isGenerating &&
      rows.length === 0 &&
      curation?.state !== CURATION_STATES.READY_FOR_QA &&
      !snapshotAuthUnavailable,
    { intervalMs: 5000 },
  );

  usePolling(
    fetchCurationData,
    curation?.state === CURATION_STATES.READY_FOR_QA &&
      !snapshotAuthUnavailable,
    { intervalMs: 5000 },
  );

  useEffect(() => {
    fetchCurationData();
  }, [artifactId, fetchCurationData]);

  const startCuration = async (
    attemptNumber: number = 1,
    gaps: string[] = [],
    resume: boolean = false,
    promptOverride?: string,
  ) => {
    if (startInFlight.current || isGenerating) return;
    startInFlight.current = true;
    setIsGenerating(true);
    try {
      const result = await startCurationAction(
        artifactId,
        attemptNumber,
        gaps,
        resume,
        promptOverride,
      );

      if (!result.success) {
        throw new Error(result.error || "No se pudo iniciar la curaduría.");
      }
      toast.success(
        resume
          ? "Completando fuentes pendientes; se conserva el progreso."
          : "Curaduria iniciada. Las fuentes comenzaran a aparecer pronto.",
      );
      await fetchCurationData();
    } catch (error) {
      setIsGenerating(false);
      toast.error(
        "Error al iniciar curaduria: " +
          (error instanceof Error ? error.message : "No se pudo iniciar la curaduría."),
      );
    } finally {
      startInFlight.current = false;
    }
  };

  const clearSystemGeneratedRows = async () => {
    setRows((current) =>
      current.filter((row) => !isSystemGeneratedCurationRow(row)),
    );

    const result = await clearSystemGeneratedCurationRowsAction(artifactId);
    if (!result.success) {
      toast.error("Error al limpiar fuentes generadas");
      fetchCurationData();
    } else {
      toast.success("Fuentes generadas eliminadas");
    }
  };

  const clearInvalidRows = async () => {
    const result = await clearInvalidCurationRowsAction(artifactId);
    if (!result.success) {
      toast.error(result.error || "Error al limpiar fuentes no aptas");
      await fetchCurationData();
      return false;
    }
    if ((result.deleted || 0) > 0) {
      toast.success(`${result.deleted} fuente(s) no aptas eliminadas`);
    }
    await fetchCurationData();
    return true;
  };

  return {
    curation,
    rows,
    lessonRequirements,
    configuredPrompt,
    loading,
    isGenerating,
    isValidating,
    startCuration,
    clearSystemGeneratedRows,
    clearInvalidRows,
    refresh: fetchCurationData,
  };
}

