export async function assembleRemotionVideoAction(
  componentId: string,
  templateId: string,
  variables: Record<string, unknown>,
) {
  const { error: authError, supabase } = await getAuthorizedSupabase();
  if (authError) return { success: false, error: authError };

  const webSupabase = await createClient();
  const token = await getAccessToken(webSupabase);
  if (!token) return { success: false, error: "No se encontró un token de autenticación" };

  let rawComponent: any = null;
  try {
    const { data, error: fetchError } = await supabase
      .from("material_components")
      .select(
        `
          assets, content, type, material_lesson_id,
          material_lessons (
            lesson_id, lesson_title, module_title, module_id,
            materials (
              artifact_id
            )
          )
        `,
      )
      .eq("id", componentId)
      .single();

    if (fetchError || !data) {
      return { success: false, error: "No se encontró el componente" };
    }
    rawComponent = data;
  } catch (err: any) {
    return { success: false, error: err.message || "Error al buscar el componente" };
  }

  const component = rawComponent as ProductionComponentRecord | null;
  const currentAssets = (component?.assets || {}) as MaterialAssets;
  const normalizedAssets = normalizeAssemblyAssets(currentAssets, 30);
  const assetReadiness = getAssemblyAssetReadiness(currentAssets, ASSEMBLY_FPS);

  if (!assetReadiness.canRender) {
    const blockingIssue = assetReadiness.blockingIssues[0];
    return {
      success: false,
      code: blockingIssue?.code || "ASSEMBLY_PREFLIGHT_FAILED",
      error: blockingIssue?.message || "El preflight de ensamblado encontro assets incompletos.",
      preflight: assetReadiness,
    };
  }

  try {
    // Update component status to IN_PROGRESS
    const updatedAssets: MaterialAssets = {
      ...currentAssets,
      production_status: "IN_PROGRESS",
      updated_at: new Date().toISOString(),
    };

    const { error: updateError } = await supabase.rpc(
      "patch_material_component_assets",
      {
        p_component_id: componentId,
        p_assets_patch: buildMaterialAssetsPatch(currentAssets, updatedAssets),
      },
    );

    if (updateError) {
      console.error("[ProductionActions] Error setting production_status to IN_PROGRESS:", updateError);
      return { success: false, error: updateError.message };
    }

    const productionApiUrl = getProductionApiBaseUrl();
    console.log("[ProductionActions] Triggering assembly render via production API.", {
      productionApiUrl,
      componentId,
      templateId,
      normalizedAssets: {
        slidesCount: normalizedAssets.slides.length,
        brollClipsCount: normalizedAssets.brollClips.length,
        hasAvatarVideo: Boolean(normalizedAssets.avatarVideoUrl),
        hasVoiceAudio: Boolean(normalizedAssets.voiceAudioUrl || normalizedAssets.voiceClips.length > 0),
        totalDurationSeconds: normalizedAssets.totalDurationSeconds,
        avatarDurationSeconds: typeof currentAssets.avatar_video?.duration === "number"
          ? currentAssets.avatar_video.duration
          : null,
        voiceDurationSeconds: typeof currentAssets.voice_audio?.duration === "number"
          ? currentAssets.voice_audio.duration
          : normalizedAssets.voiceClips.length > 0
            ? normalizedAssets.voiceClips.reduce(
                (total, clip) => total + clip.durationInFrames / ASSEMBLY_FPS,
                0,
              )
            : null,
        preflightManifest: assetReadiness.manifest,
      },
      variablesKeys: Object.keys(variables || {}),
    });

    const response = await fetchWithDeadline(`${productionApiUrl}/api/v1/production/remotion/render`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "Authorization": `Bearer ${token}`,
      },
      body: JSON.stringify({
        componentId,
        templateId,
        variables
      }),
    }, PRODUCTION_API_MUTATION_TIMEOUT_MS);

    if (!response.ok) {
      const errorText = await readResponseTextWithLimit(response, PRODUCTION_API_ERROR_MAX_BYTES)
        .catch(() => "");
      let errorMessage = `HTTP Error ${response.status}`;
      let errorCode: string | undefined;
      try {
        const errorJson: unknown = JSON.parse(errorText);
        if (isRecord(errorJson)) {
          errorMessage = typeof errorJson.error === "string" ? errorJson.error : errorMessage;
          errorCode = typeof errorJson.code === "string" ? errorJson.code : undefined;
        }
      } catch (_) {}

      // Revert status to PENDING in case of request error
      await supabase.rpc("patch_material_component_assets", {
        p_component_id: componentId,
        p_assets_patch: {
          production_status: "PENDING",
          updated_at: new Date().toISOString(),
        },
      });

      return { success: false, error: errorMessage, code: errorCode };
    }

    const result = await readJsonResponseWithLimit<unknown>(
      response,
      PRODUCTION_API_RESPONSE_MAX_BYTES,
    );
    if (!isRecord(result)) {
      throw new Error("El API de render devolvio una respuesta invalida.");
    }
    if (result.status === "FAILED") {
      await supabase.rpc("patch_material_component_assets", {
        p_component_id: componentId,
        p_assets_patch: {
          production_status: "PENDING",
          updated_at: new Date().toISOString(),
        },
      });

      return {
        success: false,
        error: typeof result.message === "string"
          ? result.message
          : "El render fue rechazado por el proveedor",
        code: typeof result.code === "string" ? result.code : undefined,
      };
    }

    return {
      success: true,
      jobId: typeof result.jobId === "string" ? result.jobId : undefined,
      status: typeof result.status === "string" ? result.status : undefined,
      productionStatus: "IN_PROGRESS" as ProductionStatus
    };

  } catch (error: unknown) {
    console.error("[ProductionActions] Error initiating video assembly:", error);
    
    // Revert status to PENDING
    try {
      await supabase.rpc("patch_material_component_assets", {
        p_component_id: componentId,
        p_assets_patch: {
          production_status: "PENDING",
          updated_at: new Date().toISOString(),
        },
      });
    } catch (_) {}

    return { success: false, error: getErrorMessage(error) };
  }
}

export async function createRemotionAssemblyBatchAction(input: RenderBatchRequest) {
  return withProductionActionBoundary("Unhandled create assembly batch error", async () => {
    const parsed = renderBatchRequestSchema.safeParse(input);
    if (!parsed.success) {
      return { success: false, error: "Solicitud de batch invalida" };
    }

    const auth = await getAuthorizedSupabase();
    if (auth.error || !auth.user) return { success: false, error: auth.error || "Unauthorized" };

    const authorized = await getAuthorizedArtifactAdmin(parsed.data.artifactId);
    if (!authorized?.artifact?.organization_id) {
      return { success: false, error: "No autorizado para ensamblar este artefacto" };
    }

    const organizationIds = await getAuthenticatedOrganizationIds(
      auth.user.userId,
      authorized.artifact.organization_id,
    )(authorized.admin);
    const service = new RenderBatchService(authorized.admin);
    const batch = await service.createBatch(parsed.data, {
      userId: auth.user.userId,
      organizationIds,
    });

