          >
            {isUploading ? <Loader2 size={10} className="animate-spin" /> : <Upload size={10} />}
            <span>MP4</span>
          </button>
          
          {/* <button
            onClick={() => setIsModalOpen(true)}
            className="flex items-center gap-1 rounded-lg border border-[var(--engine-accent)]/30 bg-[var(--engine-accent)]/5 px-2.5 py-1.5 text-[10px] font-bold text-[var(--engine-accent)] hover:bg-[var(--engine-accent)]/10 transition-all cursor-pointer"
          >
            <Search size={10} />
            <span>Artlist</span>
          </button> */}
 
          <button
            onClick={() => setIsDriveModalOpen(true)}
            className="flex items-center gap-1 rounded-lg border border-blue-200 bg-blue-50/50 px-2.5 py-1.5 text-[10px] font-bold text-blue-700 hover:bg-blue-100/70 transition-all cursor-pointer"
          >
            <HardDrive size={10} />
            <span>Drive</span>
          </button>
        </div>
      </div>

      <p className="mt-2 text-[10px] text-gray-500 dark:text-gray-400">
        MP4 o WebM · carga reanudable hasta 2 GiB · máximo 1920 px en el lado mayor.
      </p>
 
      {clips.length > 0 && (
        <div className="mt-3 grid gap-2 border-t border-gray-100 pt-3 dark:border-[var(--engine-muted)]/10 sm:grid-cols-2">
          {clips.map((clip) => (
            <div
              key={clip.id}
              className="relative"
            >
              <ProductionMediaPreview
                durationSeconds={clip.duration}
                kind="video"
                label={clip.file_name || `B-Roll ${clip.order}`}
                src={clip.public_url}
              />
              <button
                onClick={() => onDelete(clip.id)}
                className="absolute right-1 top-1 z-10 rounded bg-black/70 p-1 text-white transition-colors hover:bg-red-600"
                title="Eliminar clip"
              >
                <X size={12} />
              </button>
            </div>
          ))}
