        `Alineó ${plan.visualClipCount} elemento${plan.visualClipCount === 1 ? "" : "s"} visual${plan.visualClipCount === 1 ? "" : "es"} ${target === "CANVAS" ? "al canvas" : "a la selección"}.`,
