const rate = 48000;
const quantum = 128 * 1000 / rate;
const tolerance = 1000 / 30;
const evaluate = (witness: unknown, origin = 0, count = 1) => evaluateMediaBoundaries(witness, origin, rate, quantum, tolerance, count);

