function createDocument() {
  return createInitialCompositionDocument({
    animatedDeck: null,
    assets: [{
      checksum: "f".repeat(64),
      durationSeconds: 10,
      fileSizeBytes: 1024,
      hasAudio: false,
      mimeType: "video/mp4",
      productionAssetId: "70000000-0000-4000-8000-000000000001",
      publicUrl: null,
