import { CONFORMANCE_EVIDENCE_STORAGE } from "./composition-conformance-evidence-package";
import { AUDIO_EVIDENCE_LIMITS, audioEvidenceHashSchema, audioEvidenceReceiptSchema, audioEvidenceRecordSchema,
  audioEvidenceSha256, audioEvidenceStoragePath, validateAudioEvidenceBytes } from "./composition-audio-evidence-contract";

/** Internal worker read. Scope must come from an authorized job, not arbitrary user input. */
export async function readPersistedAudioConformanceEvidence(params: {
  supabase: SupabaseClient<any, any, any>; organizationId: string; revisionId: string;
  visualChecksum: string; checksum: string; outputParentDirectory: string;
}) {
  z.string().uuid().parse(params.organizationId); z.string().uuid().parse(params.revisionId);
  audioEvidenceHashSchema.parse(params.visualChecksum); audioEvidenceHashSchema.parse(params.checksum);
  const result = await params.supabase.rpc("read_hyperframes_audio_conformance_evidence", {
    p_organization_id: params.organizationId, p_revision_id: params.revisionId,
    p_visual_checksum: params.visualChecksum, p_bundle_sha256: params.checksum,
  });
  if (result.error || !result.data) throw new Error("AUDIO_EVIDENCE_RECORD_UNAVAILABLE");
  const record = audioEvidenceRecordSchema.parse(result.data);
  const storagePath = audioEvidenceStoragePath(params.organizationId, params.revisionId, params.visualChecksum, params.checksum);
  if (record.organizationId !== params.organizationId || record.revisionId !== params.revisionId
    || record.visualChecksum !== params.visualChecksum || record.checksum !== params.checksum || record.storagePath !== storagePath
    || record.receipt.organizationId !== record.organizationId || record.receipt.revisionId !== record.revisionId
    || record.receipt.projectHash !== record.projectHash || record.receipt.documentHash !== record.documentHash
    || record.receipt.visualChecksum !== record.visualChecksum) throw new Error("AUDIO_EVIDENCE_CONTEXT_MISMATCH");
  const downloaded = await params.supabase.storage.from(CONFORMANCE_EVIDENCE_STORAGE.bucket).download(storagePath);
  if (downloaded.error || !downloaded.data || downloaded.data.size !== record.sizeBytes) throw new Error("AUDIO_EVIDENCE_DOWNLOAD_FAILED");
  const bytes = Buffer.from(await downloaded.data.arrayBuffer());
  if (bytes.length !== record.sizeBytes || audioEvidenceSha256(bytes) !== record.checksum) throw new Error("AUDIO_EVIDENCE_STORAGE_MISMATCH");
  const zip = await JSZip.loadAsync(bytes);
  const limits = new Map([["audio-reference.wav", record.receipt.schemaVersion === 1 ? AUDIO_EVIDENCE_LIMITS.legacyWavBytes : AUDIO_EVIDENCE_LIMITS.wavBytes],
    ["audio-reference-metadata.json", AUDIO_EVIDENCE_LIMITS.jsonBytes], ["audio-reference-receipt.json", AUDIO_EVIDENCE_LIMITS.jsonBytes]]);
  const entries = Object.values(zip.files);
  if (entries.length !== limits.size || entries.some((entry) => entry.dir || !limits.has(entry.name)
    || entry.unsafeOriginalName !== entry.name)) throw new Error("AUDIO_EVIDENCE_ARCHIVE_INVALID");
  const files = new Map<string, Buffer>();
  for (const [name, maximum] of limits) {
    let size = 0; const chunks: Buffer[] = [];
    await pipeline(zip.file(name)!.nodeStream("nodebuffer"), new Writable({ write(chunk: Buffer, _encoding, callback) {
      size += chunk.length;
      if (size > maximum) callback(new Error("AUDIO_EVIDENCE_EXTRACTION_LIMIT"));
      else { chunks.push(chunk); callback(); }
    } }));
    files.set(name, Buffer.concat(chunks));
  }
  const receipt = audioEvidenceReceiptSchema.parse(JSON.parse(files.get("audio-reference-receipt.json")!.toString("utf8")));
  if (!isDeepStrictEqual(receipt, record.receipt)) throw new Error("AUDIO_EVIDENCE_RECEIPT_MISMATCH");
  const metadata = validateAudioEvidenceBytes({ wav: files.get("audio-reference.wav")!, receipt, contract: record.contract,
    metadata: JSON.parse(files.get("audio-reference-metadata.json")!.toString("utf8")) });
  const directory = await mkdtemp(join(params.outputParentDirectory, "conformance-audio-evidence-"));
  const cleanup = async () => {
    for (const name of limits.keys()) await rm(join(directory, name), { force: true });
    await rmdir(directory).catch((error: NodeJS.ErrnoException) => { if (error.code !== "ENOENT") throw error; });
  };
  try {
    for (const [name, content] of files) await writeFile(join(directory, name), content, { flag: "wx", mode: 0o600 });
    return { directory, receipt, metadata, contract: record.contract, checksum: record.checksum, audioReferencePath: join(directory, "audio-reference.wav"),
      audioReferenceMetadataPath: join(directory, "audio-reference-metadata.json"), cleanup };
  } catch (error) { await cleanup(); throw error; }
}

import type { SupabaseClient } from "@supabase/supabase-js";
import { createHash } from "node:crypto";
import { compositionConformanceContractSchema } from "../composition-preview-render-conformance";
import { eventBatchMeasurementIdentitySchema, eventBatchMeasurementPacketSchema,
  type EventBatchMeasurementAdapters, type EventBatchMeasurementIdentity } from "./composition-conformance-event-batch-execution";
import { prepareAndPersistVisualConformanceReference } from "./composition-conformance-reference-pipeline";
import { measureCompositionEventBatchWithPersistedReference } from "./composition-conformance-event-batch-measurement";
import { persistCompositionEventBatchMeasurement, readCompositionEventBatchMeasurement } from "./composition-conformance-event-batch-persistence";
import type {ComparisonProcessPorts} from "./composition-comparison-process-ports";
import {z} from "zod";

const defaultDependencies = {prepareVisual: prepareAndPersistVisualConformanceReference,
  measure: measureCompositionEventBatchWithPersistedReference,
  readPacket: readCompositionEventBatchMeasurement, persistPacket: persistCompositionEventBatchMeasurement};

/** Compose actual worker adapters. The root and local video must already pass revision/integrity verification. */
export function createPersistedCompositionEventBatchAdapters(params: {
  supabase: SupabaseClient<any, any, any>; supabaseUrl: string; rootIdentity: EventBatchMeasurementIdentity;
  outputParentDirectory: string; videoPath: string; renderReceiptPath: string; signal?: AbortSignal;
  processPorts?: ComparisonProcessPorts;
  visualReferenceChecksums?: string[];
  resolveRenderReceipt?: (contractSha256: string, batchIndex: number) => {path: string; sha256: string};
}, dependencies: typeof defaultDependencies = defaultDependencies): EventBatchMeasurementAdapters {
  const root = eventBatchMeasurementIdentitySchema.parse(params.rootIdentity);
  if (root.batch.batchIndex !== 0 || root.parentContractSha256 !== root.batchContractSha256) {
    throw new Error("CONFORMANCE_EVENT_ADAPTER_ROOT_REQUIRED");
  }
  const {supabase, supabaseUrl, outputParentDirectory, videoPath, renderReceiptPath, signal} = params;
  const visualReferences = params.visualReferenceChecksums === undefined ? undefined
    : z.array(z.string().regex(/^[a-f0-9]{64}$/)).length(root.batch.batchCount).parse(params.visualReferenceChecksums);
  if (visualReferences && !params.resolveRenderReceipt)
    throw new Error("CONFORMANCE_EVENT_ADAPTER_ADMITTED_RECEIPTS_REQUIRED_INVALID");
  const operations = {...dependencies};
  const captureChecksums = new Map<string, string>();
  const assertActive = () => {if (signal?.aborted) throw new Error("CONFORMANCE_EVENT_EXECUTION_ABORTED");};
  const validateIdentity = (input: unknown) => {
    assertActive();
    const identity = eventBatchMeasurementIdentitySchema.parse(input);
    const sameScope = (['organizationId', 'revisionId', 'projectHash', 'videoSha256', 'documentHash', 'parentContractSha256'] as const)
      .every((key) => identity[key] === root[key]);
    if (!sameScope || JSON.stringify({...identity.batch, batchIndex: 0}) !== JSON.stringify(root.batch)) {
      throw new Error("CONFORMANCE_EVENT_ADAPTER_SCOPE_MISMATCH");
    }
    if (Boolean(visualReferences) !== Boolean(identity.visualReferenceSha256)
      || visualReferences && identity.visualReferenceSha256 !== visualReferences[identity.batch.batchIndex])
      throw new Error("CONFORMANCE_EVENT_ADAPTER_REFERENCE_SELECTION_MISMATCH");
    return identity;
  };
  const identityKey = (identity: EventBatchMeasurementIdentity) => JSON.stringify(identity);
  return {
    async readBatch(input) {
      const identity = validateIdentity(input);
      const stored = await operations.readPacket({supabase, identity}); assertActive(); return stored;
    },
    async measureBatch(input) {
      const identity = validateIdentity(input.identity);
      const contract = compositionConformanceContractSchema.parse(input.contract);
      if (contract.documentHash !== identity.documentHash || contract.schemaVersion !== 4
        || JSON.stringify(contract.checkpointBatch) !== JSON.stringify(identity.batch)
        || createHash("sha256").update(JSON.stringify(contract)).digest("hex") !== identity.batchContractSha256) {
        throw new Error("CONFORMANCE_EVENT_ADAPTER_CONTRACT_MISMATCH");
      }
      const visual = identity.visualReferenceSha256 ? {organizationId: root.organizationId, revisionId: root.revisionId,
        projectHash: root.projectHash, documentHash: root.documentHash, checksum: identity.visualReferenceSha256}
        : await operations.prepareVisual({supabase, supabaseUrl, organizationId: root.organizationId,
          revisionId: root.revisionId, outputParentDirectory, signal, eventBatchIndex: identity.batch.batchIndex});
      assertActive();
      if (visual.organizationId !== root.organizationId || visual.revisionId !== root.revisionId
        || visual.projectHash !== root.projectHash || visual.documentHash !== root.documentHash) {
        throw new Error("CONFORMANCE_EVENT_ADAPTER_REFERENCE_MISMATCH");
      }
      const admittedReceipt = params.resolveRenderReceipt?.(identity.batchContractSha256, identity.batch.batchIndex);
      const packet = eventBatchMeasurementPacketSchema.parse(await operations.measure({identity: structuredClone(identity), contract: structuredClone(contract),
        comparison: {supabase, checksum: visual.checksum, outputParentDirectory, videoPath,
          renderReceiptPath: admittedReceipt?.path ?? renderReceiptPath,
          ...(admittedReceipt ? {expectedContractSha256: identity.batchContractSha256, expectedRenderReceiptSha256: admittedReceipt.sha256} : {}),
          signal, processPorts: params.processPorts}}));
      assertActive();
      if (identityKey(packet.identity) !== identityKey(identity)) throw new Error("CONFORMANCE_EVENT_ADAPTER_PACKET_MISMATCH");
      captureChecksums.set(identityKey(identity), visual.checksum);
      return packet;
    },
    async persistBatch(input) {
      const packet = eventBatchMeasurementPacketSchema.parse(input);
      const identity = validateIdentity(packet.identity), key = identityKey(identity);
      const visualChecksum = captureChecksums.get(key);
      if (!visualChecksum) throw new Error("CONFORMANCE_EVENT_ADAPTER_MEASUREMENT_REQUIRED");
      await operations.persistPacket({supabase, packet, visualChecksum});
      captureChecksums.delete(key); assertActive();
    },
  };
}

import { createHash } from "node:crypto";
import type { SupabaseClient } from "@supabase/supabase-js";
import { z } from "zod";
import { eventBatchMeasurementIdentitySchema, eventBatchMeasurementPacketSchema,
  hashEventBatchMeasurementPacket, persistedEventBatchMeasurementSchema } from "./composition-conformance-event-batch-execution";
import { eventBatchAuthorizationManifestSchema } from "../composition-conformance-batch-contract";
import { compositionConformanceContractSchema } from "../composition-preview-render-conformance";

export const EVENT_BATCH_PACKET_MAXIMUM_BYTES = 4 * 1024 * 1024;
const digestSchema = z.string().regex(/^[a-f0-9]{64}$/);
type WorkerDatabase = SupabaseClient<any, any, any>;
const canonicalHash = (value: unknown) => createHash("sha256").update(JSON.stringify(value)).digest("hex");

async function authorizeIdentity(supabase: WorkerDatabase, identity: z.infer<typeof eventBatchMeasurementIdentitySchema>) {
  const revision = await supabase.from("video_composition_revisions").select("id, organization_id, project_hash, manifest")
    .eq("id", identity.revisionId).eq("organization_id", identity.organizationId).maybeSingle();
  const row = revision.data;
  if (revision.error || !row || row.id !== identity.revisionId || row.organization_id !== identity.organizationId
    || row.project_hash !== identity.projectHash || row.manifest?.conformance_reference_version !== 1) {
    throw new Error("CONFORMANCE_EVENT_PACKET_REVISION_UNAVAILABLE");
  }
  const parent = compositionConformanceContractSchema.parse(row.manifest.conformance_contract);
  const authorization = eventBatchAuthorizationManifestSchema.parse(row.manifest.conformance_event_batch_authorization);
  if (parent.schemaVersion !== 4 || !parent.checkpointBatch || parent.documentHash !== identity.documentHash
    || canonicalHash(parent) !== identity.parentContractSha256 || authorization.documentHash !== identity.documentHash
    || authorization.parentContractSha256 !== identity.parentContractSha256
    || JSON.stringify(parent.checkpointBatch) !== JSON.stringify(authorization.rootBatch)
    || JSON.stringify({...identity.batch, batchIndex: 0}) !== JSON.stringify(authorization.rootBatch)
    || authorization.batchContractSha256[identity.batch.batchIndex] !== identity.batchContractSha256) {
    throw new Error("CONFORMANCE_EVENT_PACKET_AUTHORIZATION_MISMATCH");
  }
}

/** Internal worker only. DB stores bounded measurement packets, never a trusted PASS verdict. */
export async function persistCompositionEventBatchMeasurement(params: {
  supabase: WorkerDatabase; packet: unknown; visualChecksum: string;
}) {
  const supabase = params.supabase;
  const packet = eventBatchMeasurementPacketSchema.parse(params.packet);
  const visualChecksum = digestSchema.parse(params.visualChecksum);
  if (packet.identity.visualReferenceSha256 && packet.identity.visualReferenceSha256 !== visualChecksum)
    throw new Error("CONFORMANCE_EVENT_PACKET_REFERENCE_MISMATCH");
  if (Buffer.byteLength(JSON.stringify(packet)) > EVENT_BATCH_PACKET_MAXIMUM_BYTES) throw new Error("CONFORMANCE_EVENT_PACKET_SIZE_LIMIT");
  await authorizeIdentity(supabase, packet.identity);
  const packetSha256 = hashEventBatchMeasurementPacket(packet);
  const recorded = await supabase.rpc(packet.identity.visualReferenceSha256
    ? "record_hyperframes_selected_event_batch_measurement" : "record_hyperframes_event_batch_measurement", {
    p_identity: packet.identity, p_packet: packet, p_packet_sha256: packetSha256, p_visual_sha256: visualChecksum,
  });
  if (recorded.error || recorded.data !== packetSha256) throw new Error("CONFORMANCE_EVENT_PACKET_RECORD_FAILED");
  return {packetSha256};
}

/** Null means no matching packet, not a transport or authorization failure. */
export async function readCompositionEventBatchMeasurement(params: {supabase: WorkerDatabase; identity: unknown}) {
  const supabase = params.supabase;
  const identity = eventBatchMeasurementIdentitySchema.parse(params.identity);
  await authorizeIdentity(supabase, identity);
  const recorded = await supabase.rpc(identity.visualReferenceSha256
    ? "read_hyperframes_selected_event_batch_measurement" : "read_hyperframes_event_batch_measurement", {p_identity: identity});
  if (recorded.error) throw new Error("CONFORMANCE_EVENT_PACKET_READ_FAILED");
  if (recorded.data === null) return null;
  if (recorded.data === undefined || Buffer.byteLength(JSON.stringify(recorded.data)) > EVENT_BATCH_PACKET_MAXIMUM_BYTES + 256) {
    throw new Error("CONFORMANCE_EVENT_PACKET_SIZE_LIMIT");
  }
  const stored = persistedEventBatchMeasurementSchema.parse(recorded.data);
  if (canonicalHash(stored.packet.identity) !== canonicalHash(identity)
    || hashEventBatchMeasurementPacket(stored.packet) !== stored.packetSha256) {
    throw new Error("CONFORMANCE_EVENT_PACKET_READBACK_MISMATCH");
  }
  return stored;
}

import { createHash } from "node:crypto";
import type { SupabaseClient } from "@supabase/supabase-js";
