        ...(capture ? [Promise.resolve().then(() => capture!.cleanup())] : []),
        ...(materialized ? [Promise.resolve().then(() => materialized!.cleanup())] : []),
      ]);
      if (cleanups.some((result) => result.status === "rejected")) throw recordConformanceCleanupFailure(primaryFailure);
    }
  }
}

import {createHash} from "node:crypto";
import type {SupabaseClient} from "@supabase/supabase-js";
import {CompositionRenderAuthorityService} from "./composition-render-authority.service";
import {renderCheckpointScopeSchema, CONTROLLED_RENDER_CHECKPOINT_POLICY, type RenderCheckpointScope} from "./composition-render-checkpoint";
import type {ControlledSupervisorArtifacts} from "./composition-render-supervisor-binding";
import {assertConformanceJobActive} from "./composition-conformance-job-lease";

/** Trusted host reservation, never inferred from a receipt, URL or unscoped latest execution. */
export type ConformanceRenderEvidenceReservation = {
  scope: RenderCheckpointScope;
  artifacts: ControlledSupervisorArtifacts;
};
const digest = (value: unknown) => createHash("sha256").update(JSON.stringify(value), "utf8").digest("hex");

/** Read-only admission of previously consumed issuer/output evidence. Does not consume, sign or render. */
export async function recoverConformanceRenderEvidence(params: {
  supabase: SupabaseClient<any, any, any>;
  reservation: ConformanceRenderEvidenceReservation;
  jobScope: {organizationId: string; requestId: string; revisionId: string};
  integrity: {documentHash: string; checksum: string; sizeBytes: number};
  videoPath: string;
  signal?: AbortSignal;
}, clock: () => number = Date.now) {
  assertConformanceJobActive(params.signal);
  if (Buffer.byteLength(JSON.stringify(params.reservation), "utf8") > CONTROLLED_RENDER_CHECKPOINT_POLICY.maximumBytes)
    throw new Error("CONFORMANCE_JOB_RENDER_EVIDENCE_LIMIT_EXCEEDED");
  const reservation = structuredClone(params.reservation);
  const scope = renderCheckpointScopeSchema.parse(reservation.scope);
  if ((["organizationId", "requestId", "revisionId"] as const).some(key => scope[key] !== params.jobScope[key]))
    throw new Error("CONFORMANCE_JOB_RENDER_EVIDENCE_SCOPE_MISMATCH");
  const recovered = await new CompositionRenderAuthorityService(params.supabase, clock).recover({
    scope, artifacts: reservation.artifacts, videoPath: params.videoPath,
  });
  assertConformanceJobActive(params.signal);
  const binding = recovered.provenance.binding;
  if (binding.documentHash !== params.integrity.documentHash || binding.videoSha256 !== params.integrity.checksum
    || binding.sizeBytes !== params.integrity.sizeBytes)
    throw new Error("CONFORMANCE_JOB_RENDER_EVIDENCE_INTEGRITY_MISMATCH");
  const batches = "receipt" in recovered ? [recovered] : recovered.artifacts;
  return {
    scope: "CONSUMED_SUPERVISOR_ISSUER_OUTPUT_NOT_ISOLATION_OR_CONFORMANCE" as const,
    projectHash: binding.projectHash,
    contractSha256: binding.contractSha256,
    supervisorReceiptSha256: recovered.provenance.receiptSha256,
    binding: structuredClone(binding),
    batches: batches.map((batch, batchIndex) => ({batchIndex, contractSha256: digest(batch.contract),
      receiptSha256: digest(batch.receipt), receipt: structuredClone(batch.receipt)})),
  };
}

import {createHash} from "node:crypto";
import type {SupabaseClient} from "@supabase/supabase-js";
import {z} from "zod";
import {CONTROLLED_RENDER_CHECKPOINT_POLICY, controlledCheckpointArtifactsSchema, parseControlledRenderCheckpoint,
  renderCheckpointScopeSchema, type ControlledRenderCheckpoint} from "./composition-render-checkpoint";
import {renderSupervisorBindingSchema} from "../composition-render-supervisor-receipt";
import {buildControlledSupervisorBinding} from "./composition-render-supervisor-binding";
import {bindControlledReferenceSelection, controlledReferenceSelectionSchema} from "./composition-controlled-reference-selection";
import {compositionConformanceContractSchema} from "../composition-preview-render-conformance";
import {assertConformanceJobActive, CONFORMANCE_JOB_LEASE_POLICY} from "./composition-conformance-job-lease";
import {conformanceJobClaimSchema, type ConformanceJobClaim} from "./composition-conformance-job-worker";

const hash = z.string().regex(/^[a-f0-9]{64}$/);
const reservationSchema = z.object({version: z.literal(1), policy: z.literal("EXACT_JOB_RENDER_RESERVATION_V1"),
  jobId: z.string().uuid(), scope: renderCheckpointScopeSchema, binding: renderSupervisorBindingSchema,
  supervisorReceiptSha256: hash, artifacts: controlledCheckpointArtifactsSchema,
  referenceSelection: controlledReferenceSelectionSchema}).strict();
export type ConformanceRenderReservation = z.output<typeof reservationSchema>;
type JobScope = Pick<ConformanceJobClaim, "id" | "organization_id" | "request_id" | "revision_id">;
const digest = (bytes: string) => createHash("sha256").update(bytes, "utf8").digest("hex");

function validateReservationInputs(reservation: Omit<ConformanceRenderReservation, "jobId" | "policy" | "version">,
  job: Omit<JobScope, "id">) {
  const {scope, binding, artifacts} = reservation;
  if (scope.organizationId !== job.organization_id
    || scope.requestId !== job.request_id || scope.revisionId !== job.revision_id
    || Object.entries(scope).some(([field, value]) => binding[field as keyof typeof scope] !== value))
    throw new Error("CONFORMANCE_JOB_RESERVATION_SCOPE_MISMATCH");
  const contract = compositionConformanceContractSchema.parse(artifacts.kind === "SINGLE_CONTRACT"
    ? artifacts.input.contract : artifacts.input.parentContract);
  const derived = buildControlledSupervisorBinding({...binding, contract}, artifacts,
    {sha256: binding.videoSha256, sizeBytes: binding.sizeBytes});
  const selection = bindControlledReferenceSelection({organizationId: scope.organizationId,
    revisionId: scope.revisionId, executionId: scope.executionId, documentHash: binding.documentHash,
    projectHash: binding.projectHash, contract}, reservation.referenceSelection.references);
  if (JSON.stringify(derived) !== JSON.stringify(binding)
    || JSON.stringify(selection) !== JSON.stringify(reservation.referenceSelection))
    throw new Error("CONFORMANCE_JOB_RESERVATION_BINDING_INVALID");
  return reservation;
}

function parseReservation(raw: unknown, job: JobScope) {
  const reservation = reservationSchema.parse(raw);
  if (reservation.jobId !== job.id) throw new Error("CONFORMANCE_JOB_RESERVATION_SCOPE_MISMATCH");
  validateReservationInputs(reservation, job);
  return reservation;
}

const deferredSchema = reservationSchema.omit({jobId: true, policy: true}).extend({
  policy: z.literal("EXACT_RENDER_RESERVATION_OUTBOX_V1"),
}).strict();

/** Immutable DB reservation. Contains no lease, private key, retained path or credentials.
 * The consumed authority ledger still authenticates signature/revocation/output at measurement time. */
export class CompositionConformanceRenderReservationService {
  constructor(private readonly supabase: SupabaseClient<any, any, any>) {}

  /** Consumed checkpoint transport before upload/finalization. Does not invent a job ID.
   * DB attaches this exact payload when the integrity-triggered conformance job exists. */
  async defer(raw: ControlledRenderCheckpoint, signal?: AbortSignal) {
    assertConformanceJobActive(signal);
    const checkpoint = parseControlledRenderCheckpoint(raw, raw.scope);
    if (!checkpoint.referenceSelection) throw new Error("CONFORMANCE_JOB_RESERVATION_REFERENCES_REQUIRED_INVALID");
    const reservation = deferredSchema.parse({version: 1, policy: "EXACT_RENDER_RESERVATION_OUTBOX_V1",
      scope: checkpoint.scope, binding: checkpoint.supervisorReceipt.payload.binding,
      supervisorReceiptSha256: digest(JSON.stringify(checkpoint.supervisorReceipt)), artifacts: checkpoint.artifacts,
      referenceSelection: checkpoint.referenceSelection});
    validateReservationInputs(reservation, {organization_id: checkpoint.scope.organizationId,
      request_id: checkpoint.scope.requestId, revision_id: checkpoint.scope.revisionId});
    const bytes = JSON.stringify(reservation), sha256 = digest(bytes);
    if (Buffer.byteLength(bytes, "utf8") > CONTROLLED_RENDER_CHECKPOINT_POLICY.maximumBytes)
      throw new Error("CONFORMANCE_JOB_RESERVATION_LIMIT_EXCEEDED");
    const result = await this.rpc("stage_hyperframes_conformance_render_reservation", {
      p_organization_id: checkpoint.scope.organizationId, p_request_id: checkpoint.scope.requestId,
      p_revision_id: checkpoint.scope.revisionId, p_execution_id: checkpoint.scope.executionId,
      p_reservation_text: bytes, p_reservation_sha256: sha256,
    }, signal);
    assertConformanceJobActive(signal);
    if (result.error || result.data !== sha256) throw new Error("CONFORMANCE_JOB_RESERVATION_WRITE_UNCONFIRMED");
    return {sha256};
  }

  async publish(job: JobScope, raw: ControlledRenderCheckpoint, signal?: AbortSignal) {
    assertConformanceJobActive(signal);
    const checkpoint = parseControlledRenderCheckpoint(raw, raw.scope);
    if (!checkpoint.referenceSelection) throw new Error("CONFORMANCE_JOB_RESERVATION_REFERENCES_REQUIRED_INVALID");
    const reservation = parseReservation({version: 1, policy: "EXACT_JOB_RENDER_RESERVATION_V1", jobId: job.id,
      scope: checkpoint.scope, binding: checkpoint.supervisorReceipt.payload.binding,
      supervisorReceiptSha256: digest(JSON.stringify(checkpoint.supervisorReceipt)), artifacts: checkpoint.artifacts,
      referenceSelection: checkpoint.referenceSelection}, job);
    const bytes = JSON.stringify(reservation);
    if (Buffer.byteLength(bytes, "utf8") > CONTROLLED_RENDER_CHECKPOINT_POLICY.maximumBytes)
      throw new Error("CONFORMANCE_JOB_RESERVATION_LIMIT_EXCEEDED");
    const sha256 = digest(bytes);
    const result = await this.rpc("register_hyperframes_conformance_render_reservation", {
      p_job_id: job.id, p_organization_id: job.organization_id, p_request_id: job.request_id,
      p_revision_id: job.revision_id, p_reservation_text: bytes, p_reservation_sha256: sha256,
    }, signal);
    assertConformanceJobActive(signal);
    if (result.error || result.data !== sha256) throw new Error("CONFORMANCE_JOB_RESERVATION_WRITE_UNCONFIRMED");
    return {reservation, sha256};
  }

  async read(rawClaim: ConformanceJobClaim, signal?: AbortSignal) {
    assertConformanceJobActive(signal);
    const claim = conformanceJobClaimSchema.parse(rawClaim);
    const result = await this.rpc("read_hyperframes_conformance_render_reservation", {
      p_job_id: claim.id, p_lease_token: claim.lease_token, p_organization_id: claim.organization_id,
      p_request_id: claim.request_id, p_revision_id: claim.revision_id,
    }, signal);
    assertConformanceJobActive(signal);
    if (result.error || !result.data) throw new Error("CONFORMANCE_JOB_RESERVATION_UNAVAILABLE");
    const response = z.object({reservationText: z.string(), sha256: hash}).strict().parse(result.data);
    if (Buffer.byteLength(response.reservationText, "utf8") > CONTROLLED_RENDER_CHECKPOINT_POLICY.maximumBytes
      || digest(response.reservationText) !== response.sha256)
      throw new Error("CONFORMANCE_JOB_RESERVATION_INTEGRITY_INVALID");
    return {reservation: parseReservation(JSON.parse(response.reservationText), claim), sha256: response.sha256};
  }

  private async rpc(name: string, args: Record<string, unknown>, signal?: AbortSignal) {
    const timeout = AbortSignal.timeout(CONFORMANCE_JOB_LEASE_POLICY.renewalTimeoutMs);
    const bounded = signal ? AbortSignal.any([signal, timeout]) : timeout;
    assertConformanceJobActive(bounded);
    try {
      const result = await this.supabase.rpc(name, args).abortSignal(bounded);
      assertConformanceJobActive(bounded);
      return result;
    } catch {throw new Error("CONFORMANCE_JOB_RESERVATION_RPC_UNCONFIRMED");}
  }
}

import type { SupabaseClient } from "@supabase/supabase-js";
import { z } from "zod";
import { HYPERFRAMES_SOURCE_BUCKETS } from "../../media-storage.config";
import { HYPERFRAMES_CLOUD_ARCHIVE_LIMIT_BYTES } from "../../hyperframes/hyperframes.types";
import { materializeConformanceReference } from "./composition-conformance-materialization";
import {assertConformanceJobActive} from "./composition-conformance-job-lease";

export const CONFORMANCE_STORAGE_READ_TIMEOUT_MS = 15 * 60 * 1000;

const revisionSchema = z.object({
  id: z.string().uuid(), organization_id: z.string().uuid(), composition_id: z.string().uuid(),
  project_hash: z.string().regex(/^[a-f0-9]{64}$/), project_archive_size_bytes: z.number().int().positive().max(HYPERFRAMES_CLOUD_ARCHIVE_LIMIT_BYTES),
  project_storage_bucket: z.literal("production-assets"), project_storage_path: z.string(),
  manifest: z.object({ conformance_reference_version: z.literal(1) }).passthrough(),
}).passthrough();

export function assertConformanceStorageUrl(rawUrl: string, supabaseUrl: string, bucket: string, objectPath: string) {
  const project = new URL(supabaseUrl); const url = new URL(rawUrl);
  const hosted = /^([a-z0-9-]+)\.supabase\.co$/i.exec(project.hostname);
  const storageOrigin = hosted ? `https://${hosted[1]}.storage.supabase.co` : project.origin;
  const local = project.protocol === "http:" && ["127.0.0.1", "localhost"].includes(project.hostname);
  const expectedPath = `/storage/v1/object/sign/${encodeURIComponent(bucket)}/${objectPath.split("/").map(encodeURIComponent).join("/")}`;
  if ((!HYPERFRAMES_SOURCE_BUCKETS.has(bucket)) || !objectPath || objectPath.startsWith("/") || objectPath.includes("..") || objectPath.includes("\\")
    || url.username || url.password || (url.protocol !== "https:" && !(local && url.origin === project.origin))
    || ![project.origin, storageOrigin].includes(url.origin) || url.pathname !== expectedPath || !url.searchParams.get("token")) {
    throw new Error("CONFORMANCE_MATERIALIZATION_STORAGE_URL_INVALID");
  }
}

/** Internal worker adapter. Caller must authorize organization scope before using service-role credentials. */
export async function materializeAuthorizedConformanceRevision(params: {
  supabase: SupabaseClient<any, any, any>; supabaseUrl: string; organizationId: string; revisionId: string;
  outputParentDirectory: string; fetchImpl?: typeof fetch; signal?: AbortSignal;
}) {
  assertConformanceJobActive(params.signal);
  const cancellation = new AbortController();
  const cancel = () => cancellation.abort(new Error("CONFORMANCE_JOB_EXECUTION_CANCELLED"));
  params.signal?.addEventListener("abort", cancel, {once: true});
  if (params.signal?.aborted) cancel();
  const timeout = setTimeout(() => cancellation.abort(new Error("CONFORMANCE_MATERIALIZATION_DEADLINE_EXCEEDED")),
    CONFORMANCE_STORAGE_READ_TIMEOUT_MS);
  const assertActive = () => {
    if (cancellation.signal.aborted) throw cancellation.signal.reason;
  };
  try {return await materializeActiveRevision({...params, signal: cancellation.signal});}
  catch (error) {assertActive(); throw error;}
  finally {clearTimeout(timeout); params.signal?.removeEventListener("abort", cancel);}
}

async function materializeActiveRevision(params: Parameters<typeof materializeAuthorizedConformanceRevision>[0]
  & {signal: AbortSignal}): Promise<Awaited<ReturnType<typeof materializeConformanceReference>>> {
  const assertActive = () => {if (params.signal.aborted) throw params.signal.reason;};
  z.string().uuid().parse(params.organizationId); z.string().uuid().parse(params.revisionId);
  assertActive();
  const { data, error } = await params.supabase.from("video_composition_revisions")
    .select("id, organization_id, composition_id, project_hash, project_archive_size_bytes, project_storage_bucket, project_storage_path, manifest")
    .eq("id", params.revisionId).eq("organization_id", params.organizationId).maybeSingle();
  assertActive();
  if (error || !data) throw new Error("CONFORMANCE_MATERIALIZATION_REVISION_UNAVAILABLE");
  const revision = revisionSchema.parse(data);
  if (revision.id !== params.revisionId || revision.organization_id !== params.organizationId
    || revision.project_storage_path !== `composition-snapshots/${params.organizationId}/${revision.composition_id}/${revision.project_hash}.zip`) {
    throw new Error("CONFORMANCE_MATERIALIZATION_REVISION_MISMATCH");
  }
  const readObject = async (bucket: string, storedPath: string) => {
    assertActive();
    const objectPath = storedPath.startsWith(`${bucket}/`) ? storedPath.slice(bucket.length + 1) : storedPath;
    if (!HYPERFRAMES_SOURCE_BUCKETS.has(bucket) || !objectPath || objectPath.includes("..") || objectPath.includes("\\") || objectPath.startsWith("/")) {
      throw new Error("CONFORMANCE_MATERIALIZATION_STORAGE_PATH_INVALID");
    }
    const { data: signed, error: signError } = await params.supabase.storage.from(bucket).createSignedUrl(objectPath, 900);
    assertActive();
    if (signError || !signed?.signedUrl) throw new Error("CONFORMANCE_MATERIALIZATION_SIGN_FAILED");
    assertConformanceStorageUrl(signed.signedUrl, params.supabaseUrl, bucket, objectPath);
    const response = await (params.fetchImpl ?? fetch)(signed.signedUrl, {redirect: "error", signal: params.signal});
    if (params.signal.aborted) {
      try {await response.body?.cancel();} catch { /* Keep the canonical cancellation reason. */ }
      assertActive();
    }
    return response;
  };
  const response = await readObject(revision.project_storage_bucket, revision.project_storage_path);
  if (response.status !== 200 || !response.body || response.headers.has("content-range")
    || response.headers.get("content-length") !== null && response.headers.get("content-length") !== String(revision.project_archive_size_bytes)) {
    await response.body?.cancel(); throw new Error("CONFORMANCE_MATERIALIZATION_ARCHIVE_RESPONSE_INVALID");
  }
  const chunks: Buffer[] = []; let bytes = 0; const reader = response.body.getReader();
  const cancelRead = () => {void reader.cancel().catch(() => {});};
  params.signal.addEventListener("abort", cancelRead, {once: true});
  try {
    assertActive();
    while (true) {
      const chunk = await reader.read(); assertActive(); if (chunk.done) break;
      bytes += chunk.value.byteLength;
      if (bytes > revision.project_archive_size_bytes) throw new Error("CONFORMANCE_MATERIALIZATION_ARCHIVE_SIZE_MISMATCH");
      chunks.push(Buffer.from(chunk.value));
    }
  } catch (error) {try {await reader.cancel();} catch { /* Preserve primary failure. */ } throw error; }
  finally {params.signal.removeEventListener("abort", cancelRead); reader.releaseLock();}
  if (bytes !== revision.project_archive_size_bytes) throw new Error("CONFORMANCE_MATERIALIZATION_ARCHIVE_SIZE_MISMATCH");
  const archiveBytes = Buffer.concat(chunks); chunks.length = 0;
  assertActive();
  return await materializeConformanceReference({
    archiveBytes, expectedProjectHash: revision.project_hash,
    organizationId: params.organizationId, revisionId: params.revisionId, outputParentDirectory: params.outputParentDirectory,
    readAsset: (binding) => readObject(binding.storageBucket, binding.storagePath),
    signal: params.signal,
  });
}

import type { SupabaseClient } from "@supabase/supabase-js";
import { z } from "zod";
import { verifyCompositionHtmlEditingRead } from "../composition-html-editing-reader.service";
import { HTML_EDITING_REPOSITORY_POLICY } from "../composition-html-editing-repository-policy";
import { htmlEditingImageIdentitiesSchema } from "../composition-html-editing-image-identity";
import { controlledRenderQueueClaimSchema, type ControlledRenderQueueClaim } from "./composition-controlled-render-worker-contract";
import type { materializeControlledRenderRevision } from "./composition-controlled-render-materialization";

type Resolver = NonNullable<Parameters<typeof materializeControlledRenderRevision>[0]["readHtmlEditingAuthority"]>;
const responseSchema = z.object({ documentId: z.string().uuid(), compilation: z.unknown(),
  imageAssets: htmlEditingImageIdentitiesSchema }).strict();

/** Claim-bound service-only reader. SQL resolves actor/draft from stored lineage,
 * checks current lease and role/grants, and returns exact historical pointers in
 * one transaction. No archive or caller actor is accepted as authorization. */
export function createControlledHtmlEditingAuthorityReader(input: {
  supabase: SupabaseClient<any, any, any>; claim: ControlledRenderQueueClaim;
}): Resolver {
  const claim = controlledRenderQueueClaimSchema.parse(input.claim);
  return async request => {
    request.signal?.throwIfAborted();
    if (claim.action !== "EXECUTE" || request.organizationId !== claim.organizationId || request.revisionId !== claim.revisionId
      || request.documentHash !== claim.contract.documentHash) throw new Error("CONTROLLED_RENDER_HTML_LINEAGE_MISMATCH");
    const timeout = AbortSignal.timeout(HTML_EDITING_REPOSITORY_POLICY.rpcTimeoutMs);
    const signal = request.signal ? AbortSignal.any([request.signal, timeout]) : timeout;
    let data: unknown;
    try {
      const result = await input.supabase.rpc("read_controlled_render_html_editing_authority", {
        p_organization_id: claim.organizationId, p_request_id: claim.requestId, p_revision_id: claim.revisionId,
        p_production_job_id: claim.productionJobId, p_worker_lease_token: claim.leaseToken,
        p_document_hash: request.documentHash,
      }).abortSignal(signal);
      signal.throwIfAborted();
      if (result.error) throw new Error();
      data = result.data;
    } catch {
      request.signal?.throwIfAborted();
      throw new Error("CONTROLLED_RENDER_HTML_AUTHORITY_UNAVAILABLE");
    }
    try {
      if (Buffer.byteLength(JSON.stringify(data) ?? "", "utf8") > HTML_EDITING_REPOSITORY_POLICY.responseBytes) throw new Error();
      const response = responseSchema.parse(data);
      const { context } = verifyCompositionHtmlEditingRead({ organizationId: claim.organizationId,
        documentId: response.documentId, documentHash: request.documentHash, response: response.compilation });
      const grantedIds = new Set(context.revisions.flatMap(revision => [...revision.grantedAssetIds]));
      if (response.imageAssets.length !== grantedIds.size
        || response.imageAssets.some(image => !grantedIds.has(image.productionAssetId))) throw new Error();
      return { scope: { organizationId: context.organizationId, documentId: context.documentId },
        imageAssets: response.imageAssets,
        authorities: context.revisions.map(({ authoritativeBinding, grantedAssetIds, imageSources }) =>
          ({ authoritativeBinding, grantedAssetIds, imageSources })) };
    } catch { throw new Error("CONTROLLED_RENDER_HTML_AUTHORITY_INVALID"); }
  };
}

import {createHash} from "node:crypto";
import type {SupabaseClient} from "@supabase/supabase-js";
import {z} from "zod";
import {CompositionRenderAuthorityService} from "./composition-render-authority.service";
import {CONTROLLED_RENDER_STORAGE, controlledRenderObjectPath} from "./composition-controlled-render-storage-policy";
import {controlledWorkerLeaseArguments} from "./composition-controlled-render-worker-contract";

const bucket = CONTROLLED_RENDER_STORAGE.bucket;
const readTimeoutMilliseconds = 15 * 60 * 1000;
const signedUrlLifetimeSeconds = 20 * 60;
const maximumVideoBytes = CONTROLLED_RENDER_STORAGE.maximumVideoBytes;
const assetIdSchema = z.string().uuid();
type RecoveryInput = Parameters<CompositionRenderAuthorityService["recover"]>[0];

/** Host-only finalization of an already uploaded object. Upload and renderer execution remain separate. */
export class CompositionControlledRenderFinalizationService {
  private readonly authority: CompositionRenderAuthorityService;

  constructor(private readonly supabase: SupabaseClient<any, any, any>, private readonly supabaseUrl: string,
    private readonly fetchImpl: typeof fetch = fetch, clock: () => number = Date.now,private readonly workerLeaseToken?:string) {
    this.authority = new CompositionRenderAuthorityService(supabase, clock,workerLeaseToken);
  }

  async finalize(input: RecoveryInput & {signal?: AbortSignal}) {
    input.signal?.throwIfAborted();
    const verified = await this.authority.recover(input);
    const {binding, receiptSha256} = verified.provenance;
    const objectPath = controlledRenderObjectPath(binding);
    // Path and expected bytes are derived from freshly verified authority, never caller-selected metadata.
    await this.verifyStoredOutput(objectPath, binding.videoSha256, binding.sizeBytes, input.signal);
    const refreshed = await this.authority.recover(input);
    if (refreshed.provenance.receiptSha256 !== receiptSha256)
      throw new Error("CONTROLLED_RENDER_AUTHORITY_CHANGED");
    input.signal?.throwIfAborted();
    const publicUrl = new URL(`/storage/v1/object/public/${bucket}/${objectPath}`, this.supabaseUrl).href;
    const completed = await this.supabase.rpc("finalize_controlled_composition_render", {
      ...controlledWorkerLeaseArguments(this.workerLeaseToken),
      p_organization_id: binding.organizationId, p_request_id: binding.requestId,
      p_execution_id: binding.executionId, p_revision_id: binding.revisionId,
      p_production_job_id: binding.productionJobId, p_receipt_sha256: receiptSha256,
      p_video_sha256: binding.videoSha256, p_size_bytes: binding.sizeBytes,
      p_public_url: publicUrl,
    });
    const asset = assetIdSchema.safeParse(completed.data);
    if (completed.error || !asset.success) throw new Error("CONTROLLED_RENDER_FINALIZATION_REJECTED");
    return {assetId: asset.data, storageBucket: bucket, objectPath, checksum: binding.videoSha256,
      provenance: refreshed.provenance, conformanceApproved: false as const};
  }

  private async verifyStoredOutput(objectPath: string, expectedHash: string, expectedSize: number, signal?: AbortSignal) {
    const signed = await this.supabase.storage.from(bucket).createSignedUrl(objectPath, signedUrlLifetimeSeconds)
      .catch(() => {throw new Error("CONTROLLED_RENDER_STORAGE_UNAVAILABLE");});
    if (signed.error || !signed.data?.signedUrl) throw new Error("CONTROLLED_RENDER_STORAGE_UNAVAILABLE");
    const url = this.trustedSignedUrl(signed.data.signedUrl, objectPath);
    const timeout = AbortSignal.timeout(readTimeoutMilliseconds);
    const readSignal = signal ? AbortSignal.any([signal, timeout]) : timeout;
    readSignal.throwIfAborted();
    try {
      const response = await this.fetchImpl(url, {signal: readSignal, redirect: "error", cache: "no-store"});
      const length = response.headers.get("content-length"), type = response.headers.get("content-type")?.split(";")[0].trim();
      if (response.status !== 200 || !response.body || response.headers.has("content-range")
        || (length !== null && length !== String(expectedSize))
        || (type !== undefined && type !== "video/mp4" && type !== "application/octet-stream")) {
        await response.body?.cancel();
        throw new Error("CONTROLLED_RENDER_STORAGE_RESPONSE_INVALID");
      }
      const reader = response.body.getReader(), digest = createHash("sha256");
      let size = 0;
      const cancelRead = () => {void reader.cancel().catch(() => undefined);};
      readSignal.addEventListener("abort", cancelRead, {once: true});
      try {
        while (true) {
          readSignal.throwIfAborted();
          const chunk = await reader.read();
          readSignal.throwIfAborted();
          if (chunk.done) break;
          size += chunk.value.byteLength;
          if (size > expectedSize || size > maximumVideoBytes)
            throw new Error("CONTROLLED_RENDER_STORAGE_BYTES_MISMATCH");
          digest.update(chunk.value);
        }
        if (size !== expectedSize || digest.digest("hex") !== expectedHash)
          throw new Error("CONTROLLED_RENDER_STORAGE_BYTES_MISMATCH");
      } finally {
        readSignal.removeEventListener("abort", cancelRead);
        await reader.cancel().catch(() => undefined);
        reader.releaseLock();
      }
    } catch (error) {
      if (error instanceof Error && /^CONTROLLED_RENDER_[A-Z_]+$/.test(error.message)) throw error;
      // Fetch failures can include signed credentials or provider internals.
      throw new Error("CONTROLLED_RENDER_STORAGE_READ_FAILED");
    }
  }

  private trustedSignedUrl(raw: string, objectPath: string) {
    try {
      const project = new URL(this.supabaseUrl), signed = new URL(raw);
      const expectedPath = `/storage/v1/object/sign/${bucket}/${objectPath}`;
      if (project.protocol !== "https:" || signed.origin !== project.origin || signed.username || signed.password
        || signed.pathname !== expectedPath || !signed.searchParams.get("token") || signed.hash)
        throw new Error();
      return signed.href;
    } catch {throw new Error("CONTROLLED_RENDER_STORAGE_URL_INVALID");}
  }
}

import type {SupabaseClient} from "@supabase/supabase-js";
import {CONTROLLED_RENDER_WORKER_POLICY,controlledRenderQueueClaimSchema,controlledRenderWorkerIdSchema,
  type ControlledRenderQueueClaim,type classifyControlledRenderWorkerFailure} from "./composition-controlled-render-worker-contract";

/** Service-role host adapter only. No HTTP route or background worker is activated. */
export class CompositionControlledRenderQueueService {
  constructor(private readonly supabase:SupabaseClient<any,any,any>) {}

  async claim(workerId:string,signal?:AbortSignal) {
    const worker = controlledRenderWorkerIdSchema.safeParse(workerId);
    if (!worker.success) throw new Error("CONTROLLED_RENDER_WORKER_ID_INVALID");
    const result = await this.rpc("claim_controlled_render_worker_job",{p_worker_id:worker.data},signal);
    const parsed = controlledRenderQueueClaimSchema.nullable().safeParse(result.data);
    if (result.error || !parsed.success) throw new Error("CONTROLLED_RENDER_WORKER_CLAIM_FAILED");
    if (parsed.data && parsed.data.workerId !== worker.data) throw new Error("CONTROLLED_RENDER_WORKER_CLAIM_INVALID");
    return parsed.data;
  }

  async renew(claim:ControlledRenderQueueClaim,signal?:AbortSignal) {
    const result = await this.rpc("renew_controlled_render_worker_job",this.scope(claim),signal);
    return !result.error && result.data === true;
  }

  async finish(claim:ControlledRenderQueueClaim,assetId:string|null,
    failure:ReturnType<typeof classifyControlledRenderWorkerFailure>|null,signal?:AbortSignal) {
    const result = await this.rpc("finish_controlled_render_worker_job",{...this.scope(claim),p_asset_id:assetId,
      p_error_code:failure?.code ?? null,p_retryable:failure?.retryable ?? false,
      p_recovery_required:failure?.recoveryRequired ?? false},signal);
    if (result.error || typeof result.data !== "boolean") throw new Error("CONTROLLED_RENDER_WORKER_FINISH_UNCONFIRMED");
    return result.data;
  }

  private scope(claim:ControlledRenderQueueClaim) {
    return {p_organization_id:claim.organizationId,p_request_id:claim.requestId,
      p_worker_id:claim.workerId,p_worker_lease_token:claim.leaseToken};
  }

  private async rpc(name:string,args:Record<string,unknown>,signal?:AbortSignal) {
    const timeout = AbortSignal.timeout(CONTROLLED_RENDER_WORKER_POLICY.rpcTimeoutMilliseconds);
    const bounded = signal ? AbortSignal.any([signal,timeout]) : timeout;
    bounded.throwIfAborted();
    try {return await this.supabase.rpc(name,args).abortSignal(bounded);}
    catch {throw new Error("CONTROLLED_RENDER_WORKER_RPC_UNAVAILABLE");}
  }
}

import {open} from "node:fs/promises";
import type {SupabaseClient} from "@supabase/supabase-js";
import {z} from "zod";
import {CompositionRenderAuthorityService} from "./composition-render-authority.service";
import {CompositionControlledRenderFinalizationService} from "./composition-controlled-render-finalization.service";
import {CONTROLLED_RENDER_STORAGE as policy, controlledRenderObjectPath, controlledRenderTusUrl} from "./composition-controlled-render-storage-policy";
import {pinConformanceFile, assertConformanceFileUnchanged} from "./composition-conformance-file-integrity";
import {controlledWorkerLeaseArguments} from "./composition-controlled-render-worker-contract";

type RecoveryInput = Parameters<CompositionRenderAuthorityService["recover"]>[0];
const sessionSchema = z.object({uploadUrl: z.string().nullable(), objectExists: z.boolean()}).strict();

/** Host-only: upload tokens remain in memory; durable ledger stores only the validated TUS URL. */
export class CompositionControlledRenderUploadService {
  private readonly authority: CompositionRenderAuthorityService;
  private readonly finalizer: CompositionControlledRenderFinalizationService;
  constructor(private readonly supabase: SupabaseClient<any, any, any>, private readonly projectUrl: string,
    private readonly fetchImpl: typeof fetch = fetch, clock: () => number = Date.now,private readonly workerLeaseToken?:string) {
    this.authority = new CompositionRenderAuthorityService(supabase, clock,workerLeaseToken);
    this.finalizer = new CompositionControlledRenderFinalizationService(supabase, projectUrl, fetchImpl, clock,workerLeaseToken);
  }

  async uploadAndFinalize(input: RecoveryInput & {signal?: AbortSignal}) {
    input.signal?.throwIfAborted();
    const recovered = await this.authority.recover(input), {binding, receiptSha256} = recovered.provenance;
    const objectPath = controlledRenderObjectPath(binding);
    const scope = {...controlledWorkerLeaseArguments(this.workerLeaseToken),p_organization_id: binding.organizationId, p_request_id: binding.requestId,
      p_execution_id: binding.executionId, p_receipt_sha256: receiptSha256};
    const saved = await this.supabase.rpc("read_controlled_render_upload", scope);
    const parsed = sessionSchema.safeParse(saved.data);
    if (saved.error || !parsed.success) throw new Error("CONTROLLED_RENDER_UPLOAD_SESSION_UNAVAILABLE");
    if (parsed.data.objectExists) return this.finalizer.finalize(input);
    const signed = await this.supabase.storage.from(policy.bucket).createSignedUploadUrl(objectPath, {upsert: false})
      .catch(() => {throw new Error("CONTROLLED_RENDER_UPLOAD_TOKEN_UNAVAILABLE");});
    if (signed.error || !signed.data?.token || signed.data.path !== objectPath)
      throw new Error("CONTROLLED_RENDER_UPLOAD_TOKEN_UNAVAILABLE");
    const endpoint = controlledRenderTusUrl("/storage/v1/upload/resumable", this.projectUrl, false);
    const headers = {"Tus-Resumable": "1.0.0", "x-signature": signed.data.token};
    let uploadUrl = parsed.data.uploadUrl === null ? null : controlledRenderTusUrl(parsed.data.uploadUrl, this.projectUrl, true);
    const request = async (url: string, init: RequestInit) => {
      input.signal?.throwIfAborted();
      const signal = input.signal ? AbortSignal.any([input.signal, AbortSignal.timeout(policy.requestTimeoutMilliseconds)])
        : AbortSignal.timeout(policy.requestTimeoutMilliseconds);
      try {return await this.fetchImpl(url, {...init, headers: {...headers, ...init.headers}, signal, redirect: "error"});}
      catch {throw new Error("CONTROLLED_RENDER_UPLOAD_TRANSPORT_FAILED");}
    };
    const checkpoint = async (previousUrl: string | null, nextUrl: string) => {
      input.signal?.throwIfAborted();
      const result = await this.supabase.rpc("save_controlled_render_upload", {...scope,
        p_expected_upload_url: previousUrl, p_upload_url: nextUrl});
      if (result.error || result.data !== true) throw new Error("CONTROLLED_RENDER_UPLOAD_CHECKPOINT_REJECTED");
    };
    let offset = 0;
    if (uploadUrl !== null) {
      const response = await request(uploadUrl, {method: "HEAD"});
      await response.body?.cancel();
      if (![404, 410].includes(response.status)) {
        if (response.status !== 200 && response.status !== 204) throw new Error("CONTROLLED_RENDER_UPLOAD_HEAD_FAILED");
        offset = this.readOffset(response, binding.sizeBytes);
        if (response.headers.get("upload-length") !== String(binding.sizeBytes))
          throw new Error("CONTROLLED_RENDER_UPLOAD_LENGTH_MISMATCH");
      } else {
        // Expired session may be recreated, but an existing completed object is never overwritten.
        offset = -1;
      }
    }
    if (uploadUrl === null || offset === -1) {
      const metadata = Object.entries({bucketName: policy.bucket, objectName: objectPath, contentType: "video/mp4", cacheControl: "3600"})
        .map(([name, value]) => `${name} ${Buffer.from(value).toString("base64")}`).join(",");
      const response = await request(endpoint, {method: "POST", headers: {"Upload-Length": String(binding.sizeBytes), "Upload-Metadata": metadata}});
      await response.body?.cancel();
      if (response.status !== 201 || !response.headers.get("location")) throw new Error("CONTROLLED_RENDER_UPLOAD_CREATE_FAILED");
      const nextUrl = controlledRenderTusUrl(new URL(response.headers.get("location")!, endpoint).href, this.projectUrl, true);
      await checkpoint(uploadUrl, nextUrl);
      uploadUrl = nextUrl; offset = 0;
    }
    const pin = await pinConformanceFile(input.videoPath, policy.maximumVideoBytes);
    if (pin.sha256 !== binding.videoSha256 || pin.sizeBytes !== binding.sizeBytes)
      throw new Error("CONTROLLED_RENDER_UPLOAD_SOURCE_CHANGED");
    const file = await open(input.videoPath, "r");
    try {
      const stat = await file.stat();
      if (!stat.isFile() || stat.dev !== pin.device || stat.ino !== pin.inode || stat.size !== pin.sizeBytes
        || stat.mtimeMs !== pin.modifiedAt || stat.ctimeMs !== pin.changedAt)
        throw new Error("CONTROLLED_RENDER_UPLOAD_SOURCE_CHANGED");
      while (offset < binding.sizeBytes) {
        // Refresh admission/revocation/cancellation through the scoped checkpoint before each transfer.
        await checkpoint(uploadUrl, uploadUrl);
        const bytes = Buffer.alloc(Math.min(policy.chunkBytes, binding.sizeBytes - offset));
        let filled = 0;
        while (filled < bytes.length) {
          const read = await file.read(bytes, filled, bytes.length - filled, offset + filled);
          if (!read.bytesRead) throw new Error("CONTROLLED_RENDER_UPLOAD_SOURCE_CHANGED");
          filled += read.bytesRead;
        }
        const response = await request(uploadUrl, {method: "PATCH", headers: {
          "Content-Type": "application/offset+octet-stream", "Upload-Offset": String(offset)}, body: bytes});
        await response.body?.cancel();
        if (response.status !== 204 || this.readOffset(response, binding.sizeBytes) !== offset + bytes.length)
          throw new Error("CONTROLLED_RENDER_UPLOAD_OFFSET_MISMATCH");
        offset += bytes.length;
      }
    } finally {await file.close();}
    await assertConformanceFileUnchanged(input.videoPath, pin, policy.maximumVideoBytes);
    return this.finalizer.finalize(input);
  }

  private readOffset(response: Response, size: number) {
    const raw = response.headers.get("upload-offset");
    if (!raw || !/^(0|[1-9][0-9]*)$/.test(raw) || !Number.isSafeInteger(Number(raw)) || Number(raw) > size)
      throw new Error("CONTROLLED_RENDER_UPLOAD_OFFSET_MISMATCH");
    return Number(raw);
  }
}

import type {KeyObject} from "node:crypto";
import type {SupabaseClient} from "@supabase/supabase-js";
import {CompositionRenderCheckpointStore} from "./composition-render-checkpoint-store";
import {CompositionRenderSupervisorService} from "./composition-render-supervisor.service";
import {createMaterializedControlledRenderer} from "./composition-materialized-supervisor-renderer";
import {controlledRenderQueueClaimSchema,type ControlledRenderQueueClaim} from "./composition-controlled-render-worker-contract";
import {createControlledHtmlEditingAuthorityReader} from "./composition-controlled-html-authority.service";
import {createOwnedControlledExecutor, type ControlledOwnedExecutorConfiguration} from "./composition-controlled-owned-executor";
import {CompositionConformanceRenderReservationService} from "./composition-conformance-render-reservation.service";

type RendererConfiguration = Parameters<typeof createMaterializedControlledRenderer>[0];

/** Explicit operator composition. Requires a real executor; never substitutes the synthetic prototype. */
export function createControlledRenderWorkerHost(input:{supabase:SupabaseClient<any,any,any>;supabaseUrl:string;
  checkpoints:CompositionRenderCheckpointStore;
  resolveSigningKey:(issuer:Pick<ControlledRenderQueueClaim,"organizationId"|"supervisorId"|"keyId">) => KeyObject|Promise<KeyObject>;
  renderStorage:Pick<RendererConfiguration["storage"],"outputParentDirectory"|"animationRuntimeSha256">;
  dependencyInventory:NonNullable<RendererConfiguration["dependencyInventory"]>;
  ownedExecutor:ControlledOwnedExecutorConfiguration;fetchImpl?:typeof fetch;clock?:() => number;
  deferConformanceReservation?: boolean}) {
  if (input.deferConformanceReservation !== undefined && typeof input.deferConformanceReservation !== "boolean")
    throw new Error("CONTROLLED_RENDER_RESERVATION_CONFIGURATION_INVALID");
  const reservations = input.deferConformanceReservation === true
    ? new CompositionConformanceRenderReservationService(input.supabase) : undefined;
  let execute:ReturnType<typeof createOwnedControlledExecutor> | undefined;
  return async (raw:ControlledRenderQueueClaim) => {
    const claim = controlledRenderQueueClaimSchema.parse(raw);
    if (!input.dependencyInventory) throw new Error("CONTROLLED_RENDER_DEPENDENCY_INVENTORY_REQUIRED");
    if (!input.ownedExecutor) throw new Error("CONTROLLED_RENDER_EXECUTOR_OWNERSHIP_REQUIRED");
    if (!input.ownedExecutor.fence) throw new Error("CONTROLLED_RENDER_EXECUTION_FENCE_REQUIRED");
    execute ??= createOwnedControlledExecutor(input.ownedExecutor);
    if (execute.isQuarantined()) throw new Error("CONTROLLED_RENDER_EXECUTOR_TERMINATION_UNCONFIRMED");
    const privateKey = await input.resolveSigningKey({organizationId:claim.organizationId,supervisorId:claim.supervisorId,keyId:claim.keyId});
    const renderer = createMaterializedControlledRenderer({storage:{...input.renderStorage,supabase:input.supabase,
      supabaseUrl:input.supabaseUrl,fetchImpl:input.fetchImpl,
      readHtmlEditingAuthority:createControlledHtmlEditingAuthorityReader({supabase:input.supabase,claim})},
      dependencyInventory:input.dependencyInventory,execute});
    return {checkpoints:input.checkpoints,supervisor:new CompositionRenderSupervisorService(input.supabase,input.supabaseUrl,
      privateKey,renderer,input.fetchImpl,input.clock,claim.leaseToken,
      reservations ? (checkpoint, signal) => reservations.defer(checkpoint, signal) : undefined)};
  };
}

