const familyKey = (family: string) => family.trim().replace(/^(["'])(.*)\1$/, "$2").normalize("NFC").toLowerCase();
const loadedFaceSchema = z.object({fontFamily: z.string().min(1).max(LIMITS.nameCharacters),
  platformFontFamily: z.string().min(1).max(LIMITS.nameCharacters), src: z.string().min(1).max(LIMITS.sourceCharacters)});

/** Event must identify one exact frozen file, not a family-name-only or local() fallback. */
export function resolveConformanceFontEvent(input: unknown, fonts: ConformanceFontManifest, origin: string) {
  const face = loadedFaceSchema.parse(input);
  const cssUrl = /^url\(["']?([^"'()]+)["']?\)(?:\s+format\(["'][a-z0-9]+["']\))?$/.exec(face.src);
  const source = cssUrl?.[1] ?? face.src;
  const url = new URL(source, `${origin}/conformance-preview.html`);
  if (url.origin !== origin || url.username || url.password || url.search || url.hash) throw new Error("CONFORMANCE_FONT_EVENT_SOURCE_INVALID");
  const font = fonts.find((candidate) => familyKey(candidate.family) === familyKey(face.fontFamily)
    && url.pathname === `/${conformanceFontPath(candidate)}`);
  if (!font) throw new Error("CONFORMANCE_FONT_EVENT_BINDING_MISMATCH");
  return {family: familyKey(font.family), platformFamily: face.platformFontFamily,
    contentIdentity: `${font.checksumSha256}:${font.mimeType}:${font.fileSizeBytes}`};
}

/** Start before navigation/load so successful FontFace events cannot be missed. */
export async function startConformancePlatformFontCapture(client: CompositionQaCdpClient, fonts: ConformanceFontManifest,
  document: CompositionEditorDocument, origin: string) {
  if (!fonts.length) return {bindings: [] as Array<{elementId: string; fontAssetId: string}>, verify: async (_checkpoint: TextParityEvidence["checkpoints"][number]) => [], assertValid() {}, close() {}};
  if (!client.onEvent) throw new Error("CONFORMANCE_FONT_EVENTS_UNAVAILABLE");
  const bindings = new Map<string, ReturnType<typeof resolveConformanceFontEvent>>();
  const platformIdentities = new Map<string, string>();
  let failed = false, events = 0;
  const unsubscribe = client.onEvent("CSS.fontsUpdated", (event) => {
    if (++events > LIMITS.events) {failed = true; return;}
    if (event.font === undefined) return;
    try {
      const binding = resolveConformanceFontEvent(event.font, fonts, origin);
      const existing = bindings.get(binding.family);
      const platformIdentity = platformIdentities.get(binding.platformFamily);
      if ((existing && (existing.platformFamily !== binding.platformFamily || existing.contentIdentity !== binding.contentIdentity))
        || (platformIdentity && platformIdentity !== binding.contentIdentity)) throw new Error("CONFORMANCE_FONT_PLATFORM_AMBIGUOUS");
      bindings.set(binding.family, binding); platformIdentities.set(binding.platformFamily, binding.contentIdentity);
    } catch {failed = true;}
  });
  try {await client.send("DOM.enable"); await client.send("CSS.enable");}
  catch (error) {unsubscribe(); throw error;}
  const owners = new Map<string, {family: string; fontAssetId: string}>();
  for (const clip of document.clips) {
    if (clip.source.type === "NATIVE_TEXT" && clip.source.style.fontAssetId) owners.set(`${clip.id}-motion`,
      {family: familyKey(clip.source.style.fontFamily), fontAssetId: clip.source.style.fontAssetId});
    if (clip.source.type === "NATIVE_CAPTIONS" && clip.source.style.fontAssetId) for (const cue of clip.source.cues) {
      owners.set(captionCueElementId(clip.id, cue.id), {family: familyKey(clip.source.style.fontFamily), fontAssetId: clip.source.style.fontAssetId});
    }
  }
  // Events can invalidate the witness after its last glyph query, including during final I/O.
  const assertValid = () => {if (failed) throw new Error("CONFORMANCE_FONT_EVENT_INVALID");};
  return {bindings: [...owners].map(([elementId, owner]) => ({elementId, fontAssetId: owner.fontAssetId})), assertValid,
    close: unsubscribe, async verify(checkpoint: TextParityEvidence["checkpoints"][number]) {
    assertValid();
    const expected = checkpoint.expectedTexts.filter((text) => owners.has(text.elementId));
    if (!expected.length) return [];
    await client.send("DOM.getDocument", {depth: 0});
    const witness: Array<{elementId: string; fontAssetId: string; platformFamily: string; fonts: z.infer<typeof platformFontUsageSchema>}> = [];
    for (const text of expected) {
      const owner = owners.get(text.elementId)!;
      const binding = bindings.get(owner.family);
      if (!binding) throw new Error("CONFORMANCE_FONT_LOADED_EVENT_MISSING");
      const reference = await client.send("Runtime.evaluate", {expression: `document.getElementById(${JSON.stringify(text.elementId)})`, returnByValue: false});
      const objectId = (reference.result as {objectId?: string} | undefined)?.objectId;
      if (reference.exceptionDetails || !objectId) throw new Error("CONFORMANCE_FONT_ELEMENT_MISSING");
      try {
        const node = await client.send("DOM.requestNode", {objectId});
        if (!Number.isSafeInteger(node.nodeId) || Number(node.nodeId) <= 0) throw new Error("CONFORMANCE_FONT_NODE_INVALID");
        const response = await client.send("CSS.getPlatformFontsForNode", {nodeId: node.nodeId});
        const used = platformFontUsageSchema.parse(response.fonts).filter((font) => font.glyphCount > 0);
        if (used.some((font) => !font.isCustomFont || font.familyName !== binding.platformFamily)) throw new Error("CONFORMANCE_FONT_GLYPH_FALLBACK");
        const verifiedRegion = checkpoint.regions.find((region) => region.elementId === text.elementId);
        const provenAbsence = verifiedRegion && (text.visibility === "HIDDEN"
          || (text.presentation?.paintPose?.support.empty && text.presentation.paintPose.filter === "blur(0px)"));
        if (!used.length && !provenAbsence) throw new Error("CONFORMANCE_FONT_GLYPH_USAGE_MISSING");
        witness.push({elementId: text.elementId, fontAssetId: owner.fontAssetId, platformFamily: binding.platformFamily,
          fonts: used.sort((left, right) => left.postScriptName.localeCompare(right.postScriptName))});
      } finally {await client.send("Runtime.releaseObject", {objectId});}
    }
    assertValid();
    return witness;
  }};
}

import {createHash, createPublicKey} from "node:crypto";
import type {SupabaseClient} from "@supabase/supabase-js";
import {z} from "zod";
import {compositionConformanceContractSchema} from "../composition-preview-render-conformance";
import {renderSupervisorReceiptSchema, RENDER_SUPERVISOR_RECEIPT_LIMITS} from "../composition-render-supervisor-receipt";
import {pinConformanceFile, assertConformanceFileUnchanged} from "./composition-conformance-file-integrity";
import {buildSupervisedComparisonArtifacts, buildSupervisedEventComparisonArtifacts} from "./composition-supervised-comparison-artifacts";
import {buildControlledSupervisorBinding, type ControlledSupervisorArtifacts} from "./composition-render-supervisor-binding";
import {controlledWorkerLeaseArguments} from "./composition-controlled-render-worker-contract";

const uuid = z.string().uuid().transform(value => value.toLowerCase());
const hash = z.string().regex(/^[a-f0-9]{64}$/);
const identifier = z.string().min(1).max(80).regex(/^[a-zA-Z0-9_-]+$/);
const timestamp = z.number().int().nonnegative().max(Number.MAX_SAFE_INTEGER);
const digest = (value: unknown) => createHash("sha256").update(JSON.stringify(value), "utf8").digest("hex");
const maximumVideoBytes = 2 * 1024 ** 3;
const maximumContractBytes = 1024 ** 2;

export const renderAuthorityContextSchema = z.object({
  organizationId: uuid, requestId: uuid, revisionId: uuid, productionJobId: uuid,
  executionId: uuid, attempt: z.number().int().min(1).max(5), leaseToken: uuid, challengeSha256: hash,
  documentHash: hash, projectHash: hash, contractSha256: hash,
  artifactKind: z.enum(["SINGLE_CONTRACT", "EVENT_BATCH_SET"]), supervisorId: identifier, keyId: identifier,
  issuedAtMilliseconds: timestamp, expiresAtMilliseconds: timestamp,
  contract: compositionConformanceContractSchema,
  key: z.object({publicKeySpkiBase64: z.string().min(1).max(1024).regex(/^[A-Za-z0-9+/]+={0,2}$/),
    notBeforeMilliseconds: timestamp, notAfterMilliseconds: timestamp, revoked: z.boolean()}).strict(),
}).strict().superRefine((context, validation) => {
  const contract = context.contract;
  if (contract.schemaVersion !== 4 || !contract.renderExecution || contract.documentHash !== context.documentHash
    || digest(contract) !== context.contractSha256
    || (contract.checkpointBatch ? "EVENT_BATCH_SET" : "SINGLE_CONTRACT") !== context.artifactKind
    || context.expiresAtMilliseconds <= context.issuedAtMilliseconds
    || context.expiresAtMilliseconds - context.issuedAtMilliseconds > RENDER_SUPERVISOR_RECEIPT_LIMITS.maximumLifetimeMilliseconds)
    validation.addIssue({code: "custom", message: "RENDER_AUTHORITY_CONTEXT_INVALID"});
});

type SingleArtifacts = Extract<ControlledSupervisorArtifacts, {kind: "SINGLE_CONTRACT"}>;
type EventArtifacts = Extract<ControlledSupervisorArtifacts, {kind: "EVENT_BATCH_SET"}>;
type AuthorityContext = z.output<typeof renderAuthorityContextSchema>;
const recoveryScopeSchema = z.object({organizationId: uuid, requestId: uuid, executionId: uuid,
  revisionId: uuid, productionJobId: uuid}).strict();
const consumedExecutionSchema = z.object({state: z.literal("CONSUMED"), context: renderAuthorityContextSchema,
  receipt: renderSupervisorReceiptSchema, receiptSha256: hash, consumedAtMilliseconds: timestamp}).strict()
  .superRefine((record, validation) => {
    if (record.receiptSha256 !== digest(record.receipt)
      || record.consumedAtMilliseconds < record.context.issuedAtMilliseconds
      || record.consumedAtMilliseconds >= record.context.expiresAtMilliseconds)
      validation.addIssue({code: "custom", message: "RENDER_AUTHORITY_CONSUMED_RECORD_INVALID"});
  });
const scopeSchema = z.object({organizationId: uuid, requestId: uuid, executionId: uuid, leaseToken: uuid}).strict();
const issueSchema = z.object({organizationId: uuid, requestId: uuid, issuanceId: uuid,
  supervisorId: identifier, keyId: identifier, contract: compositionConformanceContractSchema}).strict();

/** Worker-only authority adapter. No HTTP entry point, defaults or credentials are enabled here. */
export class CompositionRenderAuthorityService {
  constructor(private readonly supabase: SupabaseClient<any, any, any>, private readonly clock: () => number = Date.now,
    private readonly workerLeaseToken?:string) {}

  async issue(input: z.input<typeof issueSchema>) {
    const parsed = issueSchema.safeParse(input);
    if (!parsed.success) throw new Error("RENDER_AUTHORITY_INPUT_INVALID");
    const params = parsed.data;
    if (params.contract.schemaVersion !== 4 || !params.contract.renderExecution
      || Buffer.byteLength(JSON.stringify(params.contract), "utf8") > maximumContractBytes)
      throw new Error("RENDER_AUTHORITY_INPUT_INVALID");
    const result = await this.supabase.rpc("issue_composition_render_execution", {
      ...controlledWorkerLeaseArguments(this.workerLeaseToken),
      p_organization_id: params.organizationId, p_request_id: params.requestId, p_issuance_id: params.issuanceId,
      p_supervisor_id: params.supervisorId, p_key_id: params.keyId, p_contract: params.contract,
      p_contract_sha256: digest(params.contract),
    });
    if (result.error) throw new Error("RENDER_AUTHORITY_ISSUE_FAILED");
    const context = this.parseContext(result.data);
    if (context.organizationId !== params.organizationId || context.requestId !== params.requestId
      || context.supervisorId !== params.supervisorId || context.keyId !== params.keyId
      || context.contractSha256 !== digest(params.contract)) throw new Error("RENDER_AUTHORITY_CONTEXT_MISMATCH");
    return context;
  }

  async admit(input: {scope: z.input<typeof scopeSchema>; supervisorReceipt: unknown;
    videoPath: string; artifacts: SingleArtifacts | EventArtifacts}) {
    const parsed = scopeSchema.safeParse(input.scope);
    if (!parsed.success) throw new Error("RENDER_AUTHORITY_INPUT_INVALID");
    const scope = parsed.data;
    const result = await this.supabase.rpc("read_composition_render_execution", {
      p_organization_id: scope.organizationId, p_request_id: scope.requestId,
      p_execution_id: scope.executionId, p_lease_token: scope.leaseToken,
    });
    if (result.error || !result.data) throw new Error("RENDER_AUTHORITY_CONTEXT_UNAVAILABLE");
    const context = this.parseContext(result.data);
    if (Object.entries(scope).some(([field, value]) => context[field as keyof typeof scope] !== value)
      || context.artifactKind !== input.artifacts.kind) throw new Error("RENDER_AUTHORITY_CONTEXT_MISMATCH");
    const {verified, output, receipt} = await this.verifyArtifacts(context, input.supervisorReceipt,
      input.artifacts, input.videoPath, this.clock());
    await assertConformanceFileUnchanged(input.videoPath, output, maximumVideoBytes);
    const committed = await this.supabase.rpc("consume_composition_render_execution", {
      ...controlledWorkerLeaseArguments(this.workerLeaseToken),
      p_organization_id: scope.organizationId, p_request_id: scope.requestId, p_execution_id: scope.executionId,
      p_lease_token: scope.leaseToken, p_receipt: receipt, p_receipt_sha256: verified.provenance.receiptSha256,
    });
    if (committed.error || committed.data !== true) throw new Error("RENDER_AUTHORITY_CONSUMPTION_REJECTED");
    await assertConformanceFileUnchanged(input.videoPath, output, maximumVideoBytes);
    return verified;
  }

  /** Read-only reconciliation of a committed receipt. Never renews a challenge or consumes a new output. */
  async recover(input: {scope: z.input<typeof recoveryScopeSchema>; videoPath: string; artifacts: SingleArtifacts | EventArtifacts}) {
    const parsed = recoveryScopeSchema.safeParse(input.scope);
    if (!parsed.success) throw new Error("RENDER_AUTHORITY_INPUT_INVALID");
    const scope = parsed.data;
    const readRecord = async () => {
      const result = await this.supabase.rpc("read_consumed_composition_render_execution", {
        p_organization_id: scope.organizationId, p_request_id: scope.requestId, p_execution_id: scope.executionId,
        p_revision_id: scope.revisionId, p_production_job_id: scope.productionJobId,
      });
      if (result.error || !result.data) throw new Error("RENDER_AUTHORITY_RECOVERY_UNAVAILABLE");
      const record = consumedExecutionSchema.safeParse(result.data);
      const now = this.clock();
      if (!record.success || !Number.isSafeInteger(now) || now < 0
        || record.data.consumedAtMilliseconds > now + RENDER_SUPERVISOR_RECEIPT_LIMITS.maximumClockSkewMilliseconds)
        throw new Error("RENDER_AUTHORITY_CONSUMED_RECORD_INVALID");
      if (Object.entries(scope).some(([field, value]) => record.data.context[field as keyof typeof scope] !== value)
        || record.data.context.artifactKind !== input.artifacts.kind) throw new Error("RENDER_AUTHORITY_CONTEXT_MISMATCH");
      return record.data;
    };
    const record = await readRecord();
    // Time comes from the committed authority ledger, never from a caller's receipt or clock override.
    // Current revocation remains enforced through the key returned by this fresh scoped RPC.
    const {verified, output} = await this.verifyArtifacts(record.context, record.receipt,
      input.artifacts, input.videoPath, record.consumedAtMilliseconds);
    if (verified.provenance.receiptSha256 !== record.receiptSha256)
      throw new Error("RENDER_AUTHORITY_CONSUMED_RECORD_INVALID");
    await assertConformanceFileUnchanged(input.videoPath, output, maximumVideoBytes);
    const refreshed = await readRecord();
    if (digest(refreshed) !== digest(record)) throw new Error("RENDER_AUTHORITY_RECOVERY_CHANGED");
    await assertConformanceFileUnchanged(input.videoPath, output, maximumVideoBytes);
    return {...verified, recovery: {policy: "CONSUMED_LEDGER_RECOVERY_NOT_NEW_ADMISSION_V1" as const,
      consumedAtMilliseconds: record.consumedAtMilliseconds, checkedAtMilliseconds: this.clock()}};
  }

  private async verifyArtifacts(context: AuthorityContext, receiptInput: unknown,
    artifactInput: SingleArtifacts | EventArtifacts, videoPath: string, verificationTime: number) {
    const receipt = renderSupervisorReceiptSchema.safeParse(receiptInput);
    if (!receipt.success || receipt.data.payload.supervisorId !== context.supervisorId
      || receipt.data.payload.keyId !== context.keyId) throw new Error("RENDER_AUTHORITY_ISSUER_MISMATCH");
    if (receipt.data.payload.issuedAtMilliseconds < context.issuedAtMilliseconds
      || receipt.data.payload.expiresAtMilliseconds > context.expiresAtMilliseconds)
      throw new Error("RENDER_AUTHORITY_RECEIPT_INTERVAL_INVALID");
    const output = await pinConformanceFile(videoPath, maximumVideoBytes);
    const expectedBinding = buildControlledSupervisorBinding(context, artifactInput, output);
    const publicKey = this.publicKey(context.key.publicKeySpkiBase64);
    const authorization = {supervisorReceipt: receipt.data, expectedBinding, nowMilliseconds: verificationTime,
      trustedKeys: [{supervisorId: context.supervisorId, keyId: context.keyId, publicKey,
        organizationIds: [context.organizationId], notBeforeMilliseconds: context.key.notBeforeMilliseconds,
        notAfterMilliseconds: context.key.notAfterMilliseconds, revoked: context.key.revoked}]};
    const verified = artifactInput.kind === "SINGLE_CONTRACT"
      ? buildSupervisedComparisonArtifacts({...artifactInput.input, ...authorization})
      : buildSupervisedEventComparisonArtifacts({...artifactInput.input, ...authorization});
    return {verified, output, receipt: receipt.data};
  }

  /** Invalidates admission authority only; OS/process cancellation belongs to the supervisor. */
  async cancel(input: z.input<typeof scopeSchema>) {
    const parsed = scopeSchema.safeParse(input);
    if (!parsed.success) throw new Error("RENDER_AUTHORITY_INPUT_INVALID");
    const scope = parsed.data;
    const result = await this.supabase.rpc("cancel_composition_render_execution", {
      ...controlledWorkerLeaseArguments(this.workerLeaseToken),
      p_organization_id: scope.organizationId, p_request_id: scope.requestId,
      p_execution_id: scope.executionId, p_lease_token: scope.leaseToken,
    });
    if (result.error || typeof result.data !== "boolean") throw new Error("RENDER_AUTHORITY_CANCEL_FAILED");
    return result.data;
  }

  private parseContext(input: unknown) {
    const parsed = renderAuthorityContextSchema.safeParse(input);
    const now = this.clock();
    if (!parsed.success || !Number.isSafeInteger(now) || now < 0 || now >= parsed.data.expiresAtMilliseconds
      || parsed.data.issuedAtMilliseconds > now + RENDER_SUPERVISOR_RECEIPT_LIMITS.maximumClockSkewMilliseconds)
      throw new Error("RENDER_AUTHORITY_CONTEXT_INVALID");
    return parsed.data;
  }

  private publicKey(encoded: string) {
    try {
      const bytes = Buffer.from(encoded, "base64");
      if (bytes.toString("base64") !== encoded) throw new Error();
      return createPublicKey({key: bytes, format: "der", type: "spki"});
    } catch {throw new Error("RENDER_AUTHORITY_TRUST_INVALID");}
  }
}

import {createHash,createPublicKey, type KeyObject} from "node:crypto";
import type {SupabaseClient} from "@supabase/supabase-js";
import {CompositionRenderAuthorityService} from "./composition-render-authority.service";
import {CompositionControlledRenderUploadService} from "./composition-controlled-render-upload.service";
import {buildControlledSupervisorBinding, type ControlledSupervisorArtifacts} from "./composition-render-supervisor-binding";
import {signRenderSupervisorReceipt} from "./composition-render-supervisor-signature";
import {pinConformanceFile, assertConformanceFileUnchanged} from "./composition-conformance-file-integrity";
import {CONTROLLED_RENDER_STORAGE} from "./composition-controlled-render-storage-policy";
import {RENDER_SUPERVISOR_RECEIPT_POLICY} from "../composition-render-supervisor-receipt";
import {createControlledRenderDeadline, CONTROLLED_RENDER_DEADLINE_POLICY} from "./composition-controlled-render-deadline";
import {CONTROLLED_RENDER_CHECKPOINT_POLICY,parseControlledRenderCheckpoint,type ControlledRenderCheckpoint,type RenderCheckpointScope} from "./composition-render-checkpoint";
import type {ControlledReferenceSelection} from "./composition-controlled-reference-selection";

type IssueInput = Parameters<CompositionRenderAuthorityService["issue"]>[0];
type Context = Awaited<ReturnType<CompositionRenderAuthorityService["issue"]>>;
export type ControlledSupervisorRenderer = (descriptor: {
  organizationId: string; revisionId: string;
  executionId: string; documentHash: string; projectHash: string; contract: Context["contract"];
}, signal?: AbortSignal) => Promise<{videoPath: string; artifacts: ControlledSupervisorArtifacts; referenceSelection?: ControlledReferenceSelection}>;

/** Host coordinator, not an isolated renderer. Caller must supply an operator-owned renderer adapter. */
export class CompositionRenderSupervisorService {
  private readonly authority: CompositionRenderAuthorityService;
  private readonly uploader: CompositionControlledRenderUploadService;
  constructor(supabase: SupabaseClient<any, any, any>, projectUrl: string, private readonly privateKey: KeyObject,
    private readonly render: ControlledSupervisorRenderer, fetchImpl: typeof fetch = fetch,
    private readonly clock: () => number = Date.now,workerLeaseToken?:string,
    private readonly deferConformanceReservation?: (checkpoint: ControlledRenderCheckpoint, signal?: AbortSignal) => Promise<unknown>) {
    this.authority = new CompositionRenderAuthorityService(supabase, clock,workerLeaseToken);
    this.uploader = new CompositionControlledRenderUploadService(supabase, projectUrl, fetchImpl, clock,workerLeaseToken);
  }

  async execute(input: IssueInput, signal?: AbortSignal,
    persistCheckpoint?: (checkpoint:ControlledRenderCheckpoint) => Promise<void>) {
    signal?.throwIfAborted();
    const context = await this.authority.issue(input);
    const admissionScope = {organizationId: context.organizationId, requestId: context.requestId,
      executionId: context.executionId, leaseToken: context.leaseToken};
    let admitted = false, admissionStarted = false;
    let budget: ReturnType<typeof createControlledRenderDeadline> | undefined;
    try {
      if (this.privateKey.type !== "private" || this.privateKey.asymmetricKeyType !== "ed25519"
        || createPublicKey(this.privateKey).export({format: "der", type: "spki"}).toString("base64") !== context.key.publicKeySpkiBase64)
        throw new Error("RENDER_SUPERVISOR_SIGNING_KEY_MISMATCH");
      signal?.throwIfAborted();
      const remaining = context.expiresAtMilliseconds - this.clock();
      if (remaining < CONTROLLED_RENDER_DEADLINE_POLICY.minimumMilliseconds)
        throw new Error("RENDER_SUPERVISOR_AUTHORITY_EXPIRED");
      budget = createControlledRenderDeadline(Math.min(remaining, CONTROLLED_RENDER_DEADLINE_POLICY.maximumMilliseconds), signal);
      // Explicit projection: no private key, trust keys, DB credential, lease or receipt is given to the renderer.
      const produced = await this.render(structuredClone({executionId: context.executionId, documentHash: context.documentHash,
        organizationId: context.organizationId, revisionId: context.revisionId,
        projectHash: context.projectHash, contract: context.contract}), budget.signal);
      // Await adapter ownership; a logical deadline is not proof that its OS processes have terminated.
      budget.remainingMilliseconds();
      signal?.throwIfAborted();
      if (produced.artifacts.kind !== context.artifactKind) throw new Error("RENDER_SUPERVISOR_ARTIFACT_KIND_MISMATCH");
      const output = await pinConformanceFile(produced.videoPath, CONTROLLED_RENDER_STORAGE.maximumVideoBytes);
      const binding = buildControlledSupervisorBinding(context, produced.artifacts, output);
      const issuedAtMilliseconds = this.clock();
      if (!Number.isSafeInteger(issuedAtMilliseconds) || issuedAtMilliseconds < context.issuedAtMilliseconds
        || issuedAtMilliseconds >= context.expiresAtMilliseconds) throw new Error("RENDER_SUPERVISOR_AUTHORITY_EXPIRED");
      const receipt = signRenderSupervisorReceipt({policy: RENDER_SUPERVISOR_RECEIPT_POLICY,
        scope: "SIGNED_ISSUER_AND_OUTPUT_BINDING_NOT_ISOLATION_OR_CONFORMANCE", supervisorId: context.supervisorId,
        keyId: context.keyId, issuedAtMilliseconds, expiresAtMilliseconds: context.expiresAtMilliseconds, binding}, this.privateKey);
      await assertConformanceFileUnchanged(produced.videoPath, output, CONTROLLED_RENDER_STORAGE.maximumVideoBytes);
      budget.remainingMilliseconds();
      const recovery = {scope: {organizationId: context.organizationId, requestId: context.requestId, executionId: context.executionId,
        revisionId: context.revisionId, productionJobId: context.productionJobId}, videoPath: produced.videoPath, artifacts: produced.artifacts};
      let checkpoint: ControlledRenderCheckpoint | undefined;
      if (this.deferConformanceReservation && (!persistCheckpoint || !produced.referenceSelection))
        throw new Error("RENDER_SUPERVISOR_CHECKPOINT_RESERVATION_REQUIRED");
      if (persistCheckpoint) {
        checkpoint = parseControlledRenderCheckpoint({version:CONTROLLED_RENDER_CHECKPOINT_POLICY.version,...recovery,leaseToken:context.leaseToken,
          supervisorReceipt:receipt,...(produced.referenceSelection ? {referenceSelection:produced.referenceSelection} : {})},recovery.scope);
        try {await persistCheckpoint(checkpoint);} catch {throw new Error("RENDER_SUPERVISOR_CHECKPOINT_WRITE_FAILED");}
        budget.remainingMilliseconds(); signal?.throwIfAborted();
        await assertConformanceFileUnchanged(produced.videoPath,output,CONTROLLED_RENDER_STORAGE.maximumVideoBytes);
      }
      admissionStarted = true;
      try {await this.authority.admit({scope: admissionScope, supervisorReceipt: receipt,
        videoPath: produced.videoPath, artifacts: produced.artifacts});}
      catch {
        // An ACK may be lost after consumption. Reconcile ledger; never blindly render or consume again.
        const recovered = await this.authority.recover(recovery);
        if (recovered.provenance.receiptSha256 !== createHash("sha256").update(JSON.stringify(receipt)).digest("hex"))
          throw new Error("RENDER_SUPERVISOR_CHECKPOINT_RECEIPT_MISMATCH");
      }
      admitted = true;
      budget.dispose();
      signal?.throwIfAborted();
      if (this.deferConformanceReservation) await this.publishDeferredReservation(checkpoint!, signal);
      return await this.uploader.uploadAndFinalize({...recovery, signal});
    } catch (error) {
      // Do not cancel an uncertain/consumed admission or erase the output needed to resume its upload.
      if (!admitted && !admissionStarted) {
        try {await this.authority.cancel(admissionScope);}
        catch {throw new Error("RENDER_SUPERVISOR_CANCELLATION_UNCONFIRMED");}
      }
      if (error instanceof Error && /^(RENDER_(SUPERVISOR|AUTHORITY)|CONTROLLED_RENDER|CONFORMANCE_FILE)_[A-Z_]+$/.test(error.message)) throw error;
      if (signal?.aborted) throw new Error("RENDER_SUPERVISOR_CANCELLED");
      throw new Error("RENDER_SUPERVISOR_EXECUTION_FAILED");
    } finally {budget?.dispose();}
  }

  /** Retry upload/finalization of a consumed output without issuing a new challenge or calling the renderer. */
  resume(input: Parameters<CompositionControlledRenderUploadService["uploadAndFinalize"]>[0]) {
    if (this.deferConformanceReservation) return Promise.reject(new Error("RENDER_SUPERVISOR_CHECKPOINT_RESERVATION_REQUIRED"));
    return this.uploader.uploadAndFinalize(input);
  }

  /** Replay the exact admission after a process restart; never issue a new challenge or invoke the renderer. */
  async resumeCheckpoint(raw:unknown,expectedScope:RenderCheckpointScope,signal?:AbortSignal) {
    signal?.throwIfAborted();
    const checkpoint = parseControlledRenderCheckpoint(raw,expectedScope);
    if (this.deferConformanceReservation && !checkpoint.referenceSelection)
      throw new Error("RENDER_SUPERVISOR_CHECKPOINT_RESERVATION_REQUIRED");
    const recovery = {scope:checkpoint.scope,videoPath:checkpoint.videoPath,artifacts:checkpoint.artifacts};
    let recovered: Awaited<ReturnType<CompositionRenderAuthorityService["recover"]>> | undefined;
    try {
      recovered = await this.authority.recover(recovery);
    } catch (error) {
      // Only absent/unavailable history permits checking the original live challenge.
      // A foreign, changed or revoked consumed record cannot become a fresh admission.
      if (!(error instanceof Error) || error.message !== "RENDER_AUTHORITY_RECOVERY_UNAVAILABLE") throw error;
      signal?.throwIfAborted();
      try {
        await this.authority.admit({scope:{organizationId:checkpoint.scope.organizationId,requestId:checkpoint.scope.requestId,
          executionId:checkpoint.scope.executionId,leaseToken:checkpoint.leaseToken},supervisorReceipt:checkpoint.supervisorReceipt,
          videoPath:checkpoint.videoPath,artifacts:checkpoint.artifacts});
      } catch {recovered = await this.authority.recover(recovery);}
    }
    if (recovered && recovered.provenance.receiptSha256 !== createHash("sha256").update(JSON.stringify(checkpoint.supervisorReceipt)).digest("hex"))
      throw new Error("RENDER_SUPERVISOR_CHECKPOINT_RECEIPT_MISMATCH");
    signal?.throwIfAborted();
    if (this.deferConformanceReservation) await this.publishDeferredReservation(checkpoint, signal);
    return this.uploader.uploadAndFinalize({...recovery,signal});
  }

  private async publishDeferredReservation(checkpoint: ControlledRenderCheckpoint, signal?: AbortSignal) {
    try {
      if (!checkpoint.referenceSelection) throw new Error();
      await this.deferConformanceReservation!(structuredClone(checkpoint), signal);
      signal?.throwIfAborted();
    } catch {throw new Error("RENDER_SUPERVISOR_CHECKPOINT_RESERVATION_UNCONFIRMED");}
  }
}

import {execFile} from "node:child_process";
import {promisify} from "node:util";
import {createHash} from "node:crypto";
import {performance} from "node:perf_hooks";
import {z} from "zod";
import {SDR_AUDIO_MUX_POLICY, SDR_SILENT_ASSEMBLY_POLICY, SDR_FRAME_CONVERSION_POLICY, sdrFrameCaptureProfileSchema} from "../composition-sdr-conversion-policy";
import {pinConformanceFile, assertConformanceFileUnchanged} from "./composition-conformance-file-integrity";
import {assertConformanceJobActive} from "./composition-conformance-job-lease";
import {createControlledProcessEnvironment} from "./composition-controlled-process-environment";
import {assertSdrCheckpointStreamProfile} from "./composition-sdr-checkpoint-decoder";
import {validateSdrEncodedOutput} from "./composition-sdr-output-profile";
import {hashSdrPacketTiming} from "./composition-sdr-packet-timing";

const MAXIMUM_PACKET_JSON_BYTES = 16 * 1024 * 1024;
const packetHash = z.string().regex(/^SHA256:[a-f0-9]{64}$/i).transform(value => value.toLowerCase());
const packetSchema = z.object({packets: z.array(z.object({data_hash: packetHash,
  size: z.string().max(10).regex(/^[1-9]\d*$/)}).passthrough()).min(1).max(36000),
  streams: z.array(z.object({codec_type: z.literal("video"), extradata_hash: packetHash}).passthrough()).length(1)}).passthrough();

/** Ordered packet payload + codec extradata identity. Not timing, decoding or origin proof. */
export function hashSdrVideoPackets(encoded: unknown, frameCount: number) {
  try {
    if (!Number.isSafeInteger(frameCount) || frameCount < 1 || frameCount > 36000
      || typeof encoded !== "string" || Buffer.byteLength(encoded) > MAXIMUM_PACKET_JSON_BYTES) throw new Error();
    const parsed = packetSchema.parse(JSON.parse(encoded));
    if (parsed.packets.length !== frameCount) throw new Error();
    const digest = createHash("sha256").update("courseforge-sdr-video-payloads-v1\n").update(parsed.streams[0]!.extradata_hash);
    for (const packet of parsed.packets) digest.update(JSON.stringify([packet.size, packet.data_hash]));
    return digest.digest("hex");
  } catch {throw new Error("SDR_MUX_VIDEO_PACKETS_INVALID");}
}

type ProbeExecutor = (binary: string, args: string[], options: {timeout: number; maxBuffer: number;
  windowsHide: boolean; signal?: AbortSignal; env: NodeJS.ProcessEnv}) => Promise<{stdout: string}>;
const executeFile = promisify(execFile);

type CopiedVideoInput = {silentVideoPath: string; silentVideoSha256: string;
  videoPath: string; videoSha256: string; ffprobePath: string; ffprobeSha256: string;
  profile: {width: number; height: number; fps: number; frameCount: number}; timeoutMilliseconds: number;
  signal?: AbortSignal};

/** Same packet/timing checks for both SDK assembly branches; audio obligations never inferred. */
async function verifyCopiedSdrVideo(input: CopiedVideoInput, execute: ProbeExecutor, hasAudio: boolean) {
  assertConformanceJobActive(input.signal);
  const profile = sdrFrameCaptureProfileSchema.parse({...input.profile, captureProfile: SDR_FRAME_CONVERSION_POLICY.captureProfile});
  if (!Number.isSafeInteger(input.timeoutMilliseconds) || input.timeoutMilliseconds < 1 || input.timeoutMilliseconds > 600000
    || [input.silentVideoSha256, input.videoSha256, input.ffprobeSha256].some(hash => !/^[a-f0-9]{64}$/.test(hash)))
    throw new Error("SDR_MUX_VERIFICATION_INPUT_INVALID");
  const started = performance.now();
  const remaining = () => {
    assertConformanceJobActive(input.signal);
    const duration = input.timeoutMilliseconds - (performance.now() - started);
    if (duration <= 0) throw new Error("SDR_MUX_VERIFICATION_TIMEOUT");
    return Math.max(1, Math.floor(duration));
  };
  const silent = await pinConformanceFile(input.silentVideoPath, 2 * 1024 ** 3, false, input.signal);
  const output = await pinConformanceFile(input.videoPath, 2 * 1024 ** 3, false, input.signal);
  const probe = await pinConformanceFile(input.ffprobePath, 1024 ** 3, false, input.signal);
  if (silent.sha256 !== input.silentVideoSha256 || output.sha256 !== input.videoSha256 || probe.sha256 !== input.ffprobeSha256)
    throw new Error("SDR_MUX_VERIFICATION_HASH_MISMATCH");
  const run = async (args: string[], maxBuffer: number) => {
    const result = await execute(input.ffprobePath, ["-v", "error", "-protocol_whitelist", "file,pipe", ...args],
      {timeout: remaining(), maxBuffer, windowsHide: true, signal: input.signal, env: createControlledProcessEnvironment()});
    remaining(); return result.stdout;
  };
  const metadata = await run(["-count_frames", "-show_entries",
    "stream=codec_type,codec_name,width,height,pix_fmt,avg_frame_rate,nb_read_frames,color_space,color_transfer,color_primaries,color_range,chroma_location,start_time,sample_rate,channels,duration:format=duration,size,format_name,start_time",
    "-of", "json", input.videoPath], 65536);
  let outputProfile: ReturnType<typeof validateSdrEncodedOutput>;
  try {
    if (Buffer.byteLength(metadata) > 65536) throw new Error();
    const parsed = JSON.parse(metadata) as {streams: Array<Record<string, unknown>>; format: unknown};
    assertSdrCheckpointStreamProfile(parsed, hasAudio ? SDR_AUDIO_MUX_POLICY : undefined,
      {durationSeconds: profile.frameCount / profile.fps, frameDurationSeconds: 1 / profile.fps});
    const videos = parsed.streams.filter(stream => stream.codec_type === "video").map(stream => {
      const {duration: _streamDuration, ...countedVideoFields} = stream; return countedVideoFields;
    });
    outputProfile = validateSdrEncodedOutput(JSON.stringify({streams: videos,
      format: parsed.format}), {...profile, sizeBytes: output.sizeBytes});
  } catch {throw new Error("SDR_MUX_OUTPUT_PROFILE_INVALID");}
  const hashes: string[] = [];
  const timingHashes: string[] = [];
  for (const path of [input.silentVideoPath, input.videoPath]) {
    const packets = await run(["-select_streams", "v:0", "-show_packets", "-show_streams", "-show_data_hash", "sha256",
      "-show_entries", "packet=size,data_hash,pts,dts,duration:stream=codec_type,extradata_hash,time_base", "-of", "json", path], MAXIMUM_PACKET_JSON_BYTES);
    hashes.push(hashSdrVideoPackets(packets, profile.frameCount));
    timingHashes.push(hashSdrPacketTiming(packets, profile));
  }
  if (hashes[0] !== hashes[1]) throw new Error("SDR_MUX_VIDEO_PAYLOAD_CHANGED");
  if (timingHashes[0] !== timingHashes[1]) throw new Error("SDR_MUX_VIDEO_TIMING_CHANGED");
  for (const [path, pin, maximum] of [[input.silentVideoPath, silent, 2 * 1024 ** 3],
    [input.videoPath, output, 2 * 1024 ** 3], [input.ffprobePath, probe, 1024 ** 3]] as const)
    await assertConformanceFileUnchanged(path, pin, maximum, false, input.signal);
  remaining();
  return {
    silentVideoSha256: silent.sha256, videoSha256: output.sha256, probeSha256: probe.sha256,
    videoPayloadSha256: hashes[0]!, videoTimingSha256: timingHashes[0]!, frameCount: profile.frameCount, outputProfile};
}

/** Verify SDK AAC mux before receipt, without repairs or relabeling. */
export async function verifySdrAudioMuxOutput(input: CopiedVideoInput, execute: ProbeExecutor = executeFile) {
  return {...await verifyCopiedSdrVideo(input, execute, true), policy: SDR_AUDIO_MUX_POLICY,
    scope: "LOCAL_PROBED_VIDEO_PAYLOADS_NOT_SYNC_OR_RENDER_ATTESTATION" as const};
}

/** A changed MP4 container is acceptable only with unchanged video payloads AND timing,
 * counted SDR profile, no audio/extra streams, and rechecked bytes on both sides. */
export async function verifySdrSilentAssemblyOutput(input: CopiedVideoInput, execute: ProbeExecutor = executeFile) {
  return {...await verifyCopiedSdrVideo(input, execute, false), policy: SDR_SILENT_ASSEMBLY_POLICY,
    scope: "LOCAL_PROBED_SILENT_VIDEO_COPY_NOT_RENDER_ATTESTATION" as const};
}

