} from "./render-batch.types";

type SupabaseAdmin = ReturnType<typeof getServiceRoleClient>;

function firstRelation<T>(value: T | T[] | null | undefined): T | undefined {
  if (!value) return undefined;
  return Array.isArray(value) ? value[0] : value;
}

function getComponentLabel(component: any) {
  const lesson = firstRelation(component.material_lessons);
  return lesson?.lesson_title || component.content?.title || "Video";
}

function getProgressPercent(progress: unknown) {
  if (!Array.isArray(progress) || progress.length === 0) return 0;
  const last = progress[progress.length - 1] as { percent?: unknown };
  const percent = Number(last.percent);
  return Number.isFinite(percent) ? Math.max(0, Math.min(100, Math.round(percent))) : 0;
}

function getLastLog(progress: unknown) {
  if (!Array.isArray(progress) || progress.length === 0) return undefined;
  const last = progress[progress.length - 1] as { message?: unknown };
  return typeof last.message === "string" ? last.message : undefined;
}

export function hasRenderableAssets(component: any) {
  const currentAssets = (component.assets || {}) as MaterialAssets;
  return getAssemblyAssetReadiness(currentAssets, 30).canRender;
}

export class RenderBatchService {
  constructor(
    private readonly supabase: SupabaseAdmin,
    private readonly controlPlane = new DesktopWorkerControlPlane(supabase),
  ) {}

  async createBatch(input: RenderBatchRequest, context: { userId: string; organizationIds: string[] }) {
    const request = renderBatchRequestSchema.parse(input);
    const { data: artifact, error: artifactError } = await this.supabase
      .from("artifacts")
      .select("id, organization_id")
      .eq("id", request.artifactId)
      .maybeSingle();

    if (artifactError || !artifact) throw new Error("ARTIFACT_NOT_FOUND");
    if (!context.organizationIds.includes(artifact.organization_id)) {
      throw new Error("FORBIDDEN_ARTIFACT_ORGANIZATION");
    }

    const componentIds = request.items.map((item) => item.componentId);
    const templateIds = Array.from(new Set([
      request.defaultTemplateId,
      ...request.items.map((item) => item.templateId).filter((value): value is string => Boolean(value)),
    ]));
    const preferredWorkerIds = Array.from(new Set(
      request.items
        .map((item) => item.preferredWorkerId)
        .filter((value): value is string => Boolean(value)),
    ));

    const [{ data: components }, { data: templates }, { data: workers }] = await Promise.all([
      this.supabase
        .from("material_components")
        .select(`
          id, assets, content, type, material_lesson_id,
          material_lessons (
            id, lesson_id, lesson_title, module_title, module_id,
            materials ( artifact_id )
          )
        `)
        .in("id", componentIds),
      this.supabase
        .from("remotion_templates")
        .select("id, organization_id")
        .in("id", templateIds),
      preferredWorkerIds.length > 0
        ? this.supabase
            .from("render_workers")
            .select("id, organization_id, status")
            .in("id", preferredWorkerIds)
        : Promise.resolve({ data: [] }),
    ]);

    const componentsById = new Map((components || []).map((component: any) => [component.id, component]));
    const templatesById = new Map((templates || []).map((template: any) => [template.id, template]));
    const workersById = new Map((workers || []).map((worker: any) => [worker.id, worker]));

    for (const item of request.items) {
      const component = componentsById.get(item.componentId);
      if (!component) throw new Error(`COMPONENT_NOT_FOUND: ${item.componentId}`);
      const lesson = firstRelation(component.material_lessons);
      const material = firstRelation(lesson?.materials);
      if (material?.artifact_id !== request.artifactId) {
        throw new Error(`COMPONENT_FORBIDDEN_FOR_BATCH: ${item.componentId}`);
      }
      if (!hasRenderableAssets(component)) {
        const readiness = getAssemblyAssetReadiness((component.assets || {}) as MaterialAssets, 30);
        const issue = readiness.blockingIssues[0];
        throw new Error(
          `${issue?.code || "COMPONENT_NOT_RENDERABLE"}: ${getComponentLabel(component)} - ${issue?.message || "assets incompletos"}`,
        );
      }

      const template = templatesById.get(item.templateId || request.defaultTemplateId);
      if (!template) throw new Error(`TEMPLATE_NOT_FOUND: ${item.templateId || request.defaultTemplateId}`);
      if (template.organization_id && !context.organizationIds.includes(template.organization_id)) {
        throw new Error(`FORBIDDEN_TEMPLATE_ORGANIZATION: ${template.id}`);
      }

      if (item.preferredWorkerId) {
        const worker = workersById.get(item.preferredWorkerId);
        if (!worker || worker.organization_id !== artifact.organization_id || worker.status === "REVOKED") {
          throw new Error(`WORKER_NOT_AVAILABLE_FOR_BATCH: ${item.preferredWorkerId}`);
        }
      }
    }

    const now = new Date().toISOString();
    const { data: batch, error: batchError } = await this.supabase
      .from("production_render_batches")
      .insert({
        organization_id: artifact.organization_id,
        artifact_id: request.artifactId,
        created_by: context.userId,
        status: "QUEUED",
        assignment_mode: request.assignmentMode,
        default_template_id: request.defaultTemplateId,
        total_items: request.items.length,
        metadata: {
          requestedItems: request.items.length,
          createdVia: "postproduction_assembly",
        },
      })
      .select("*")
      .single();

    if (batchError || !batch) throw new Error(`BATCH_CREATE_FAILED: ${batchError?.message || "Unknown error"}`);

    const itemRows: any[] = [];
    const startedJobs: RenderBatchItemStatusView[] = [];

    for (const item of request.items) {
      const component = componentsById.get(item.componentId);
      const templateId = item.templateId || request.defaultTemplateId;
      const preferredWorkerId = item.preferredWorkerId || null;
      const variables = {
        ...item.variables,
        renderBatchId: batch.id,
        componentTitle: getComponentLabel(component),
      };

      const jobResult = await this.controlPlane.createDesktopRenderJob({
        componentId: item.componentId,
        templateId,
        variables,
        userId: context.userId,
        organizationIds: context.organizationIds,
        renderBatchId: batch.id,
        preferredWorkerId,
        assignedStrategy: preferredWorkerId ? "MANUAL" : "AUTO",
      });

      itemRows.push({
        batch_id: batch.id,
        organization_id: artifact.organization_id,
        artifact_id: request.artifactId,
        material_component_id: item.componentId,
        template_id: templateId,
        preferred_worker_id: preferredWorkerId,
        production_job_id: jobResult.jobId,
        status: jobResult.status || "WAITING_PROVIDER",
        variables,
        updated_at: now,
      });

      startedJobs.push({
        componentId: item.componentId,
        jobId: jobResult.jobId,
        label: getComponentLabel(component),
        status: jobResult.status || "WAITING_PROVIDER",
        progress: 5,
        templateId,
        preferredWorkerId,
      });
    }

    const { error: itemsError } = await this.supabase
      .from("production_render_batch_items")
      .upsert(itemRows, { onConflict: "batch_id,material_component_id" });

    if (itemsError) throw new Error(`BATCH_ITEMS_CREATE_FAILED: ${itemsError.message}`);

    await this.supabase
      .from("production_render_batches")
      .update({ status: "RUNNING", updated_at: now })
      .eq("id", batch.id);

    return {
      batchId: batch.id as string,
      status: "RUNNING",
      items: startedJobs,
    };
  }

  async getBatchStatus(batchId: string, organizationIds: string[]): Promise<RenderBatchStatusView> {
    const { data: batch, error } = await this.supabase
      .from("production_render_batches")
      .select("*")
      .eq("id", batchId)
      .maybeSingle();

    if (error || !batch) throw new Error("BATCH_NOT_FOUND");
    if (!organizationIds.includes(batch.organization_id)) throw new Error("FORBIDDEN_BATCH_ORGANIZATION");

    const { data: rows } = await this.supabase
      .from("production_render_batch_items")
      .select(`
        id, material_component_id, template_id, preferred_worker_id, status, error_sanitized,
        production_jobs (
          id, status, progress, output_snapshot, provider_error, worker_id
        ),
        material_components (
          content,
          material_lessons ( lesson_title )
        )
      `)
      .eq("batch_id", batchId)
      .order("created_at", { ascending: true });

    const items = (rows || []).map((row: any): RenderBatchItemStatusView => {
      const job = firstRelation(row.production_jobs);
      const component = firstRelation(row.material_components);
      const lesson = firstRelation(component?.material_lessons);
      const providerError = job?.provider_error || {};

      return {
        componentId: row.material_component_id,
        jobId: job?.id || null,
        label: lesson?.lesson_title || component?.content?.title || "Video",
        status: job?.status || row.status,
        progress: getProgressPercent(job?.progress),
        finalVideoUrl: job?.output_snapshot?.final_video_url,
        error: row.error_sanitized || providerError.message,
        errorCode: providerError.code,
        lastLog: getLastLog(job?.progress),
        templateId: row.template_id,
        preferredWorkerId: row.preferred_worker_id,
        workerId: job?.worker_id || null,
      };
    });

    return {
      id: batch.id,
      status: batch.status,
      assignmentMode: batch.assignment_mode,
      totalItems: batch.total_items,
      completedItems: batch.completed_items,
      failedItems: batch.failed_items,
      items,
    };
  }
}

type CatalogRow = Record<string, unknown>;
interface QueryResult { data: CatalogRow | null; error: { message: string } | null; count?: number }

export function createImportCatalogFixture() {
  const tables = new Map<string, Map<string, CatalogRow>>();
  const files = new Map<string, Buffer>();
  const accesses: Array<{ table: string; filters: Record<string, unknown>; operation: string }> = [];
  const failure = { finalSave: false };
  class Query {
    private filters: Record<string, unknown> = {};
    private operation = "read";
    private row: CatalogRow = {};
    private count = false;
    constructor(private table: string) {}
    eq(key: string, value: unknown) { this.filters[key] = value; return this; }
    in(key: string, values: unknown[]) { this.filters[key] = values; return this; }
    select(_columns: string, options?: { count?: string }) { this.count = Boolean(options?.count); return this; }
    upsert(row: CatalogRow) { this.operation = "insert"; this.row = row; return this; }
    update(row: CatalogRow) { this.operation = "update"; this.row = row; return this; }
    private execute(): QueryResult {
      accesses.push({ table: this.table, filters: { ...this.filters }, operation: this.operation });
      if (!tables.has(this.table)) tables.set(this.table, new Map());
      const records = tables.get(this.table)!;
      const selected = [...records.values()].filter(row => Object.entries(this.filters).every(([key, value]) => Array.isArray(value) ? value.includes(row[key]) : row[key] === value));
      if (this.count) return { data: null, error: null, count: selected.length };
      if (this.operation === "insert") {
        const id = String(this.row.id);
        if (!records.has(id)) records.set(id, { ...this.row });
        return { data: records.get(id)!, error: null };
      }
      if (this.operation === "update") {
        if (failure.finalSave) { failure.finalSave = false; return { data: null, error: { message: "Fallo simulado al confirmar" } }; }
        for (const row of selected) Object.assign(row, this.row);
      }
      return { data: selected[0] || null, error: null };
    }
    async maybeSingle() { return this.execute(); }
    async single() { return this.execute(); }
    then(resolve: (value: QueryResult) => unknown) { return Promise.resolve(this.execute()).then(resolve); }
  }
  const admin = {
    from: (table: string) => new Query(table),
    storage: { from: (_bucket: string) => ({
      async upload(path: string, bytes: Buffer) {
        if (files.has(path)) return { error: { message: "El archivo ya existe" } };
        files.set(path, bytes); return { error: null };
      },
      async download(path: string) {
        const bytes = files.get(path);
        return { data: bytes ? { arrayBuffer: async () => Uint8Array.from(bytes).buffer } : null, error: bytes ? null : { message: "No encontrado" } };
      },
    }) },
  };
  return { admin, accesses, tables, files, failure };
}

"use server";

import { getAuthenticatedUser, getServiceRoleClient } from "@/lib/server/artifact-action-auth";
import { resolveActiveTenantContext } from "@/lib/server/tenant-context";
import { getAuthBridgeUser, getUserOrganizations } from "@/utils/auth/session";
import { createClient } from "@/utils/supabase/server";
import { importedDesignPreview } from "./import/imported-slide-design.service";
import { importedSlideDesignSchema } from "./import/imported-slide-design.contract";

export interface SlideTemplateLibraryItem {
  design_base_run_id?: string | null;
  imported?: boolean;
  preview_html?: string | null;
  preview_url?: string | null;
  id: string;
  conversation_id: string;
  organization_id: string;
  spec_id: string | null;
  title: string;
  description: string | null;
  package_id: string | null;
  status: "QUEUED" | "RUNNING" | "PACKAGED" | "VALIDATION_FAILED" | "SUBMITTED_FOR_REVIEW" | "FAILED";
  bundle_storage_path: string | null;
  output_hash: string | null;
  error_sanitized: string | null;
  created_at: string;
  finished_at: string | null;
  layouts: string[];
  example_slide_count: number;
  preview_design: { accent: string; accent2: string; background: string; muted: string; surface: string; text: string } | null;
  preview_slides: Array<{ body_items: string[]; chart_points: number[]; layout: string | null; order: number; subtitle: string | null; title: string; type: string }>;
  runtime_canvas: { width: number; height: number; aspectRatio: string } | null;
  validation_report: { isValid?: boolean; errors?: string[]; warnings?: string[]; info?: Record<string, unknown> } | null;
}

export async function getSlideTemplatePackagesAction(): Promise<{ success: boolean; slideTemplates?: SlideTemplateLibraryItem[]; error?: string }> {
  try {
    const supabase = await createClient();
    if (!await getAuthenticatedUser(supabase)) return { success: false, error: "Unauthorized" };
    const organizationId = await resolveOrganizationId();
    if (!organizationId) return { success: true, slideTemplates: [] };
    const admin = getServiceRoleClient();
    const { data: runs, error } = await admin.from("soflia_bundle_generation_runs")
      .select("id, conversation_id, organization_id, spec_id, status, output_hash, bundle_storage_path, validation_report, error_sanitized, created_at, finished_at")
      .eq("organization_id", organizationId).is("template_id", null).order("created_at", { ascending: false }).limit(80);
    if (error) throw error;
    if (!runs?.length) return { success: true, slideTemplates: [] };
    const conversationIds = [...new Set(runs.map((run: any) => run.conversation_id).filter(Boolean))];
    const specIds = [...new Set(runs.map((run: any) => run.spec_id).filter(Boolean))];
    const [{ data: conversations, error: conversationsError }, { data: specs, error: specsError }] = await Promise.all([
      conversationIds.length ? admin.from("soflia_bundle_conversations").select("id, title").eq("organization_id", organizationId).in("id", conversationIds) : Promise.resolve({ data: [], error: null }),
      specIds.length ? admin.from("soflia_bundle_specs").select("id, spec_json").eq("organization_id", organizationId).in("id", specIds) : Promise.resolve({ data: [], error: null }),
    ]);
    if (conversationsError) throw conversationsError;
    if (specsError) throw specsError;
    const conversationsById = new Map((conversations || []).map((row: any) => [row.id, row]));
    const specsById = new Map((specs || []).map((row: any) => [row.id, row]));
    return { success: true, slideTemplates: runs.flatMap((run: any) => {
      const specJson = specsById.get(run.spec_id)?.spec_json;
      if (!isSlideTemplateRun(run, specJson)) return [];
      const spec = asRecord(specJson);
      const conversation = conversationsById.get(run.conversation_id);
      const imported = importedSlideDesignSchema.safeParse(spec?.importedDesign);
      return [{ id: run.id, conversation_id: run.conversation_id, organization_id: run.organization_id, spec_id: run.spec_id || null,
        design_base_run_id: typeof asRecord(spec?.designBase)?.runId === "string" ? spec!.designBase.runId : null,
        imported: imported.success,
        preview_url: imported.success && imported.data.editingMode === "html-text" ? `/api/production/slides/templates/${run.id}/preview` : null,
        preview_html: imported.success && imported.data.editingMode !== "html-text" ? importedDesignPreview(imported.data, 0) : null,
        title: typeof spec?.title === "string" ? spec.title : conversation?.title || "Plantilla de slides", description: typeof spec?.description === "string" ? spec.description : null,
        package_id: typeof spec?.packageId === "string" ? spec.packageId : null, status: run.status, bundle_storage_path: run.bundle_storage_path || null, output_hash: run.output_hash || null,
        error_sanitized: run.error_sanitized || null, created_at: run.created_at, finished_at: run.finished_at || null,
        layouts: imported.success ? imported.data.layouts.map(layout => layout.label) : getLayouts(specJson),
        example_slide_count: imported.success ? imported.data.layouts.length : getExampleCount(specJson),
        preview_design: getPreviewDesign(specJson), preview_slides: getPreviewSlides(specJson), runtime_canvas: getCanvas(specJson), validation_report: asRecord(run.validation_report) }];
    }) };
  } catch (error: any) {
    console.error("[SlideTemplateLibrary] Failed to load packages", { message: error instanceof Error ? error.message : "unknown" });
    return { success: false, error: error?.message || "Error al obtener plantillas de slides" };
  }
}

async function resolveOrganizationId(): Promise<string | null> {
  const bridgeUser = await getAuthBridgeUser();
  if (bridgeUser?.active_organization_id) return bridgeUser.active_organization_id;
  if (bridgeUser?.organization_ids?.length) return bridgeUser.organization_ids[0];
  const cookieOrganization = (await getUserOrganizations())[0]?.id;
  if (cookieOrganization) return cookieOrganization;

  // This is only a final fallback. The library must not depend on the profile
  // role lookup, which can be temporarily unavailable while the tenant layout
  // has already authenticated the current request.
  try {
    return (await resolveActiveTenantContext())?.organizationId || null;
  } catch (error) {
    console.warn("[SlideTemplateLibrary] Active tenant lookup unavailable; no organization fallback.");
    return null;
  }
}
function asRecord(value: unknown): Record<string, any> | null { return value && typeof value === "object" && !Array.isArray(value) ? value as Record<string, any> : null; }
function getLayouts(value: unknown): string[] { const spec = asRecord(value); const layouts = asRecord(spec?.templateBlueprint)?.layouts; return Array.isArray(layouts) ? layouts.map((item) => { const row = asRecord(item); return row?.label || row?.id; }).filter((item): item is string => typeof item === "string") : []; }
function getExampleCount(value: unknown): number { const examples = asRecord(value)?.examples; const first = Array.isArray(examples) ? asRecord(examples[0]) : null; return Array.isArray(first?.slides) ? first.slides.length : 0; }
function getPreviewDesign(value: unknown): SlideTemplateLibraryItem["preview_design"] { const tokens = asRecord(asRecord(value)?.templateBlueprint)?.designTokens; const color = (key: string, fallback: string) => typeof tokens?.[key] === "string" && /^#[0-9a-f]{6}$/i.test(tokens[key]) ? tokens[key] : fallback; return { accent: color("accent", "#00D4B3"), accent2: color("accent2", "#2D7D6E"), background: color("background", "#F7FAFC"), muted: color("muted", "#65758B"), surface: color("surface", "#FFFFFF"), text: color("text", "#0A2540") }; }
function getPreviewSlides(value: unknown): SlideTemplateLibraryItem["preview_slides"] { const examples = asRecord(value)?.examples; const slides = Array.isArray(examples) ? asRecord(examples[0])?.slides : []; return Array.isArray(slides) ? slides.slice(0, 4).map((slide, index) => { const row = asRecord(slide) || {}; const hints = asRecord(row.renderHints); const chart = asRecord(row.chart); return { body_items: Array.isArray(row.bodyBlocks) ? row.bodyBlocks.flatMap((block: unknown) => { const body = asRecord(block); return Array.isArray(body?.items) ? body.items.filter((item: unknown): item is string => typeof item === "string") : typeof body?.text === "string" ? [body.text] : []; }).slice(0, 4) : [], chart_points: Array.isArray(chart?.points) ? chart.points.map((point: unknown) => asRecord(point)?.value).filter((point: unknown): point is number => typeof point === "number" && Number.isFinite(point)).slice(0, 4) : [], layout: typeof hints?.layout === "string" ? hints.layout : null, order: typeof row.order === "number" ? row.order : index + 1, subtitle: typeof row.subtitle === "string" ? row.subtitle : null, title: typeof row.title === "string" ? row.title : `Slide ${index + 1}`, type: typeof row.type === "string" ? row.type : "slide" }; }) : []; }
function getCanvas(value: unknown): SlideTemplateLibraryItem["runtime_canvas"] { const canvas = asRecord(asRecord(asRecord(value)?.templateManifest)?.runtime)?.canvas; return typeof canvas?.width === "number" && typeof canvas?.height === "number" && typeof canvas?.aspectRatio === "string" ? { width: canvas.width, height: canvas.height, aspectRatio: canvas.aspectRatio } : null; }
function isSlideTemplateRun(run: Record<string, any>, specJson: unknown): boolean { return asRecord(asRecord(run.validation_report)?.info)?.artifactKind === "slide_template" || asRecord(specJson)?.artifactKind === "slide_template"; }

import type { SupabaseClient } from "@supabase/supabase-js";
import { createHash, randomUUID } from "node:crypto";
import { z } from "zod";

/** Preview URLs are deliberately much shorter lived than render-delivery URLs. */
export const SOUND_EFFECT_PREVIEW_URL_TTL_SECONDS = 5 * 60;

export const soundEffectCategorySchema = z.enum([
  "TRANSITION",
  "EMPHASIS",
  "UI",
  "IMPACT",
  "AMBIENCE",
  "OTHER",
]);

export const soundEffectLibraryQuerySchema = z.object({
  category: soundEffectCategorySchema.optional(),
  limit: z.coerce.number().int().min(1).max(50).default(25),
  query: z.string().trim().max(120).optional(),
});

export const linkSoundEffectToDraftSchema = z.object({
  draftId: z.string().uuid(),
  soundEffectAssetId: z.string().uuid(),
}).strict();

export class SoundEffectLibraryError extends Error {
  constructor(message: string, readonly status = 400) {
    super(message);
  }
}

export const uploadSoundEffectSchema = z.object({
  category: soundEffectCategorySchema,
  description: z.string().trim().max(1000).default(""),
  licenseReference: z.string().trim().max(1000).optional(),
  licenseType: z.string().trim().min(1).max(80).default("INTERNAL"),
  name: z.string().trim().min(1).max(160),
  tags: z.array(z.string().trim().min(1).max(40)).max(20).default([]),
}).strict();

/**
 * Experimental ingestion deliberately accepts WAV only: its duration can be
 * verified locally and deterministically without trusting browser metadata or
 * introducing a media-processing dependency into the request path.
 */
export async function uploadVerifiedWavSoundEffect(params: {
  bytes: Uint8Array;
  input: z.infer<typeof uploadSoundEffectSchema>;
  organizationId: string;
  supabase: SupabaseClient<any, "public", any>;
  userId: string;
}) {
  if (params.bytes.byteLength === 0 || params.bytes.byteLength > 25 * 1024 * 1024) {
    throw new SoundEffectLibraryError("El archivo debe pesar entre 1 byte y 25 MB.");
  }
  const durationMilliseconds = inspectWavDurationMilliseconds(params.bytes);
  if (durationMilliseconds > 30_000) {
    throw new SoundEffectLibraryError("Un efecto de sonido no puede durar más de 30 segundos.");
  }
  const checksum = createHash("sha256").update(params.bytes).digest("hex");
  const { data: existing, error: existingError } = await params.supabase
    .from("sound_effect_assets")
    .select("id")
    .eq("organization_id", params.organizationId)
    .eq("checksum_sha256", checksum)
    .maybeSingle();
  if (existingError) throw existingError;
  if (existing) throw new SoundEffectLibraryError("Este mismo archivo ya existe en la biblioteca.", 409);

  const storagePath = `organizations/${params.organizationId}/${randomUUID()}/${checksum}.wav`;
  const { error: uploadError } = await params.supabase.storage
    .from("sound-effect-assets")
    .upload(storagePath, params.bytes, { contentType: "audio/wav", upsert: false });
  if (uploadError) throw uploadError;
  const { data, error } = await params.supabase.from("sound_effect_assets").insert({
    category: params.input.category,
    checksum_sha256: checksum,
    created_by: params.userId,
    description: params.input.description,
    duration_milliseconds: durationMilliseconds,
    file_size_bytes: params.bytes.byteLength,
    license_reference: params.input.licenseReference || null,
    license_type: params.input.licenseType,
    mime_type: "audio/wav",
    name: params.input.name,
    organization_id: params.organizationId,
    status: "READY",
    storage_bucket: "sound-effect-assets",
    storage_path: storagePath,
    tags: normalizeTags(params.input.tags),
  }).select("id, name, category, duration_milliseconds").single();
  if (error) {
    // The object is private and inaccessible without a database record. Leave
    // it for a bounded storage-orphan cleanup job rather than risking a delete
    // race against a retried request.
    throw error;
  }
  return {
    category: data.category,
    durationMilliseconds: data.duration_milliseconds,
    id: data.id,
    name: data.name,
  };
}

/** Lists only READY assets; file paths and signed URLs never reach the editor catalogue. */
export async function listReadySoundEffects(params: {
  filters: z.infer<typeof soundEffectLibraryQuerySchema>;
  organizationId: string;
  supabase: SupabaseClient<any, "public", any>;
}) {
  let request = params.supabase
    .from("sound_effect_assets")
    .select("id, name, description, category, tags, duration_milliseconds, mime_type, license_type, attribution_text")
    .eq("organization_id", params.organizationId)
    .eq("status", "READY")
    .order("created_at", { ascending: false })
    .limit(params.filters.limit);
  if (params.filters.category) request = request.eq("category", params.filters.category);
  if (params.filters.query) {
    const query = escapePostgrestSearch(params.filters.query);
    request = request.or(`name.ilike.%${query}%,description.ilike.%${query}%`);
  }
  const { data, error } = await request;
  if (error) throw error;
  return (data || []).map((asset) => ({
    attributionText: asset.attribution_text || null,
    category: asset.category,
    description: asset.description,
    durationMilliseconds: asset.duration_milliseconds,
    id: asset.id,
    licenseType: asset.license_type,
    mimeType: asset.mime_type,
    name: asset.name,
    tags: asset.tags || [],
  }));
}

/** Resolves only the private Storage identity of a READY, tenant-owned effect. */
export async function getReadySoundEffectStorageIdentity(params: {
  organizationId: string;
  soundEffectAssetId: string;
  supabase: SupabaseClient<any, "public", any>;
}) {
  const { data, error } = await params.supabase
    .from("sound_effect_assets")
    .select("storage_bucket, storage_path")
    .eq("id", params.soundEffectAssetId)
    .eq("organization_id", params.organizationId)
    .eq("status", "READY")
    .maybeSingle();
  if (error) throw error;
  if (!data?.storage_bucket || !data.storage_path) {
    throw new SoundEffectLibraryError("El efecto de sonido no está disponible para preescucha.", 404);
  }
  return { storageBucket: data.storage_bucket, storagePath: data.storage_path };
}

/** Links a READY organization asset to a draft before it may enter the document. */
export async function linkReadySoundEffectToDraft(params: {
  draftId: string;
  organizationId: string;
  soundEffectAssetId: string;
  supabase: SupabaseClient<any, "public", any>;
}) {
  const [{ data: draft, error: draftError }, { data: asset, error: assetError }] = await Promise.all([
    params.supabase.from("video_composition_drafts").select("id").eq("id", params.draftId).eq("organization_id", params.organizationId).eq("state", "ACTIVE").maybeSingle(),
    params.supabase.from("sound_effect_assets").select("id, duration_milliseconds, name").eq("id", params.soundEffectAssetId).eq("organization_id", params.organizationId).eq("status", "READY").maybeSingle(),
  ]);
  if (draftError) throw draftError;
  if (assetError) throw assetError;
  if (!draft) throw new SoundEffectLibraryError("El borrador no está disponible para editar.", 409);
  if (!asset) throw new SoundEffectLibraryError("El efecto de sonido no existe o no está listo.", 404);
  const { error: linkError } = await params.supabase
    .from("video_composition_draft_sound_effect_assets")
    .upsert({ draft_id: params.draftId, organization_id: params.organizationId, sound_effect_asset_id: params.soundEffectAssetId }, { onConflict: "draft_id,sound_effect_asset_id" });
  if (linkError) throw linkError;
  return { durationMilliseconds: asset.duration_milliseconds, id: asset.id, name: asset.name };
}

function escapePostgrestSearch(value: string) {
  return value.replace(/[%,()]/g, " ").replace(/\s+/g, " ").trim();
}

function normalizeTags(tags: string[]) {
  return [...new Set(tags.map((tag) => tag.toLocaleLowerCase("es-MX").replace(/\s+/g, " ").trim()))];
}

function inspectWavDurationMilliseconds(bytes: Uint8Array) {
  const view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
  if (bytes.byteLength < 44 || readAscii(bytes, 0, 4) !== "RIFF" || readAscii(bytes, 8, 4) !== "WAVE") {
    throw new SoundEffectLibraryError("El experimento acepta únicamente archivos WAV RIFF válidos.");
  }
  let byteRate = 0;
  let dataBytes = 0;
  let offset = 12;
  while (offset + 8 <= bytes.byteLength) {
    const chunkId = readAscii(bytes, offset, 4);
    const chunkSize = view.getUint32(offset + 4, true);
    const payloadStart = offset + 8;
    const payloadEnd = payloadStart + chunkSize;
    if (payloadEnd > bytes.byteLength) throw new SoundEffectLibraryError("El archivo WAV está truncado.");
    if (chunkId === "fmt " && chunkSize >= 16) byteRate = view.getUint32(payloadStart + 8, true);
    if (chunkId === "data") dataBytes = chunkSize;
    if (byteRate > 0 && dataBytes > 0) break;
    offset = payloadEnd + (chunkSize % 2);
  }
  if (!byteRate || !dataBytes) throw new SoundEffectLibraryError("El WAV no contiene datos de audio válidos.");
  return Math.max(1, Math.round((dataBytes / byteRate) * 1000));
}

function readAscii(bytes: Uint8Array, start: number, length: number) {
  return String.fromCharCode(...bytes.slice(start, start + length));
}

